INSERT INTO ts_agent_skill (name, draft_json, published_json, row_version, create_by, update_by, create_time, update_time, publish_time)
VALUES ('action-decision', '{"name": "action-decision", "display_name": "客群行动决策", "description": "回答“接下来可以做什么、优先做谁”：基于已形成的诊断，提出行动对象与优先级建议，并逐条经过适当性、营销排除与权限规则的过滤说明。用户问“怎么经营、先营销谁、下一步做什么”时使用；规则服务未接入时必须如实说明行动对象无法确定，绝不直接指定客户或替代规则判断；只做事实描述请用 fact-analysis。", "instructions": "# 行动决策\\n\\n你要回答：「接下来可以做什么」。行动建议的结构是**漏斗**：从诊断发现的可行动对象出发，经规则逐层收窄，最后只剩可执行的对象。语言模型负责理解\\"应该考虑什么行动\\"，规则系统负责决定\\"谁真的符合行动条件\\"。\\n\\n## 前置链条\\n\\n行动建立在诊断之上。检查上下文里是否已有本轮诊断结论；没有就先调用 **diagnostic-analysis**（它会按需先调用 fact-analysis）。没有诊断证据时，不要凭条件描述直接跳到行动。`tag_stats` 里服务端注入的标签统计是可用的规模与结构事实，可以支撑\\"做谁\\"的判断；但适当性、营销排除与触达规则仍无取数通道，不能据此产出最终名单或优先级分数。\\n\\n## 行动框架\\n\\n1. **候选对象**：从诊断结论中提取可行动人群的形态（如\\"高资产且产品覆盖不足的客户\\"），说明它是**问题画像**，不是客户名单。\\n2. **规则过滤**（漏斗每一层都要有规则出处与人数，见 `references/action-framework.md`）：\\n   适当性规则 → 排除已持有冲突产品 → 营销免打扰/频次规则 → 事件窗口（如近期大额入金）。\\n   每一层过滤都来自规则服务；没有规则服务时，漏斗停在第一层并声明\\"对象数与可执行性无法确定\\"。\\n3. **优先级**：按 `references/priority-rules.md` 排序（价值 × 意愿 × 可触达 × 排除惩罚），输出高/中/低分档，不输出具体客户。\\n4. **行动建议**：动作类型（关注/触达/配置检视）、理由组合、约束条件（执行前须做适当性复核、排除免打扰等）。\\n\\n## 合规红线\\n\\n- 不在输出中指定、列举或暗示具体客户；行动对象只以\\"数量 + 条件画像\\"的形式出现。\\n- 涉及产品的建议必须声明\\"执行前按最新适当性与风险匹配规则复核\\"（见 `references/compliance-boundaries.md`）。\\n- 评分与优先级是未校准排序时，标记为 `HYPOTHESIS`，不得声称收益或转化率。\\n\\n## 输出\\n\\n正文之后以 ```insight-result 块收尾（契约见 `references/result-contract.md`；块内是严格 JSON，字符串里不要用英文双引号）：\\n\\n- 卡片 `action` 段写行动建议与理由组合，`population_fact_id` 指向候选对象人数事实（未接入时为 `null`），`priority` 填 `HIGH`/`MEDIUM`/`LOW`/`NONE`。\\n- 规则未接入时 `status` 至少 `PARTIAL`，`reasons` 写明缺哪条规则链。\\n- `followups` 给出可执行的下一步（如\\"接入适当性规则后重跑以获得可执行对象数\\"）。\\n\\n图表：漏斗类（`funnel`）适合展示逐层收窄——但必须有每一层的真实人数事实且单调递减；缺失时不要画漏斗，用表格或纯文字说明。", "argument_hint": "期望的经营方向或约束（可留空）", "version": "1.1.2", "category": "decision", "user_invocable": true, "disable_model_invocation": false, "allowed_tools": ["Read", "Skill"], "resources": [{"path": "references/action-framework.md", "content": "# 行动框架\\n\\n## 漏斗结构\\n\\n行动对象数从来不是一次跳变的，而是逐层过滤的结果。每一层都写清：规则出处、过滤前人数、过滤后人数。\\n\\n```\\n诊断发现的候选画像（人数 = 服务端事实）\\n        │  ① 适当性过滤（风险等级、投资经历与产品风险匹配）\\n        ▼\\n        │  ② 冲突排除（已持有同类产品 / 近期已成交）\\n        ▼\\n        │  ③ 联系规则（免打扰名单、触达频次上限）\\n        ▼\\n        │  ④ 事件窗口（近期大额入金、产品到期等触发事件）\\n        ▼\\n可执行对象（高/中/低优先级分档）\\n```\\n\\n## 每一层的要求\\n\\n| 层 | 规则来源 | 没有规则服务时 |\\n| --- | --- | --- |\\n| 适当性 | 已发布的适当性/风险匹配规则 | 声明\\"未做适当性过滤，人数不可执行\\" |\\n| 冲突排除 | 持仓数据 + 排除规则 | 声明未排除 |\\n| 联系规则 | 免打扰名单、频次上限 | 声明未过滤联系约束 |\\n| 事件窗口 | 事件数据（入金、到期） | 声明未筛选事件 |\\n\\n**层与层之间的人数必须单调不增**；任何一层人数反增说明口径有错，停下来检查而不是继续输出。\\n\\n## 行动建议的形态\\n\\n```\\n{\\n  \\"action\\": \\"wealth_management_followup\\",     // 动作标识（英文），配一句中文说明\\n  \\"target_form\\": \\"高资产、产品覆盖不足、风险匹配且未免打扰的客户\\",\\n  \\"target_count_fact_id\\": \\"f-action-count\\",   // 对象人数事实；没有时为 null\\n  \\"priority\\": \\"HIGH\\",\\n  \\"reason\\": [\\"近期存在大额资金流入\\", \\"产品覆盖低于同类基准\\", \\"风险等级满足匹配规则\\"],\\n  \\"constraints\\": [\\"执行前再次进行适当性校验\\", \\"排除免打扰与频次超限客户\\"]\\n}\\n```\\n\\n理由（reason）只引用诊断与规则中已出现的证据，不要引入新数据。\\n\\n## 无规则链时的降级\\n\\n本轮若规则服务未接入：\\n\\n- 输出「候选画像 + 需要哪些规则链过滤」，不输出对象人数。\\n- `population_fact_id`、`target_count_fact_id` 为 `null`，`priority` 为 `NONE`，依据用 `HYPOTHESIS` 或干脆不填结论。\\n- 把\\"接入哪条规则链后可以得到什么\\"写进 followups。\\n"}, {"path": "references/compliance-boundaries.md", "content": "# 合规与权限边界\\n\\n## 必须遵守\\n\\n1. **不指定客户**：任何输出都不出现客户号、姓名或可识别个体的信息；行动对象只以条件画像与数量出现。\\n2. **适当性前置**：涉及产品配置的建议，一律声明\\"实际触达前按最新适当性、风险匹配与冷静期规则复核\\"。\\n3. **免打扰优先**：联系规则（免打扰名单、频次上限、投诉记录）是硬过滤；未接入时明说未过滤，并降低结论置信度。\\n4. **权限边界**：行动建议不改变客群条件与方案版本，不代替业务审批；输出是\\"建议\\"，不是\\"指令\\"。\\n5. **不做收益承诺**：不得出现预期收益、转化率、提升幅度等未经校准的数字。\\n\\n## 常见越界与修正\\n\\n| 越界 | 修正 |\\n| --- | --- |\\n| 「先联系这 168 位客户」 | 「符合本轮条件的对象为 168 人（已过适当性与免打扰规则的假设口径为……）」——人数必须有规则出处 |\\n| 「推荐配置 XX 理财，预计提升 AUM 20%」 | 「可在适当性复核后考虑财富管理跟进；收益提升需以实际经营结果为准」 |\\n| 「客户王某某近期有大额入金」 | 「近期大额入金客户 xx 人（若事件数据接入）」 |\\n| 「这个人群风险偏好保守」 | 「风险等级分布未接入；若需要，接入后按风险等级重新分档」 |\\n\\n## 留痕\\n\\n每条行动建议都留下依据链：诊断卡 id → 规则出处 → 人数事实 id。这样业务复核时能一路追溯回原始证据；断链的建议在平台里等同于没有依据。\\n"}, {"path": "references/priority-rules.md", "content": "# 优先级规则\\n\\n## 排序维度\\n\\n| 维度 | 含义 | 数据缺失时 |\\n| --- | --- | --- |\\n| 价值（value_score） | 客户/机会的价值量级 | 不排序或按已知维度排序并声明 |\\n| 意愿（demand_event） | 触发事件与需求信号 | 声明未使用 |\\n| 可触达（channel_reach） | 渠道可用性与历史响应 | 声明未使用 |\\n| 排除惩罚（disturbance_penalty） | 免打扰、频次、投诉史 | 未接入则整体降级 |\\n\\n## 分档\\n\\n- 按综合分分档：高（≥80）/ 中（60~79）/ 低（40~59）/ 不推送（<40，含被排除客户）。\\n- 分档阈值是**未校准的排序假设**：必须标注 `HYPOTHESIS`，不得声称\\"转化率更高\\"。\\n- 分档输出的是**人数**（每档多少人），不是客户明细。\\n\\n## 排序纪律\\n\\n1. 规则过滤先于评分：被适当性或免打扰规则排除的客户不进入评分（不是扣分）。\\n2. 分数构成（weights）必须可复算：权重之和为 1，每一项的来源事实登记在 `derived_from`。\\n3. 缺维度的客户单独成组\\"信息不足\\"，不并入低分档——低分和缺分是两回事。\\n\\n## 输出形态\\n\\n```\\n优先级分布：高 {fact:xx} / 中 {fact:xx} / 低 {fact:xx} / 信息不足 {fact:xx}\\n```\\n\\n（所有人数都必须是服务端事实；没有事实时只描述排序方法，不给分布数字。）\\n"}, {"path": "references/result-contract.md", "content": "# 结果契约（insight-result 块）\\n\\n正文之后必须追加一个 ```insight-result 围栏块，内含一个 JSON 对象。平台会在服务端校验并组装为洞察报告；块缺失或校验失败时只保留正文，图表与卡片不会展示。\\n\\n## JSON 纪律（先看这一节）\\n\\n块内必须是**严格 JSON**，平台直接解析，不接受任何近似写法：\\n\\n- 字符串内部不要出现英文双引号；需要引用词句时用中文引号 `「」` 或 `“”`。未转义的英文双引号是最常见的解析失败原因。\\n- 不要写注释、尾逗号、单引号；换行、反斜杠按 JSON 规则转义（正文段落已写在 JSON 外面，字符串内如需换行用 `\\\\n`）。\\n- 输出块之前自查一遍括号配对与逗号，宁可少写一段文字，也不要产出不合法 JSON。\\n- 块只写一次，放在正文最后；界面会把它从正文中移除，不要把同一份结果重复输出。\\n\\n## 顶层字段\\n\\n| 字段 | 类型 | 说明 |\\n| --- | --- | --- |\\n| `status` | `COMPLETE` / `PARTIAL` / `BLOCKED` | 本轮分析完成度。只有人数可用、其余指标缺失时为 `PARTIAL`；连人数都没有或无法归纳任何事实时为 `BLOCKED` |\\n| `reasons` | string[]（≤6） | 为什么是这个状态：一句话一条，写清缺失了什么 |\\n| `facts` | Fact[]（≤300） | 事实表，见下 |\\n| `cards` | InsightCard[]（1~30） | 五段式洞察卡，见下 |\\n| `charts` | ChartSpec[]（0~30） | 由 chart-intent / chart-atomic 产出的图表 spec；没有可用数据时为 `[]` |\\n| `followups` | string[]（≤10） | 建议的下一步（可运行的技能、可补充的条件、值得关注的方向） |\\n\\n## Fact（事实）\\n\\n| 字段 | 规则 |\\n| --- | --- |\\n| `id` | `f-` 开头小写标识（`f-count`、`f-aum-missing`），全表唯一 |\\n| `metric` | 指标 id（见 metric-catalog），如 `customer_count`、`aum` |\\n| `label` | 中文短标签，如「客群规模」「总资产」 |\\n| `value` | 数值；MISSING/SUPPRESSED 时必须为 `null` |\\n| `unit` | 只能是 `人` `元` `%` `pp` `分` |\\n| `sample_size` | 计算该事实的样本量（整数）。客群人数事实填人数本身；MISSING 填 `null` |\\n| `status` | `AVAILABLE`（有数）/ `SUPPRESSED`（样本太小被抑制）/ `MISSING`（数据未接入） |\\n| `query_id` | 证据来源标记：`cohort.count`（服务端人数）、`catalog.<metric>`（目录中未接入的指标）等 |\\n| `evidence` | 1~10 条来源说明（中文），写清\\"来自服务端核验的什么\\" |\\n| `role` | `OBSERVED`（直接观测）/ `BENCHMARK` / `POST_EXCLUSION` / `DERIVED` |\\n| `denominator_id` | 百分比的分子分母引用；非百分比填 `null` |\\n| `derived_from` | 派生来源事实 id 数组；直接观测填 `[]` |\\n| `exclusions_applied` | 已应用的排除项；未排除填 `[]` |\\n\\n允许登记为 AVAILABLE 的数值只有三类：\\n\\n1. **服务端核验的人数**（`count.value`，`query_id` 用 `cohort.count`）。\\n2. **条件原文中的阈值**（如「转入金额 ≥ 500000 元」中的 500000）。条件阈值事实用最接近的目录指标 id 作 `metric`、条件原文单位作 `unit`，并在 `evidence` 注明「来自服务端核验的圈选条件」——这样正文才能用 `{fact:id}` 安全引用这些数字。\\n3. **`tag_stats` 与 `baseline.tag_stats` 中服务端注入的标签统计**（本节下一小节）。服务端会逐条复核：`query_id` 命中 `tagstat.*`、`benchmark.*`、`diff.*` 的事实，取值必须与注入的统计量一致，否则整条被丢弃；数值统计的 `unit` 必须与注入值相同，未登记单位的标签统计不得登记为 AVAILABLE。\\n\\n除此之外的一切数值都必须来自确定性数据系统，没有就登记 `MISSING`。\\n\\n## 标签统计（tag_stats）与脱敏明细（sample_rows）\\n\\n当用户在左侧标签栏选择了标签并运行技能时，`cohort_context` 会多出两个字段：\\n\\n- `tag_stats`：每个所选标签一条，字段为 `tag_id` / `label` / `tag_type` / `unit` / `unit_source` / `plan_tag` / `status` / `reason` / `sample_size`，以及二选一的 `numeric` 或 `categories`。\\n  - `status` 为 `AVAILABLE` 时才可作为事实来源；`SUPPRESSED`（存在小于 20 人的分类，整组已抑制）、`MISSING`（取数失败或人数漂移）、`UNSUPPORTED`（该标签类型不支持统计）一律登记为 `MISSING` 事实并复述 `reason`。\\n  - `numeric`：`{n, missing, min, max, sum, avg, median}`，`query_id` 用 `tagstat.<tag_id>.<统计名>`（如 `tagstat.812.avg`）。数值已按标签登记的量纲折算到 `unit` 上（比率类已转成百分数，万元量纲已折算成元），**不要**再自行换算。\\n  - `categories`：`[{code, label, count, share}]`，计数用 `tagstat.<tag_id>.cat.<code>`（单位「人」），占比用 `tagstat.<tag_id>.share.<code>`（单位「%」）；占比事实必须带 `denominator_id`（指向人数事实）。分布的单位是固有的，不受该标签是否登记量纲影响。\\n  - `unit` 为 `null` 表示该标签的数值统计没有登记量纲：它的 `numeric` 数字只能用于定性描述与边界说明，**不得**登记为 AVAILABLE 事实；`categories` 的计数与占比不受此限制。\\n  - `plan_tag` 为 `true` 表示该列已被圈选条件截断（例如条件是「AUM ≥ 50 万」，那么 AUM 的均值有偏），结论里必须声明这一点。\\n- `sample_rows`：`{columns, rows, limit, masked, note}`，是所选标签列在客群内的脱敏明细（客户号已打码，最多 100 行）。它只用于观察分布形态与异常值，**不得**据以产出任何个体级结论或精确统计；正式数值一律引用 `tag_stats` 或人数。\\n\\n`stats_note` 非空时说明本轮取数已降级，要在 `boundary` 里如实转述。\\n\\n## 对照客群基准（baseline）\\n\\n当用户在运行技能前选择了「对照客群」时，`cohort_context` 会多出 `baseline`：`{group_id, name, count, tag_stats, stats_note}`。`tag_stats` 的结构与当前客群完全一致，字段含义相同；`plan_tag` 表示该列被对照客群自身的条件截断，做差与结论时要一并声明。`baseline` 是服务端核验的已保存客群，同一批标签列的两套统计可以直接比较。\\n\\n- 对照统计登记为事实时，`query_id` 用 `benchmark.<tag_id>.<统计名>` / `benchmark.<tag_id>.cat.<code>` / `benchmark.<tag_id>.share.<code>`，`role` 填 `BENCHMARK`；取值必须与注入值一致，服务端同样逐条复核。\\n- 客群与对照的差值登记为派生事实：`query_id` 用 `diff.<tag_id>.<统计名>`（数值差，单位与量纲同该统计）、`diff.<tag_id>.cat.<code>`（人数差，单位「人」）、`diff.<tag_id>.share.<code>`（占比差，单位 `pp`）；`role` 填 `DERIVED`，`derived_from` 填两侧事实 id。差值只在两侧同口径（均 AVAILABLE 且单位相同）时成立；只有一侧可用时不得登记差值。\\n- 差异 = 客群值 − 对照值；方向说明（高于/低于）本身不做价值判断，高与低都不等于好与坏。\\n- `baseline.stats_note` 非空时说明对照取数已降级，`comparison` 段与 `boundary` 要如实转述。\\n- 没选对照客群时以上都不适用，`comparison` 段按无基准处理。\\n\\n## Statement（陈述段）\\n\\n`{ text, fact_ids }`：`text` 是中文陈述，事实数值写成 `{fact:id}` 占位符，`fact_ids` 列出本段引用的全部 id。`{fact:}` 只允许引用 AVAILABLE 事实；缺失数据改用自然语言说明。日期、版本号、阈值这类非事实数字可以直接写。\\n\\n## InsightCard（五段式卡片）\\n\\n| 段 | 要求 |\\n| --- | --- |\\n| `facts` | 事实陈述 + 条件复述；引用规模事实 |\\n| `comparison` | `{text, fact_ids, benchmark_fact_ids, difference_fact_ids}`。有对照客群时写清比较对象（名称与人数）与差异事实；没有基准数据时如实写「本轮未接入基准数据，无法对比」并把两个数组填空数组 |\\n| `diagnosis` | `{text, fact_ids, basis}`，`basis ∈ RULE / STAT / HYPOTHESIS`。事实技能只做方法性说明（如「缺少基准，未形成诊断」），basis 用 `RULE`；`statistical_evidence` 填 `null` |\\n| `action` | `{text, fact_ids, population_fact_id, priority}`。不产出行动对象时 `population_fact_id: null`、`priority: \\"NONE\\"` |\\n| `boundary` | `{text, data_as_of, skill_version, sample_fact_id, metric_definitions}`。`text` 写适用边界与缺失影响；`data_as_of` 与 `skill_version` 先写空串（服务端回填）；`sample_fact_id` 填规模事实 id，无人数时写 `\\"\\"`；`metric_definitions` 是本次使用/欠缺的指标口径说明（每条一句话） |\\n\\n## 完整示例\\n\\n```insight-result\\n{\\n  \\"status\\": \\"PARTIAL\\",\\n  \\"reasons\\": [\\n    \\"仅接入服务端核验的客群条件与有效人数，资产、产品与行为指标未接入\\",\\n    \\"缺少基准数据，不产出对比与诊断结论\\"\\n  ],\\n  \\"facts\\": [\\n    {\\n      \\"id\\": \\"f-count\\",\\n      \\"metric\\": \\"customer_count\\",\\n      \\"label\\": \\"客群规模\\",\\n      \\"value\\": 1268,\\n      \\"unit\\": \\"人\\",\\n      \\"sample_size\\": 1268,\\n      \\"status\\": \\"AVAILABLE\\",\\n      \\"query_id\\": \\"cohort.count\\",\\n      \\"evidence\\": [\\"服务端按当前已核验方案统计的人数\\"],\\n      \\"role\\": \\"OBSERVED\\",\\n      \\"denominator_id\\": null,\\n      \\"derived_from\\": [],\\n      \\"exclusions_applied\\": []\\n    },\\n    {\\n      \\"id\\": \\"f-aum-missing\\",\\n      \\"metric\\": \\"aum\\",\\n      \\"label\\": \\"总资产\\",\\n      \\"value\\": null,\\n      \\"unit\\": \\"元\\",\\n      \\"sample_size\\": null,\\n      \\"status\\": \\"MISSING\\",\\n      \\"query_id\\": \\"catalog.aum\\",\\n      \\"evidence\\": [\\"本轮未接入指标取数通道，无法计算总资产\\"],\\n      \\"role\\": \\"OBSERVED\\",\\n      \\"denominator_id\\": null,\\n      \\"derived_from\\": [],\\n      \\"exclusions_applied\\": []\\n    },\\n    {\\n      \\"id\\": \\"f-holding-missing\\",\\n      \\"metric\\": \\"product_holding_rate\\",\\n      \\"label\\": \\"产品持有率\\",\\n      \\"value\\": null,\\n      \\"unit\\": \\"%\\",\\n      \\"sample_size\\": null,\\n      \\"status\\": \\"MISSING\\",\\n      \\"query_id\\": \\"catalog.product_holding_rate\\",\\n      \\"evidence\\": [\\"本轮未接入指标取数通道，无法计算产品持有结构\\"],\\n      \\"role\\": \\"OBSERVED\\",\\n      \\"denominator_id\\": null,\\n      \\"derived_from\\": [],\\n      \\"exclusions_applied\\": []\\n    }\\n  ],\\n  \\"cards\\": [\\n    {\\n      \\"id\\": \\"card-overview\\",\\n      \\"title\\": \\"客群概况\\",\\n      \\"facts\\": {\\n        \\"text\\": \\"本客群由「近30天转入金额至少500000元」且「未持有理财产品」两个条件圈定，共 {fact:f-count}。\\",\\n        \\"fact_ids\\": [\\"f-count\\"]\\n      },\\n      \\"comparison\\": {\\n        \\"text\\": \\"本轮未接入基准数据，无法回答「和同类客户比怎么样」。\\",\\n        \\"fact_ids\\": [],\\n        \\"benchmark_fact_ids\\": [],\\n        \\"difference_fact_ids\\": []\\n      },\\n      \\"diagnosis\\": {\\n        \\"text\\": \\"缺少对比对象与指标数据，本轮未形成诊断；条件的业务含义不等于客户的经营结论。\\",\\n        \\"fact_ids\\": [],\\n        \\"basis\\": \\"RULE\\",\\n        \\"statistical_evidence\\": null\\n      },\\n      \\"action\\": {\\n        \\"text\\": \\"本轮不产出行动对象：既没有客户级产品数据，也没有营销与适当性规则。\\",\\n        \\"fact_ids\\": [],\\n        \\"population_fact_id\\": null,\\n        \\"priority\\": \\"NONE\\"\\n      },\\n      \\"boundary\\": {\\n        \\"text\\": \\"结论仅覆盖客群条件与规模；资产、产品、人口与行为表现均未接入，不能据此推断客户特征或配置缺口。\\",\\n        \\"data_as_of\\": \\"\\",\\n        \\"skill_version\\": \\"\\",\\n        \\"sample_fact_id\\": \\"f-count\\",\\n        \\"metric_definitions\\": [\\n          \\"customer_count：按当前已核验方案服务端统计的客户数\\",\\n          \\"aum：客户名下资产总额，本轮未接入\\",\\n          \\"product_holding_rate：持有指定产品的客户占比，本轮未接入\\"\\n        ]\\n      }\\n    }\\n  ],\\n  \\"charts\\": [\\n    {\\n      \\"schema_version\\": 1,\\n      \\"id\\": \\"chart-scale\\",\\n      \\"title\\": \\"客群规模\\",\\n      \\"kind\\": \\"kpi\\",\\n      \\"intent\\": \\"single_value\\",\\n      \\"unit\\": \\"人\\",\\n      \\"metric_label\\": \\"客户数\\",\\n      \\"series\\": [\\n        {\\n          \\"name\\": \\"客群规模\\",\\n          \\"fact_ids\\": [\\"f-count\\"],\\n          \\"points\\": [{ \\"category\\": \\"客户数\\", \\"column\\": null, \\"fact_id\\": \\"f-count\\", \\"value\\": 1268 }]\\n        }\\n      ],\\n      \\"annotations\\": [],\\n      \\"reconcile\\": [],\\n      \\"zero_baseline\\": true,\\n      \\"orientation\\": \\"vertical\\"\\n    }\\n  ],\\n  \\"followups\\": [\\n    \\"运行 diagnostic-analysis：在接入基准数据后对比同类客群的资产与产品结构\\",\\n    \\"补充产品持有相关条件后再圈选，可缩小到更聚焦的客群\\"\\n  ]\\n}\\n```\\n\\n## 常见错误\\n\\n- 写了「约 1200 人」「近七成」这类未绑定事实的数字——必须用 `{fact:f-count}`。\\n- 把估算或经验值写成事实——宁可 `MISSING`，不可编造。\\n- 用 `{fact:}` 引用 MISSING 事实——面板会拒绝渲染；缺失只做文字说明。\\n- 段内 `text` 引用了 `{fact:id}` 却没写进该段的 `fact_ids`——服务端会按引用自动补齐；引用了不存在或不可用事实的，整卡丢弃。\\n- 图表 spec 引用了 `facts` 中不存在、或数值与事实不一致的 `fact_id`——spec 里的 `value` 必须与事实值完全相等。\\n- 忘了 `insight-result` 块或 JSON 不合法——结果是降级为纯文本，卡片和图表全部丢失。\\n- 给标签统计事实写了 `tagstat.*` 的 `query_id` 却改了数值，或引用了未选择标签、已抑制、未登记单位的统计量——服务端会整条丢弃。\\n- 给对照统计写了 `benchmark.*` / `diff.*` 却自行改数，或对只有一侧可用的统计量造差值——同样整条丢弃。\\n- 把 `sample_rows` 里的明细当成统计口径，或据它写出个体级结论。\\n"}], "skill_md": "---\\nname: \\"action-decision\\"\\ndescription: \\"回答“接下来可以做什么、优先做谁”：基于已形成的诊断，提出行动对象与优先级建议，并逐条经过适当性、营销排除与权限规则的过滤说明。用户问“怎么经营、先营销谁、下一步做什么”时使用；规则服务未接入时必须如实说明行动对象无法确定，绝不直接指定客户或替代规则判断；只做事实描述请用 fact-analysis。\\"\\nargument-hint: \\"期望的经营方向或约束（可留空）\\"\\nuser-invocable: true\\ndisable-model-invocation: false\\nallowed-tools: [\\"Read\\", \\"Skill\\"]\\n---\\n\\n# 行动决策\\n\\n你要回答：「接下来可以做什么」。行动建议的结构是**漏斗**：从诊断发现的可行动对象出发，经规则逐层收窄，最后只剩可执行的对象。语言模型负责理解\\"应该考虑什么行动\\"，规则系统负责决定\\"谁真的符合行动条件\\"。\\n\\n## 前置链条\\n\\n行动建立在诊断之上。检查上下文里是否已有本轮诊断结论；没有就先调用 **diagnostic-analysis**（它会按需先调用 fact-analysis）。没有诊断证据时，不要凭条件描述直接跳到行动。`tag_stats` 里服务端注入的标签统计是可用的规模与结构事实，可以支撑\\"做谁\\"的判断；但适当性、营销排除与触达规则仍无取数通道，不能据此产出最终名单或优先级分数。\\n\\n## 行动框架\\n\\n1. **候选对象**：从诊断结论中提取可行动人群的形态（如\\"高资产且产品覆盖不足的客户\\"），说明它是**问题画像**，不是客户名单。\\n2. **规则过滤**（漏斗每一层都要有规则出处与人数，见 `references/action-framework.md`）：\\n   适当性规则 → 排除已持有冲突产品 → 营销免打扰/频次规则 → 事件窗口（如近期大额入金）。\\n   每一层过滤都来自规则服务；没有规则服务时，漏斗停在第一层并声明\\"对象数与可执行性无法确定\\"。\\n3. **优先级**：按 `references/priority-rules.md` 排序（价值 × 意愿 × 可触达 × 排除惩罚），输出高/中/低分档，不输出具体客户。\\n4. **行动建议**：动作类型（关注/触达/配置检视）、理由组合、约束条件（执行前须做适当性复核、排除免打扰等）。\\n\\n## 合规红线\\n\\n- 不在输出中指定、列举或暗示具体客户；行动对象只以\\"数量 + 条件画像\\"的形式出现。\\n- 涉及产品的建议必须声明\\"执行前按最新适当性与风险匹配规则复核\\"（见 `references/compliance-boundaries.md`）。\\n- 评分与优先级是未校准排序时，标记为 `HYPOTHESIS`，不得声称收益或转化率。\\n\\n## 输出\\n\\n正文之后以 ```insight-result 块收尾（契约见 `references/result-contract.md`；块内是严格 JSON，字符串里不要用英文双引号）：\\n\\n- 卡片 `action` 段写行动建议与理由组合，`population_fact_id` 指向候选对象人数事实（未接入时为 `null`），`priority` 填 `HIGH`/`MEDIUM`/`LOW`/`NONE`。\\n- 规则未接入时 `status` 至少 `PARTIAL`，`reasons` 写明缺哪条规则链。\\n- `followups` 给出可执行的下一步（如\\"接入适当性规则后重跑以获得可执行对象数\\"）。\\n\\n图表：漏斗类（`funnel`）适合展示逐层收窄——但必须有每一层的真实人数事实且单调递减；缺失时不要画漏斗，用表格或纯文字说明。\\n"}', '{"name": "action-decision", "display_name": "客群行动决策", "description": "回答“接下来可以做什么、优先做谁”：基于已形成的诊断，提出行动对象与优先级建议，并逐条经过适当性、营销排除与权限规则的过滤说明。用户问“怎么经营、先营销谁、下一步做什么”时使用；规则服务未接入时必须如实说明行动对象无法确定，绝不直接指定客户或替代规则判断；只做事实描述请用 fact-analysis。", "instructions": "# 行动决策\\n\\n你要回答：「接下来可以做什么」。行动建议的结构是**漏斗**：从诊断发现的可行动对象出发，经规则逐层收窄，最后只剩可执行的对象。语言模型负责理解\\"应该考虑什么行动\\"，规则系统负责决定\\"谁真的符合行动条件\\"。\\n\\n## 前置链条\\n\\n行动建立在诊断之上。检查上下文里是否已有本轮诊断结论；没有就先调用 **diagnostic-analysis**（它会按需先调用 fact-analysis）。没有诊断证据时，不要凭条件描述直接跳到行动。`tag_stats` 里服务端注入的标签统计是可用的规模与结构事实，可以支撑\\"做谁\\"的判断；但适当性、营销排除与触达规则仍无取数通道，不能据此产出最终名单或优先级分数。\\n\\n## 行动框架\\n\\n1. **候选对象**：从诊断结论中提取可行动人群的形态（如\\"高资产且产品覆盖不足的客户\\"），说明它是**问题画像**，不是客户名单。\\n2. **规则过滤**（漏斗每一层都要有规则出处与人数，见 `references/action-framework.md`）：\\n   适当性规则 → 排除已持有冲突产品 → 营销免打扰/频次规则 → 事件窗口（如近期大额入金）。\\n   每一层过滤都来自规则服务；没有规则服务时，漏斗停在第一层并声明\\"对象数与可执行性无法确定\\"。\\n3. **优先级**：按 `references/priority-rules.md` 排序（价值 × 意愿 × 可触达 × 排除惩罚），输出高/中/低分档，不输出具体客户。\\n4. **行动建议**：动作类型（关注/触达/配置检视）、理由组合、约束条件（执行前须做适当性复核、排除免打扰等）。\\n\\n## 合规红线\\n\\n- 不在输出中指定、列举或暗示具体客户；行动对象只以\\"数量 + 条件画像\\"的形式出现。\\n- 涉及产品的建议必须声明\\"执行前按最新适当性与风险匹配规则复核\\"（见 `references/compliance-boundaries.md`）。\\n- 评分与优先级是未校准排序时，标记为 `HYPOTHESIS`，不得声称收益或转化率。\\n\\n## 输出\\n\\n正文之后以 ```insight-result 块收尾（契约见 `references/result-contract.md`；块内是严格 JSON，字符串里不要用英文双引号）：\\n\\n- 卡片 `action` 段写行动建议与理由组合，`population_fact_id` 指向候选对象人数事实（未接入时为 `null`），`priority` 填 `HIGH`/`MEDIUM`/`LOW`/`NONE`。\\n- 规则未接入时 `status` 至少 `PARTIAL`，`reasons` 写明缺哪条规则链。\\n- `followups` 给出可执行的下一步（如\\"接入适当性规则后重跑以获得可执行对象数\\"）。\\n\\n图表：漏斗类（`funnel`）适合展示逐层收窄——但必须有每一层的真实人数事实且单调递减；缺失时不要画漏斗，用表格或纯文字说明。", "argument_hint": "期望的经营方向或约束（可留空）", "version": "1.1.2", "category": "decision", "user_invocable": true, "disable_model_invocation": false, "allowed_tools": ["Read", "Skill"], "resources": [{"path": "references/action-framework.md", "content": "# 行动框架\\n\\n## 漏斗结构\\n\\n行动对象数从来不是一次跳变的，而是逐层过滤的结果。每一层都写清：规则出处、过滤前人数、过滤后人数。\\n\\n```\\n诊断发现的候选画像（人数 = 服务端事实）\\n        │  ① 适当性过滤（风险等级、投资经历与产品风险匹配）\\n        ▼\\n        │  ② 冲突排除（已持有同类产品 / 近期已成交）\\n        ▼\\n        │  ③ 联系规则（免打扰名单、触达频次上限）\\n        ▼\\n        │  ④ 事件窗口（近期大额入金、产品到期等触发事件）\\n        ▼\\n可执行对象（高/中/低优先级分档）\\n```\\n\\n## 每一层的要求\\n\\n| 层 | 规则来源 | 没有规则服务时 |\\n| --- | --- | --- |\\n| 适当性 | 已发布的适当性/风险匹配规则 | 声明\\"未做适当性过滤，人数不可执行\\" |\\n| 冲突排除 | 持仓数据 + 排除规则 | 声明未排除 |\\n| 联系规则 | 免打扰名单、频次上限 | 声明未过滤联系约束 |\\n| 事件窗口 | 事件数据（入金、到期） | 声明未筛选事件 |\\n\\n**层与层之间的人数必须单调不增**；任何一层人数反增说明口径有错，停下来检查而不是继续输出。\\n\\n## 行动建议的形态\\n\\n```\\n{\\n  \\"action\\": \\"wealth_management_followup\\",     // 动作标识（英文），配一句中文说明\\n  \\"target_form\\": \\"高资产、产品覆盖不足、风险匹配且未免打扰的客户\\",\\n  \\"target_count_fact_id\\": \\"f-action-count\\",   // 对象人数事实；没有时为 null\\n  \\"priority\\": \\"HIGH\\",\\n  \\"reason\\": [\\"近期存在大额资金流入\\", \\"产品覆盖低于同类基准\\", \\"风险等级满足匹配规则\\"],\\n  \\"constraints\\": [\\"执行前再次进行适当性校验\\", \\"排除免打扰与频次超限客户\\"]\\n}\\n```\\n\\n理由（reason）只引用诊断与规则中已出现的证据，不要引入新数据。\\n\\n## 无规则链时的降级\\n\\n本轮若规则服务未接入：\\n\\n- 输出「候选画像 + 需要哪些规则链过滤」，不输出对象人数。\\n- `population_fact_id`、`target_count_fact_id` 为 `null`，`priority` 为 `NONE`，依据用 `HYPOTHESIS` 或干脆不填结论。\\n- 把\\"接入哪条规则链后可以得到什么\\"写进 followups。\\n"}, {"path": "references/compliance-boundaries.md", "content": "# 合规与权限边界\\n\\n## 必须遵守\\n\\n1. **不指定客户**：任何输出都不出现客户号、姓名或可识别个体的信息；行动对象只以条件画像与数量出现。\\n2. **适当性前置**：涉及产品配置的建议，一律声明\\"实际触达前按最新适当性、风险匹配与冷静期规则复核\\"。\\n3. **免打扰优先**：联系规则（免打扰名单、频次上限、投诉记录）是硬过滤；未接入时明说未过滤，并降低结论置信度。\\n4. **权限边界**：行动建议不改变客群条件与方案版本，不代替业务审批；输出是\\"建议\\"，不是\\"指令\\"。\\n5. **不做收益承诺**：不得出现预期收益、转化率、提升幅度等未经校准的数字。\\n\\n## 常见越界与修正\\n\\n| 越界 | 修正 |\\n| --- | --- |\\n| 「先联系这 168 位客户」 | 「符合本轮条件的对象为 168 人（已过适当性与免打扰规则的假设口径为……）」——人数必须有规则出处 |\\n| 「推荐配置 XX 理财，预计提升 AUM 20%」 | 「可在适当性复核后考虑财富管理跟进；收益提升需以实际经营结果为准」 |\\n| 「客户王某某近期有大额入金」 | 「近期大额入金客户 xx 人（若事件数据接入）」 |\\n| 「这个人群风险偏好保守」 | 「风险等级分布未接入；若需要，接入后按风险等级重新分档」 |\\n\\n## 留痕\\n\\n每条行动建议都留下依据链：诊断卡 id → 规则出处 → 人数事实 id。这样业务复核时能一路追溯回原始证据；断链的建议在平台里等同于没有依据。\\n"}, {"path": "references/priority-rules.md", "content": "# 优先级规则\\n\\n## 排序维度\\n\\n| 维度 | 含义 | 数据缺失时 |\\n| --- | --- | --- |\\n| 价值（value_score） | 客户/机会的价值量级 | 不排序或按已知维度排序并声明 |\\n| 意愿（demand_event） | 触发事件与需求信号 | 声明未使用 |\\n| 可触达（channel_reach） | 渠道可用性与历史响应 | 声明未使用 |\\n| 排除惩罚（disturbance_penalty） | 免打扰、频次、投诉史 | 未接入则整体降级 |\\n\\n## 分档\\n\\n- 按综合分分档：高（≥80）/ 中（60~79）/ 低（40~59）/ 不推送（<40，含被排除客户）。\\n- 分档阈值是**未校准的排序假设**：必须标注 `HYPOTHESIS`，不得声称\\"转化率更高\\"。\\n- 分档输出的是**人数**（每档多少人），不是客户明细。\\n\\n## 排序纪律\\n\\n1. 规则过滤先于评分：被适当性或免打扰规则排除的客户不进入评分（不是扣分）。\\n2. 分数构成（weights）必须可复算：权重之和为 1，每一项的来源事实登记在 `derived_from`。\\n3. 缺维度的客户单独成组\\"信息不足\\"，不并入低分档——低分和缺分是两回事。\\n\\n## 输出形态\\n\\n```\\n优先级分布：高 {fact:xx} / 中 {fact:xx} / 低 {fact:xx} / 信息不足 {fact:xx}\\n```\\n\\n（所有人数都必须是服务端事实；没有事实时只描述排序方法，不给分布数字。）\\n"}, {"path": "references/result-contract.md", "content": "# 结果契约（insight-result 块）\\n\\n正文之后必须追加一个 ```insight-result 围栏块，内含一个 JSON 对象。平台会在服务端校验并组装为洞察报告；块缺失或校验失败时只保留正文，图表与卡片不会展示。\\n\\n## JSON 纪律（先看这一节）\\n\\n块内必须是**严格 JSON**，平台直接解析，不接受任何近似写法：\\n\\n- 字符串内部不要出现英文双引号；需要引用词句时用中文引号 `「」` 或 `“”`。未转义的英文双引号是最常见的解析失败原因。\\n- 不要写注释、尾逗号、单引号；换行、反斜杠按 JSON 规则转义（正文段落已写在 JSON 外面，字符串内如需换行用 `\\\\n`）。\\n- 输出块之前自查一遍括号配对与逗号，宁可少写一段文字，也不要产出不合法 JSON。\\n- 块只写一次，放在正文最后；界面会把它从正文中移除，不要把同一份结果重复输出。\\n\\n## 顶层字段\\n\\n| 字段 | 类型 | 说明 |\\n| --- | --- | --- |\\n| `status` | `COMPLETE` / `PARTIAL` / `BLOCKED` | 本轮分析完成度。只有人数可用、其余指标缺失时为 `PARTIAL`；连人数都没有或无法归纳任何事实时为 `BLOCKED` |\\n| `reasons` | string[]（≤6） | 为什么是这个状态：一句话一条，写清缺失了什么 |\\n| `facts` | Fact[]（≤300） | 事实表，见下 |\\n| `cards` | InsightCard[]（1~30） | 五段式洞察卡，见下 |\\n| `charts` | ChartSpec[]（0~30） | 由 chart-intent / chart-atomic 产出的图表 spec；没有可用数据时为 `[]` |\\n| `followups` | string[]（≤10） | 建议的下一步（可运行的技能、可补充的条件、值得关注的方向） |\\n\\n## Fact（事实）\\n\\n| 字段 | 规则 |\\n| --- | --- |\\n| `id` | `f-` 开头小写标识（`f-count`、`f-aum-missing`），全表唯一 |\\n| `metric` | 指标 id（见 metric-catalog），如 `customer_count`、`aum` |\\n| `label` | 中文短标签，如「客群规模」「总资产」 |\\n| `value` | 数值；MISSING/SUPPRESSED 时必须为 `null` |\\n| `unit` | 只能是 `人` `元` `%` `pp` `分` |\\n| `sample_size` | 计算该事实的样本量（整数）。客群人数事实填人数本身；MISSING 填 `null` |\\n| `status` | `AVAILABLE`（有数）/ `SUPPRESSED`（样本太小被抑制）/ `MISSING`（数据未接入） |\\n| `query_id` | 证据来源标记：`cohort.count`（服务端人数）、`catalog.<metric>`（目录中未接入的指标）等 |\\n| `evidence` | 1~10 条来源说明（中文），写清\\"来自服务端核验的什么\\" |\\n| `role` | `OBSERVED`（直接观测）/ `BENCHMARK` / `POST_EXCLUSION` / `DERIVED` |\\n| `denominator_id` | 百分比的分子分母引用；非百分比填 `null` |\\n| `derived_from` | 派生来源事实 id 数组；直接观测填 `[]` |\\n| `exclusions_applied` | 已应用的排除项；未排除填 `[]` |\\n\\n允许登记为 AVAILABLE 的数值只有三类：\\n\\n1. **服务端核验的人数**（`count.value`，`query_id` 用 `cohort.count`）。\\n2. **条件原文中的阈值**（如「转入金额 ≥ 500000 元」中的 500000）。条件阈值事实用最接近的目录指标 id 作 `metric`、条件原文单位作 `unit`，并在 `evidence` 注明「来自服务端核验的圈选条件」——这样正文才能用 `{fact:id}` 安全引用这些数字。\\n3. **`tag_stats` 与 `baseline.tag_stats` 中服务端注入的标签统计**（本节下一小节）。服务端会逐条复核：`query_id` 命中 `tagstat.*`、`benchmark.*`、`diff.*` 的事实，取值必须与注入的统计量一致，否则整条被丢弃；数值统计的 `unit` 必须与注入值相同，未登记单位的标签统计不得登记为 AVAILABLE。\\n\\n除此之外的一切数值都必须来自确定性数据系统，没有就登记 `MISSING`。\\n\\n## 标签统计（tag_stats）与脱敏明细（sample_rows）\\n\\n当用户在左侧标签栏选择了标签并运行技能时，`cohort_context` 会多出两个字段：\\n\\n- `tag_stats`：每个所选标签一条，字段为 `tag_id` / `label` / `tag_type` / `unit` / `unit_source` / `plan_tag` / `status` / `reason` / `sample_size`，以及二选一的 `numeric` 或 `categories`。\\n  - `status` 为 `AVAILABLE` 时才可作为事实来源；`SUPPRESSED`（存在小于 20 人的分类，整组已抑制）、`MISSING`（取数失败或人数漂移）、`UNSUPPORTED`（该标签类型不支持统计）一律登记为 `MISSING` 事实并复述 `reason`。\\n  - `numeric`：`{n, missing, min, max, sum, avg, median}`，`query_id` 用 `tagstat.<tag_id>.<统计名>`（如 `tagstat.812.avg`）。数值已按标签登记的量纲折算到 `unit` 上（比率类已转成百分数，万元量纲已折算成元），**不要**再自行换算。\\n  - `categories`：`[{code, label, count, share}]`，计数用 `tagstat.<tag_id>.cat.<code>`（单位「人」），占比用 `tagstat.<tag_id>.share.<code>`（单位「%」）；占比事实必须带 `denominator_id`（指向人数事实）。分布的单位是固有的，不受该标签是否登记量纲影响。\\n  - `unit` 为 `null` 表示该标签的数值统计没有登记量纲：它的 `numeric` 数字只能用于定性描述与边界说明，**不得**登记为 AVAILABLE 事实；`categories` 的计数与占比不受此限制。\\n  - `plan_tag` 为 `true` 表示该列已被圈选条件截断（例如条件是「AUM ≥ 50 万」，那么 AUM 的均值有偏），结论里必须声明这一点。\\n- `sample_rows`：`{columns, rows, limit, masked, note}`，是所选标签列在客群内的脱敏明细（客户号已打码，最多 100 行）。它只用于观察分布形态与异常值，**不得**据以产出任何个体级结论或精确统计；正式数值一律引用 `tag_stats` 或人数。\\n\\n`stats_note` 非空时说明本轮取数已降级，要在 `boundary` 里如实转述。\\n\\n## 对照客群基准（baseline）\\n\\n当用户在运行技能前选择了「对照客群」时，`cohort_context` 会多出 `baseline`：`{group_id, name, count, tag_stats, stats_note}`。`tag_stats` 的结构与当前客群完全一致，字段含义相同；`plan_tag` 表示该列被对照客群自身的条件截断，做差与结论时要一并声明。`baseline` 是服务端核验的已保存客群，同一批标签列的两套统计可以直接比较。\\n\\n- 对照统计登记为事实时，`query_id` 用 `benchmark.<tag_id>.<统计名>` / `benchmark.<tag_id>.cat.<code>` / `benchmark.<tag_id>.share.<code>`，`role` 填 `BENCHMARK`；取值必须与注入值一致，服务端同样逐条复核。\\n- 客群与对照的差值登记为派生事实：`query_id` 用 `diff.<tag_id>.<统计名>`（数值差，单位与量纲同该统计）、`diff.<tag_id>.cat.<code>`（人数差，单位「人」）、`diff.<tag_id>.share.<code>`（占比差，单位 `pp`）；`role` 填 `DERIVED`，`derived_from` 填两侧事实 id。差值只在两侧同口径（均 AVAILABLE 且单位相同）时成立；只有一侧可用时不得登记差值。\\n- 差异 = 客群值 − 对照值；方向说明（高于/低于）本身不做价值判断，高与低都不等于好与坏。\\n- `baseline.stats_note` 非空时说明对照取数已降级，`comparison` 段与 `boundary` 要如实转述。\\n- 没选对照客群时以上都不适用，`comparison` 段按无基准处理。\\n\\n## Statement（陈述段）\\n\\n`{ text, fact_ids }`：`text` 是中文陈述，事实数值写成 `{fact:id}` 占位符，`fact_ids` 列出本段引用的全部 id。`{fact:}` 只允许引用 AVAILABLE 事实；缺失数据改用自然语言说明。日期、版本号、阈值这类非事实数字可以直接写。\\n\\n## InsightCard（五段式卡片）\\n\\n| 段 | 要求 |\\n| --- | --- |\\n| `facts` | 事实陈述 + 条件复述；引用规模事实 |\\n| `comparison` | `{text, fact_ids, benchmark_fact_ids, difference_fact_ids}`。有对照客群时写清比较对象（名称与人数）与差异事实；没有基准数据时如实写「本轮未接入基准数据，无法对比」并把两个数组填空数组 |\\n| `diagnosis` | `{text, fact_ids, basis}`，`basis ∈ RULE / STAT / HYPOTHESIS`。事实技能只做方法性说明（如「缺少基准，未形成诊断」），basis 用 `RULE`；`statistical_evidence` 填 `null` |\\n| `action` | `{text, fact_ids, population_fact_id, priority}`。不产出行动对象时 `population_fact_id: null`、`priority: \\"NONE\\"` |\\n| `boundary` | `{text, data_as_of, skill_version, sample_fact_id, metric_definitions}`。`text` 写适用边界与缺失影响；`data_as_of` 与 `skill_version` 先写空串（服务端回填）；`sample_fact_id` 填规模事实 id，无人数时写 `\\"\\"`；`metric_definitions` 是本次使用/欠缺的指标口径说明（每条一句话） |\\n\\n## 完整示例\\n\\n```insight-result\\n{\\n  \\"status\\": \\"PARTIAL\\",\\n  \\"reasons\\": [\\n    \\"仅接入服务端核验的客群条件与有效人数，资产、产品与行为指标未接入\\",\\n    \\"缺少基准数据，不产出对比与诊断结论\\"\\n  ],\\n  \\"facts\\": [\\n    {\\n      \\"id\\": \\"f-count\\",\\n      \\"metric\\": \\"customer_count\\",\\n      \\"label\\": \\"客群规模\\",\\n      \\"value\\": 1268,\\n      \\"unit\\": \\"人\\",\\n      \\"sample_size\\": 1268,\\n      \\"status\\": \\"AVAILABLE\\",\\n      \\"query_id\\": \\"cohort.count\\",\\n      \\"evidence\\": [\\"服务端按当前已核验方案统计的人数\\"],\\n      \\"role\\": \\"OBSERVED\\",\\n      \\"denominator_id\\": null,\\n      \\"derived_from\\": [],\\n      \\"exclusions_applied\\": []\\n    },\\n    {\\n      \\"id\\": \\"f-aum-missing\\",\\n      \\"metric\\": \\"aum\\",\\n      \\"label\\": \\"总资产\\",\\n      \\"value\\": null,\\n      \\"unit\\": \\"元\\",\\n      \\"sample_size\\": null,\\n      \\"status\\": \\"MISSING\\",\\n      \\"query_id\\": \\"catalog.aum\\",\\n      \\"evidence\\": [\\"本轮未接入指标取数通道，无法计算总资产\\"],\\n      \\"role\\": \\"OBSERVED\\",\\n      \\"denominator_id\\": null,\\n      \\"derived_from\\": [],\\n      \\"exclusions_applied\\": []\\n    },\\n    {\\n      \\"id\\": \\"f-holding-missing\\",\\n      \\"metric\\": \\"product_holding_rate\\",\\n      \\"label\\": \\"产品持有率\\",\\n      \\"value\\": null,\\n      \\"unit\\": \\"%\\",\\n      \\"sample_size\\": null,\\n      \\"status\\": \\"MISSING\\",\\n      \\"query_id\\": \\"catalog.product_holding_rate\\",\\n      \\"evidence\\": [\\"本轮未接入指标取数通道，无法计算产品持有结构\\"],\\n      \\"role\\": \\"OBSERVED\\",\\n      \\"denominator_id\\": null,\\n      \\"derived_from\\": [],\\n      \\"exclusions_applied\\": []\\n    }\\n  ],\\n  \\"cards\\": [\\n    {\\n      \\"id\\": \\"card-overview\\",\\n      \\"title\\": \\"客群概况\\",\\n      \\"facts\\": {\\n        \\"text\\": \\"本客群由「近30天转入金额至少500000元」且「未持有理财产品」两个条件圈定，共 {fact:f-count}。\\",\\n        \\"fact_ids\\": [\\"f-count\\"]\\n      },\\n      \\"comparison\\": {\\n        \\"text\\": \\"本轮未接入基准数据，无法回答「和同类客户比怎么样」。\\",\\n        \\"fact_ids\\": [],\\n        \\"benchmark_fact_ids\\": [],\\n        \\"difference_fact_ids\\": []\\n      },\\n      \\"diagnosis\\": {\\n        \\"text\\": \\"缺少对比对象与指标数据，本轮未形成诊断；条件的业务含义不等于客户的经营结论。\\",\\n        \\"fact_ids\\": [],\\n        \\"basis\\": \\"RULE\\",\\n        \\"statistical_evidence\\": null\\n      },\\n      \\"action\\": {\\n        \\"text\\": \\"本轮不产出行动对象：既没有客户级产品数据，也没有营销与适当性规则。\\",\\n        \\"fact_ids\\": [],\\n        \\"population_fact_id\\": null,\\n        \\"priority\\": \\"NONE\\"\\n      },\\n      \\"boundary\\": {\\n        \\"text\\": \\"结论仅覆盖客群条件与规模；资产、产品、人口与行为表现均未接入，不能据此推断客户特征或配置缺口。\\",\\n        \\"data_as_of\\": \\"\\",\\n        \\"skill_version\\": \\"\\",\\n        \\"sample_fact_id\\": \\"f-count\\",\\n        \\"metric_definitions\\": [\\n          \\"customer_count：按当前已核验方案服务端统计的客户数\\",\\n          \\"aum：客户名下资产总额，本轮未接入\\",\\n          \\"product_holding_rate：持有指定产品的客户占比，本轮未接入\\"\\n        ]\\n      }\\n    }\\n  ],\\n  \\"charts\\": [\\n    {\\n      \\"schema_version\\": 1,\\n      \\"id\\": \\"chart-scale\\",\\n      \\"title\\": \\"客群规模\\",\\n      \\"kind\\": \\"kpi\\",\\n      \\"intent\\": \\"single_value\\",\\n      \\"unit\\": \\"人\\",\\n      \\"metric_label\\": \\"客户数\\",\\n      \\"series\\": [\\n        {\\n          \\"name\\": \\"客群规模\\",\\n          \\"fact_ids\\": [\\"f-count\\"],\\n          \\"points\\": [{ \\"category\\": \\"客户数\\", \\"column\\": null, \\"fact_id\\": \\"f-count\\", \\"value\\": 1268 }]\\n        }\\n      ],\\n      \\"annotations\\": [],\\n      \\"reconcile\\": [],\\n      \\"zero_baseline\\": true,\\n      \\"orientation\\": \\"vertical\\"\\n    }\\n  ],\\n  \\"followups\\": [\\n    \\"运行 diagnostic-analysis：在接入基准数据后对比同类客群的资产与产品结构\\",\\n    \\"补充产品持有相关条件后再圈选，可缩小到更聚焦的客群\\"\\n  ]\\n}\\n```\\n\\n## 常见错误\\n\\n- 写了「约 1200 人」「近七成」这类未绑定事实的数字——必须用 `{fact:f-count}`。\\n- 把估算或经验值写成事实——宁可 `MISSING`，不可编造。\\n- 用 `{fact:}` 引用 MISSING 事实——面板会拒绝渲染；缺失只做文字说明。\\n- 段内 `text` 引用了 `{fact:id}` 却没写进该段的 `fact_ids`——服务端会按引用自动补齐；引用了不存在或不可用事实的，整卡丢弃。\\n- 图表 spec 引用了 `facts` 中不存在、或数值与事实不一致的 `fact_id`——spec 里的 `value` 必须与事实值完全相等。\\n- 忘了 `insight-result` 块或 JSON 不合法——结果是降级为纯文本，卡片和图表全部丢失。\\n- 给标签统计事实写了 `tagstat.*` 的 `query_id` 却改了数值，或引用了未选择标签、已抑制、未登记单位的统计量——服务端会整条丢弃。\\n- 给对照统计写了 `benchmark.*` / `diff.*` 却自行改数，或对只有一侧可用的统计量造差值——同样整条丢弃。\\n- 把 `sample_rows` 里的明细当成统计口径，或据它写出个体级结论。\\n"}], "skill_md": "---\\nname: \\"action-decision\\"\\ndescription: \\"回答“接下来可以做什么、优先做谁”：基于已形成的诊断，提出行动对象与优先级建议，并逐条经过适当性、营销排除与权限规则的过滤说明。用户问“怎么经营、先营销谁、下一步做什么”时使用；规则服务未接入时必须如实说明行动对象无法确定，绝不直接指定客户或替代规则判断；只做事实描述请用 fact-analysis。\\"\\nargument-hint: \\"期望的经营方向或约束（可留空）\\"\\nuser-invocable: true\\ndisable-model-invocation: false\\nallowed-tools: [\\"Read\\", \\"Skill\\"]\\n---\\n\\n# 行动决策\\n\\n你要回答：「接下来可以做什么」。行动建议的结构是**漏斗**：从诊断发现的可行动对象出发，经规则逐层收窄，最后只剩可执行的对象。语言模型负责理解\\"应该考虑什么行动\\"，规则系统负责决定\\"谁真的符合行动条件\\"。\\n\\n## 前置链条\\n\\n行动建立在诊断之上。检查上下文里是否已有本轮诊断结论；没有就先调用 **diagnostic-analysis**（它会按需先调用 fact-analysis）。没有诊断证据时，不要凭条件描述直接跳到行动。`tag_stats` 里服务端注入的标签统计是可用的规模与结构事实，可以支撑\\"做谁\\"的判断；但适当性、营销排除与触达规则仍无取数通道，不能据此产出最终名单或优先级分数。\\n\\n## 行动框架\\n\\n1. **候选对象**：从诊断结论中提取可行动人群的形态（如\\"高资产且产品覆盖不足的客户\\"），说明它是**问题画像**，不是客户名单。\\n2. **规则过滤**（漏斗每一层都要有规则出处与人数，见 `references/action-framework.md`）：\\n   适当性规则 → 排除已持有冲突产品 → 营销免打扰/频次规则 → 事件窗口（如近期大额入金）。\\n   每一层过滤都来自规则服务；没有规则服务时，漏斗停在第一层并声明\\"对象数与可执行性无法确定\\"。\\n3. **优先级**：按 `references/priority-rules.md` 排序（价值 × 意愿 × 可触达 × 排除惩罚），输出高/中/低分档，不输出具体客户。\\n4. **行动建议**：动作类型（关注/触达/配置检视）、理由组合、约束条件（执行前须做适当性复核、排除免打扰等）。\\n\\n## 合规红线\\n\\n- 不在输出中指定、列举或暗示具体客户；行动对象只以\\"数量 + 条件画像\\"的形式出现。\\n- 涉及产品的建议必须声明\\"执行前按最新适当性与风险匹配规则复核\\"（见 `references/compliance-boundaries.md`）。\\n- 评分与优先级是未校准排序时，标记为 `HYPOTHESIS`，不得声称收益或转化率。\\n\\n## 输出\\n\\n正文之后以 ```insight-result 块收尾（契约见 `references/result-contract.md`；块内是严格 JSON，字符串里不要用英文双引号）：\\n\\n- 卡片 `action` 段写行动建议与理由组合，`population_fact_id` 指向候选对象人数事实（未接入时为 `null`），`priority` 填 `HIGH`/`MEDIUM`/`LOW`/`NONE`。\\n- 规则未接入时 `status` 至少 `PARTIAL`，`reasons` 写明缺哪条规则链。\\n- `followups` 给出可执行的下一步（如\\"接入适当性规则后重跑以获得可执行对象数\\"）。\\n\\n图表：漏斗类（`funnel`）适合展示逐层收窄——但必须有每一层的真实人数事实且单调递减；缺失时不要画漏斗，用表格或纯文字说明。\\n"}', 1, 'seed', 'seed', NOW(), NOW(), NOW())
ON DUPLICATE KEY UPDATE draft_json=VALUES(draft_json), published_json=VALUES(published_json),
  row_version=row_version+1, update_by='seed', update_time=NOW(), publish_time=NOW();

INSERT INTO ts_agent_skill (name, draft_json, published_json, row_version, create_by, update_by, create_time, update_time, publish_time)
VALUES ('diagnostic-analysis', '{"name": "diagnostic-analysis", "display_name": "客群诊断分析", "description": "回答“哪里值得关注、为什么值得关注”：在事实基础上寻找对比对象、量化差异、下钻定位集中方向，并严格区分规则、统计与假设三种依据。运行前若选择了对照客群，用两套服务端统计做差并说明方向；没有基准数据时如实说明无法诊断，绝不把差异说成原因；简单描述现状请用 fact-analysis。", "instructions": "# 诊断分析\\n\\n你要回答：「哪里值得关注」「为什么值得关注」。诊断的前提是**有可比较的对象**——基准、规则或统计检验；没有对比就没有诊断。\\n\\n## 前置事实\\n\\n先检查当前上下文里是否已经有本轮事实（同一次会话中先跑过 fact-analysis 时，提示词里会带有其输出）。没有就先调用 **fact-analysis** 技能补齐事实链，再做诊断——诊断必须建立在同一份事实表上，不能另起一套口径。\\n\\n## 诊断循环\\n\\n1. **读事实**：列出 AS-IS 事实（客群实际值，优先使用 `tag_stats` 里服务端注入的统计）与已声明的缺口。\\n2. **找可比对象**：上下文里有 `baseline`（对照客群）时，它就是本轮基准——对照客群由服务端重新编译并统计，与客群使用同一批标签列，可直接做差；在报告里写清对照客群的名称与人数。没有 `baseline` 时，按 `references/benchmark-selection.md` 逐项检查同类客群、全量客群、同机构、标准化基准，都不具备就明确记录「无基准」，进入第 5 步。`tag_stats`/`baseline.tag_stats` 只覆盖各自客群自身，不能跨客群拼接成本轮之外的基准。\\n3. **量化差异**：差异 = 客群值 − 对照值，登记为 `diff.*` 派生事实（比率类差值单位 `pp`），注明方向（高于/低于）。差异只在两侧口径一致时才成立（同期、同口径、同分母、同单位）；只有一侧可用时不得做差。被条件截断的列（`plan_tag`）要在结论里声明截断影响。\\n4. **下钻定位**（见 `references/drilldown-strategy.md`）：差异集中在哪些子群？按资产层、风险层、机构、产品线逐层看；下钻每一层都需要对应维度数据，数据没有就停下并声明。本轮可选标签有限，无法下钻时如实记录，不得用明细臆测子群差异。\\n5. **形成诊断**（见 `references/diagnosis-boundaries.md`）：每条结论标明依据类型——`RULE`（明确业务规则推导）、`STAT`（统计检验，需附检验方法与区间）、`HYPOTHESIS`（未验证的假设）。**差异 ≠ 原因**：可以说\\"权益类占比均值低于对照客群 X pp\\"，不能说\\"因为客户不喜欢理财\\"。对照客群的位置只是可比对象，不是目标值。\\n\\n## 阈值与显著性\\n\\n- 规则型判断（如\\"低于同类客群 X pp 以上算缺口\\"）要把规则原文写进 `boundary.metric_definitions`。\\n- 统计型判断必须给检验方法与双侧区间（如 Wilson + 多重比较校正），样本不足时降级为 HYPOTHESIS 或不下结论。没有做检验时，只能把差异陈述为观察（事实/派生事实），诊断句用 `HYPOTHESIS` 或规则口径，不得声称\\"显著\\"。\\n- 没有依据时宁可输出「未形成诊断」，也不要输出一个看起来像结论的猜测。\\n\\n## 输出\\n\\n正文之后以 ```insight-result 块收尾，字段与示例见 `references/result-contract.md`（与基础事实技能同一契约；块内是严格 JSON，字符串里不要用英文双引号）。诊断结论写进卡片的 `diagnosis` 段，`basis` 如实填写；`comparison` 段写清比较对象、差异值与方向，`benchmark_fact_ids` 引用 `benchmark.*` 事实、`difference_fact_ids` 引用 `diff.*` 事实；没有基准时才写「本轮未接入基准数据，无法对比」。行动建议只写\\"值得考虑的检验方向\\"，不要产出行动对象（那是 action-decision 的职责）。\\n\\n输出前逐段自查：`text` 里出现的每一个 `{fact:id}` 都必须同时出现在该段的 `fact_ids` 数组里（`comparison` 段的引用也计入 `fact_ids`）；`{fact:}` 只能引用本块 `facts` 中 `status` 为 `AVAILABLE` 的事实。漏登记或引用了不可用事实，该卡片会被服务端整卡丢弃。\\n\\n配图：差异对比适合 `compare_categories` 柱状图（客群与对照两组系列）、结构占比适合 `stacked_bar`、下钻矩阵适合 `heatmap`；调用 chart-intent 判定，不要直接画。没有可展示数值时 `charts` 为 `[]`。", "argument_hint": "要诊断的方向（如：产品配置、资产结构）", "version": "1.2.0", "category": "diagnosis", "user_invocable": true, "disable_model_invocation": false, "allowed_tools": ["Read", "Skill"], "resources": [{"path": "references/benchmark-selection.md", "content": "# 基准选择\\n\\n## 基准来源\\n\\n| 来源 | 说明 | 适用 |\\n| --- | --- | --- |\\n| `baseline` 对照客群（已接入） | 用户在运行前选择的已保存客群，服务端按同一批标签列重新编译并统计；`benchmark.*` 是对照值，`diff.*` 是差值 | 默认来源；在报告里写清对照客群名称与人数 |\\n| `same_aum` | 同资产层级客群 | 防\\"资产规模差异\\"混淆产品行为差异 |\\n| `all_customers` | 全量客户 | 看客群相对全行的位置 |\\n| `same_org` | 同机构（分行/支行） | 排除地域经营差异 |\\n| `standardized` | 标准化基准 | 按 AUM × 风险等级交叉标准化后比较 |\\n\\n优先使用上下文里的 `baseline`——它是本轮唯一可复核的服务端基准。上下文没有 `baseline` 时，`same_aum` / `all_customers` / `same_org` / `standardized` 都是**尚未接入取数通道**的类型：在 `reasons` 中写「缺少基准数据，无法量化差异」，`comparison` 段如实写未接入，`benchmark_fact_ids` 与 `difference_fact_ids` 留空；诊断段只允许规则型结论（规则原文写进边界）。\\n\\n## 可比性检查清单\\n\\n比较前逐条确认，任何一条不满足就要么换基准、要么声明不可比：\\n\\n- **同期**：两侧数据日期一致（`data_as_of` 对齐）。\\n- **同口径**：指标定义一致（分子分母、时间窗口、是否含无资产客户）。\\n- **同分母**：比率类指标的分母口径一致。\\n- **样本充足**：两侧样本都超过抑制阈值（20），统计比较时按检验方法要求更高。\\n- **截断声明**：任一侧该列被自身圈选条件截断（`plan_tag`）时，差异结论必须声明截断影响。\\n\\n## 差异表达\\n\\n- 比率差用 **pp**（百分点）：`48.7% − 23.4% = 25.3pp`；相对差才用 %（`相对低 52%`），两者不能混用。\\n- 金额差注明单位与是否可比期间。\\n- 标注方向：缺口（低于基准）还是溢出（高于基准），并且**方向本身不做价值判断**——高与低都不等于好与坏。\\n- 与对照客群的差异是观察事实；把差异诊断为\\"问题\\"需要规则或检验支撑，`basis` 按依据如实填写。\\n"}, {"path": "references/diagnosis-boundaries.md", "content": "# 诊断边界\\n\\n## 差异 ≠ 原因\\n\\n观察到的差异只说明「不一样」，不说明「为什么不一样」。把差异叙述成因果是诊断环节最常见的越界：\\n\\n- ❌ 「因为客户风险偏好保守，所以理财持有率低」——把相关当因果，且\\"风险偏好保守\\"本身没有证据。\\n- ✅ 「理财持有率较同资产层级低 25.3pp，差异集中在 100~300 万资产段、中高风险承受能力客户」——陈述可复算的观察。\\n- ✅ 「一种可能解释是……，需要 X 数据/检验才能确认」——写成 HYPOTHESIS 并明确验证路径。\\n\\n## 依据类型（basis）\\n\\n| basis | 含义 | 必要条件 |\\n| --- | --- | --- |\\n| `RULE` | 明确业务规则推导 | 规则原文附在边界说明里；规则本身是组织已确认的口径 |\\n| `STAT` | 统计检验结论 | 附检验方法、区间与样本量；区间不重叠才可称\\"显著\\"；多重比较要校正 |\\n| `HYPOTHESIS` | 未验证假设 | 语言必须标明\\"假设/待验证\\"，不得使用断言句式 |\\n\\n评分、排序、预测类内容一律 `HYPOTHESIS`，除非有已发布的评分规则（此时是 `RULE`）。\\n\\n## 统计表达纪律\\n\\n- 区间不重叠 → \\"存在显著差异（方法：Wilson，95% 区间 [19.9%, 30.8%] vs [66.1%, 74.6%]）\\"。\\n- 区间重叠 → 只能说\\"观察到的差异未通过显著性检验\\"，不能暗示趋势。\\n- 样本低于阈值 → 不出结论；把该子群标记为样本不足。\\n- 不得把 RULE 型判断包装成\\"统计显著\\"；也不得把 HYPOTHESIS 写成确定性结论。\\n\\n## 什么时候输出「未形成诊断」\\n\\n以下情形，`status` 至少降为 `PARTIAL`，诊断段如实写未形成诊断与原因：\\n\\n- 没有任何基准或规则可比；\\n- 数据缺口使差异无法量化（如指标未接入）；\\n- 样本不足，差异不可检验。\\n\\n宁可输出\\"未形成诊断 + 检验计划\\"，也不要输出没有依据的结论——报告会被业务直接采信，未验证的猜测可能造成真实的营销与合规损失。\\n"}, {"path": "references/drilldown-strategy.md", "content": "# 下钻策略\\n\\n差异找到后，回答「集中在谁身上」。下钻是逐层的：每层只在数据允许时进行，每层下钻都要保持两侧可比。\\n\\n## 常用下钻维度（按优先级）\\n\\n1. **资产层级** `aum_tier`：差异是否集中在高/低资产段——最常见的混杂因素。\\n2. **风险等级** `risk_level`：产品持有差异常与风险承受能力共线。\\n3. **客户等级** `customer_tier`：存量经营分层。\\n4. **机构** `org_branch`：地域经营差异。\\n5. **时间**：差异是结构性的还是本期事件驱动的。\\n\\n## 方法\\n\\n- 逐层计算「客群值 vs 基准值」的差异，观察差异在哪个子群放大。\\n- 子群样本低于抑制阈值（20）时该格必须抑制（`SUPPRESSED` / 图上 `value: null`），不得展示。\\n- 下钻层数控制在 2~3 层：更深的层通常样本不足，结论会失去统计意义。\\n- 记录每次下钻的过滤条件，保证结论可复算。\\n\\n## 收敛判断\\n\\n- 差异在某个子群显著放大 → 「差异主要集中于……」，这是可下结论的形态。\\n- 差异在各子群均匀 → 说明差异与这些维度无关，换维度或接受\\"未定位到集中方向\\"。\\n- 数据不足以完成下钻 → 在 `reasons` 与 `boundary` 写明缺哪一层的什么数据。\\n\\n## 与事实层的关系\\n\\n下钻产生的新数字同样是事实：要么来自确定性数据系统，要么登记为 MISSING。下钻中临时口算的结果不得写进报告——比率、差值必须由服务端事实承载。\\n"}, {"path": "references/result-contract.md", "content": "# 结果契约（insight-result 块）\\n\\n正文之后必须追加一个 ```insight-result 围栏块，内含一个 JSON 对象。平台会在服务端校验并组装为洞察报告；块缺失或校验失败时只保留正文，图表与卡片不会展示。\\n\\n## JSON 纪律（先看这一节）\\n\\n块内必须是**严格 JSON**，平台直接解析，不接受任何近似写法：\\n\\n- 字符串内部不要出现英文双引号；需要引用词句时用中文引号 `「」` 或 `“”`。未转义的英文双引号是最常见的解析失败原因。\\n- 不要写注释、尾逗号、单引号；换行、反斜杠按 JSON 规则转义（正文段落已写在 JSON 外面，字符串内如需换行用 `\\\\n`）。\\n- 输出块之前自查一遍括号配对与逗号，宁可少写一段文字，也不要产出不合法 JSON。\\n- 块只写一次，放在正文最后；界面会把它从正文中移除，不要把同一份结果重复输出。\\n\\n## 顶层字段\\n\\n| 字段 | 类型 | 说明 |\\n| --- | --- | --- |\\n| `status` | `COMPLETE` / `PARTIAL` / `BLOCKED` | 本轮分析完成度。只有人数可用、其余指标缺失时为 `PARTIAL`；连人数都没有或无法归纳任何事实时为 `BLOCKED` |\\n| `reasons` | string[]（≤6） | 为什么是这个状态：一句话一条，写清缺失了什么 |\\n| `facts` | Fact[]（≤300） | 事实表，见下 |\\n| `cards` | InsightCard[]（1~30） | 五段式洞察卡，见下 |\\n| `charts` | ChartSpec[]（0~30） | 由 chart-intent / chart-atomic 产出的图表 spec；没有可用数据时为 `[]` |\\n| `followups` | string[]（≤10） | 建议的下一步（可运行的技能、可补充的条件、值得关注的方向） |\\n\\n## Fact（事实）\\n\\n| 字段 | 规则 |\\n| --- | --- |\\n| `id` | `f-` 开头小写标识（`f-count`、`f-aum-missing`），全表唯一 |\\n| `metric` | 指标 id（见 metric-catalog），如 `customer_count`、`aum` |\\n| `label` | 中文短标签，如「客群规模」「总资产」 |\\n| `value` | 数值；MISSING/SUPPRESSED 时必须为 `null` |\\n| `unit` | 只能是 `人` `元` `%` `pp` `分` |\\n| `sample_size` | 计算该事实的样本量（整数）。客群人数事实填人数本身；MISSING 填 `null` |\\n| `status` | `AVAILABLE`（有数）/ `SUPPRESSED`（样本太小被抑制）/ `MISSING`（数据未接入） |\\n| `query_id` | 证据来源标记：`cohort.count`（服务端人数）、`catalog.<metric>`（目录中未接入的指标）等 |\\n| `evidence` | 1~10 条来源说明（中文），写清\\"来自服务端核验的什么\\" |\\n| `role` | `OBSERVED`（直接观测）/ `BENCHMARK` / `POST_EXCLUSION` / `DERIVED` |\\n| `denominator_id` | 百分比的分子分母引用；非百分比填 `null` |\\n| `derived_from` | 派生来源事实 id 数组；直接观测填 `[]` |\\n| `exclusions_applied` | 已应用的排除项；未排除填 `[]` |\\n\\n允许登记为 AVAILABLE 的数值只有三类：\\n\\n1. **服务端核验的人数**（`count.value`，`query_id` 用 `cohort.count`）。\\n2. **条件原文中的阈值**（如「转入金额 ≥ 500000 元」中的 500000）。条件阈值事实用最接近的目录指标 id 作 `metric`、条件原文单位作 `unit`，并在 `evidence` 注明「来自服务端核验的圈选条件」——这样正文才能用 `{fact:id}` 安全引用这些数字。\\n3. **`tag_stats` 与 `baseline.tag_stats` 中服务端注入的标签统计**（本节下一小节）。服务端会逐条复核：`query_id` 命中 `tagstat.*`、`benchmark.*`、`diff.*` 的事实，取值必须与注入的统计量一致，否则整条被丢弃；数值统计的 `unit` 必须与注入值相同，未登记单位的标签统计不得登记为 AVAILABLE。\\n\\n除此之外的一切数值都必须来自确定性数据系统，没有就登记 `MISSING`。\\n\\n## 标签统计（tag_stats）与脱敏明细（sample_rows）\\n\\n当用户在左侧标签栏选择了标签并运行技能时，`cohort_context` 会多出两个字段：\\n\\n- `tag_stats`：每个所选标签一条，字段为 `tag_id` / `label` / `tag_type` / `unit` / `unit_source` / `plan_tag` / `status` / `reason` / `sample_size`，以及二选一的 `numeric` 或 `categories`。\\n  - `status` 为 `AVAILABLE` 时才可作为事实来源；`SUPPRESSED`（存在小于 20 人的分类，整组已抑制）、`MISSING`（取数失败或人数漂移）、`UNSUPPORTED`（该标签类型不支持统计）一律登记为 `MISSING` 事实并复述 `reason`。\\n  - `numeric`：`{n, missing, min, max, sum, avg, median}`，`query_id` 用 `tagstat.<tag_id>.<统计名>`（如 `tagstat.812.avg`）。数值已按标签登记的量纲折算到 `unit` 上（比率类已转成百分数，万元量纲已折算成元），**不要**再自行换算。\\n  - `categories`：`[{code, label, count, share}]`，计数用 `tagstat.<tag_id>.cat.<code>`（单位「人」），占比用 `tagstat.<tag_id>.share.<code>`（单位「%」）；占比事实必须带 `denominator_id`（指向人数事实）。分布的单位是固有的，不受该标签是否登记量纲影响。\\n  - `unit` 为 `null` 表示该标签的数值统计没有登记量纲：它的 `numeric` 数字只能用于定性描述与边界说明，**不得**登记为 AVAILABLE 事实；`categories` 的计数与占比不受此限制。\\n  - `plan_tag` 为 `true` 表示该列已被圈选条件截断（例如条件是「AUM ≥ 50 万」，那么 AUM 的均值有偏），结论里必须声明这一点。\\n- `sample_rows`：`{columns, rows, limit, masked, note}`，是所选标签列在客群内的脱敏明细（客户号已打码，最多 100 行）。它只用于观察分布形态与异常值，**不得**据以产出任何个体级结论或精确统计；正式数值一律引用 `tag_stats` 或人数。\\n\\n`stats_note` 非空时说明本轮取数已降级，要在 `boundary` 里如实转述。\\n\\n## 对照客群基准（baseline）\\n\\n当用户在运行技能前选择了「对照客群」时，`cohort_context` 会多出 `baseline`：`{group_id, name, count, tag_stats, stats_note}`。`tag_stats` 的结构与当前客群完全一致，字段含义相同；`plan_tag` 表示该列被对照客群自身的条件截断，做差与结论时要一并声明。`baseline` 是服务端核验的已保存客群，同一批标签列的两套统计可以直接比较。\\n\\n- 对照统计登记为事实时，`query_id` 用 `benchmark.<tag_id>.<统计名>` / `benchmark.<tag_id>.cat.<code>` / `benchmark.<tag_id>.share.<code>`，`role` 填 `BENCHMARK`；取值必须与注入值一致，服务端同样逐条复核。\\n- 客群与对照的差值登记为派生事实：`query_id` 用 `diff.<tag_id>.<统计名>`（数值差，单位与量纲同该统计）、`diff.<tag_id>.cat.<code>`（人数差，单位「人」）、`diff.<tag_id>.share.<code>`（占比差，单位 `pp`）；`role` 填 `DERIVED`，`derived_from` 填两侧事实 id。差值只在两侧同口径（均 AVAILABLE 且单位相同）时成立；只有一侧可用时不得登记差值。\\n- 差异 = 客群值 − 对照值；方向说明（高于/低于）本身不做价值判断，高与低都不等于好与坏。\\n- `baseline.stats_note` 非空时说明对照取数已降级，`comparison` 段与 `boundary` 要如实转述。\\n- 没选对照客群时以上都不适用，`comparison` 段按无基准处理。\\n\\n## Statement（陈述段）\\n\\n`{ text, fact_ids }`：`text` 是中文陈述，事实数值写成 `{fact:id}` 占位符，`fact_ids` 列出本段引用的全部 id。`{fact:}` 只允许引用 AVAILABLE 事实；缺失数据改用自然语言说明。日期、版本号、阈值这类非事实数字可以直接写。\\n\\n## InsightCard（五段式卡片）\\n\\n| 段 | 要求 |\\n| --- | --- |\\n| `facts` | 事实陈述 + 条件复述；引用规模事实 |\\n| `comparison` | `{text, fact_ids, benchmark_fact_ids, difference_fact_ids}`。有对照客群时写清比较对象（名称与人数）与差异事实；没有基准数据时如实写「本轮未接入基准数据，无法对比」并把两个数组填空数组 |\\n| `diagnosis` | `{text, fact_ids, basis}`，`basis ∈ RULE / STAT / HYPOTHESIS`。事实技能只做方法性说明（如「缺少基准，未形成诊断」），basis 用 `RULE`；`statistical_evidence` 填 `null` |\\n| `action` | `{text, fact_ids, population_fact_id, priority}`。不产出行动对象时 `population_fact_id: null`、`priority: \\"NONE\\"` |\\n| `boundary` | `{text, data_as_of, skill_version, sample_fact_id, metric_definitions}`。`text` 写适用边界与缺失影响；`data_as_of` 与 `skill_version` 先写空串（服务端回填）；`sample_fact_id` 填规模事实 id，无人数时写 `\\"\\"`；`metric_definitions` 是本次使用/欠缺的指标口径说明（每条一句话） |\\n\\n## 完整示例\\n\\n```insight-result\\n{\\n  \\"status\\": \\"PARTIAL\\",\\n  \\"reasons\\": [\\n    \\"仅接入服务端核验的客群条件与有效人数，资产、产品与行为指标未接入\\",\\n    \\"缺少基准数据，不产出对比与诊断结论\\"\\n  ],\\n  \\"facts\\": [\\n    {\\n      \\"id\\": \\"f-count\\",\\n      \\"metric\\": \\"customer_count\\",\\n      \\"label\\": \\"客群规模\\",\\n      \\"value\\": 1268,\\n      \\"unit\\": \\"人\\",\\n      \\"sample_size\\": 1268,\\n      \\"status\\": \\"AVAILABLE\\",\\n      \\"query_id\\": \\"cohort.count\\",\\n      \\"evidence\\": [\\"服务端按当前已核验方案统计的人数\\"],\\n      \\"role\\": \\"OBSERVED\\",\\n      \\"denominator_id\\": null,\\n      \\"derived_from\\": [],\\n      \\"exclusions_applied\\": []\\n    },\\n    {\\n      \\"id\\": \\"f-aum-missing\\",\\n      \\"metric\\": \\"aum\\",\\n      \\"label\\": \\"总资产\\",\\n      \\"value\\": null,\\n      \\"unit\\": \\"元\\",\\n      \\"sample_size\\": null,\\n      \\"status\\": \\"MISSING\\",\\n      \\"query_id\\": \\"catalog.aum\\",\\n      \\"evidence\\": [\\"本轮未接入指标取数通道，无法计算总资产\\"],\\n      \\"role\\": \\"OBSERVED\\",\\n      \\"denominator_id\\": null,\\n      \\"derived_from\\": [],\\n      \\"exclusions_applied\\": []\\n    },\\n    {\\n      \\"id\\": \\"f-holding-missing\\",\\n      \\"metric\\": \\"product_holding_rate\\",\\n      \\"label\\": \\"产品持有率\\",\\n      \\"value\\": null,\\n      \\"unit\\": \\"%\\",\\n      \\"sample_size\\": null,\\n      \\"status\\": \\"MISSING\\",\\n      \\"query_id\\": \\"catalog.product_holding_rate\\",\\n      \\"evidence\\": [\\"本轮未接入指标取数通道，无法计算产品持有结构\\"],\\n      \\"role\\": \\"OBSERVED\\",\\n      \\"denominator_id\\": null,\\n      \\"derived_from\\": [],\\n      \\"exclusions_applied\\": []\\n    }\\n  ],\\n  \\"cards\\": [\\n    {\\n      \\"id\\": \\"card-overview\\",\\n      \\"title\\": \\"客群概况\\",\\n      \\"facts\\": {\\n        \\"text\\": \\"本客群由「近30天转入金额至少500000元」且「未持有理财产品」两个条件圈定，共 {fact:f-count}。\\",\\n        \\"fact_ids\\": [\\"f-count\\"]\\n      },\\n      \\"comparison\\": {\\n        \\"text\\": \\"本轮未接入基准数据，无法回答「和同类客户比怎么样」。\\",\\n        \\"fact_ids\\": [],\\n        \\"benchmark_fact_ids\\": [],\\n        \\"difference_fact_ids\\": []\\n      },\\n      \\"diagnosis\\": {\\n        \\"text\\": \\"缺少对比对象与指标数据，本轮未形成诊断；条件的业务含义不等于客户的经营结论。\\",\\n        \\"fact_ids\\": [],\\n        \\"basis\\": \\"RULE\\",\\n        \\"statistical_evidence\\": null\\n      },\\n      \\"action\\": {\\n        \\"text\\": \\"本轮不产出行动对象：既没有客户级产品数据，也没有营销与适当性规则。\\",\\n        \\"fact_ids\\": [],\\n        \\"population_fact_id\\": null,\\n        \\"priority\\": \\"NONE\\"\\n      },\\n      \\"boundary\\": {\\n        \\"text\\": \\"结论仅覆盖客群条件与规模；资产、产品、人口与行为表现均未接入，不能据此推断客户特征或配置缺口。\\",\\n        \\"data_as_of\\": \\"\\",\\n        \\"skill_version\\": \\"\\",\\n        \\"sample_fact_id\\": \\"f-count\\",\\n        \\"metric_definitions\\": [\\n          \\"customer_count：按当前已核验方案服务端统计的客户数\\",\\n          \\"aum：客户名下资产总额，本轮未接入\\",\\n          \\"product_holding_rate：持有指定产品的客户占比，本轮未接入\\"\\n        ]\\n      }\\n    }\\n  ],\\n  \\"charts\\": [\\n    {\\n      \\"schema_version\\": 1,\\n      \\"id\\": \\"chart-scale\\",\\n      \\"title\\": \\"客群规模\\",\\n      \\"kind\\": \\"kpi\\",\\n      \\"intent\\": \\"single_value\\",\\n      \\"unit\\": \\"人\\",\\n      \\"metric_label\\": \\"客户数\\",\\n      \\"series\\": [\\n        {\\n          \\"name\\": \\"客群规模\\",\\n          \\"fact_ids\\": [\\"f-count\\"],\\n          \\"points\\": [{ \\"category\\": \\"客户数\\", \\"column\\": null, \\"fact_id\\": \\"f-count\\", \\"value\\": 1268 }]\\n        }\\n      ],\\n      \\"annotations\\": [],\\n      \\"reconcile\\": [],\\n      \\"zero_baseline\\": true,\\n      \\"orientation\\": \\"vertical\\"\\n    }\\n  ],\\n  \\"followups\\": [\\n    \\"运行 diagnostic-analysis：在接入基准数据后对比同类客群的资产与产品结构\\",\\n    \\"补充产品持有相关条件后再圈选，可缩小到更聚焦的客群\\"\\n  ]\\n}\\n```\\n\\n## 常见错误\\n\\n- 写了「约 1200 人」「近七成」这类未绑定事实的数字——必须用 `{fact:f-count}`。\\n- 把估算或经验值写成事实——宁可 `MISSING`，不可编造。\\n- 用 `{fact:}` 引用 MISSING 事实——面板会拒绝渲染；缺失只做文字说明。\\n- 段内 `text` 引用了 `{fact:id}` 却没写进该段的 `fact_ids`——服务端会按引用自动补齐；引用了不存在或不可用事实的，整卡丢弃。\\n- 图表 spec 引用了 `facts` 中不存在、或数值与事实不一致的 `fact_id`——spec 里的 `value` 必须与事实值完全相等。\\n- 忘了 `insight-result` 块或 JSON 不合法——结果是降级为纯文本，卡片和图表全部丢失。\\n- 给标签统计事实写了 `tagstat.*` 的 `query_id` 却改了数值，或引用了未选择标签、已抑制、未登记单位的统计量——服务端会整条丢弃。\\n- 给对照统计写了 `benchmark.*` / `diff.*` 却自行改数，或对只有一侧可用的统计量造差值——同样整条丢弃。\\n- 把 `sample_rows` 里的明细当成统计口径，或据它写出个体级结论。\\n"}], "skill_md": "---\\nname: \\"diagnostic-analysis\\"\\ndescription: \\"回答“哪里值得关注、为什么值得关注”：在事实基础上寻找对比对象、量化差异、下钻定位集中方向，并严格区分规则、统计与假设三种依据。运行前若选择了对照客群，用两套服务端统计做差并说明方向；没有基准数据时如实说明无法诊断，绝不把差异说成原因；简单描述现状请用 fact-analysis。\\"\\nargument-hint: \\"要诊断的方向（如：产品配置、资产结构）\\"\\nuser-invocable: true\\ndisable-model-invocation: false\\nallowed-tools: [\\"Read\\", \\"Skill\\"]\\n---\\n\\n# 诊断分析\\n\\n你要回答：「哪里值得关注」「为什么值得关注」。诊断的前提是**有可比较的对象**——基准、规则或统计检验；没有对比就没有诊断。\\n\\n## 前置事实\\n\\n先检查当前上下文里是否已经有本轮事实（同一次会话中先跑过 fact-analysis 时，提示词里会带有其输出）。没有就先调用 **fact-analysis** 技能补齐事实链，再做诊断——诊断必须建立在同一份事实表上，不能另起一套口径。\\n\\n## 诊断循环\\n\\n1. **读事实**：列出 AS-IS 事实（客群实际值，优先使用 `tag_stats` 里服务端注入的统计）与已声明的缺口。\\n2. **找可比对象**：上下文里有 `baseline`（对照客群）时，它就是本轮基准——对照客群由服务端重新编译并统计，与客群使用同一批标签列，可直接做差；在报告里写清对照客群的名称与人数。没有 `baseline` 时，按 `references/benchmark-selection.md` 逐项检查同类客群、全量客群、同机构、标准化基准，都不具备就明确记录「无基准」，进入第 5 步。`tag_stats`/`baseline.tag_stats` 只覆盖各自客群自身，不能跨客群拼接成本轮之外的基准。\\n3. **量化差异**：差异 = 客群值 − 对照值，登记为 `diff.*` 派生事实（比率类差值单位 `pp`），注明方向（高于/低于）。差异只在两侧口径一致时才成立（同期、同口径、同分母、同单位）；只有一侧可用时不得做差。被条件截断的列（`plan_tag`）要在结论里声明截断影响。\\n4. **下钻定位**（见 `references/drilldown-strategy.md`）：差异集中在哪些子群？按资产层、风险层、机构、产品线逐层看；下钻每一层都需要对应维度数据，数据没有就停下并声明。本轮可选标签有限，无法下钻时如实记录，不得用明细臆测子群差异。\\n5. **形成诊断**（见 `references/diagnosis-boundaries.md`）：每条结论标明依据类型——`RULE`（明确业务规则推导）、`STAT`（统计检验，需附检验方法与区间）、`HYPOTHESIS`（未验证的假设）。**差异 ≠ 原因**：可以说\\"权益类占比均值低于对照客群 X pp\\"，不能说\\"因为客户不喜欢理财\\"。对照客群的位置只是可比对象，不是目标值。\\n\\n## 阈值与显著性\\n\\n- 规则型判断（如\\"低于同类客群 X pp 以上算缺口\\"）要把规则原文写进 `boundary.metric_definitions`。\\n- 统计型判断必须给检验方法与双侧区间（如 Wilson + 多重比较校正），样本不足时降级为 HYPOTHESIS 或不下结论。没有做检验时，只能把差异陈述为观察（事实/派生事实），诊断句用 `HYPOTHESIS` 或规则口径，不得声称\\"显著\\"。\\n- 没有依据时宁可输出「未形成诊断」，也不要输出一个看起来像结论的猜测。\\n\\n## 输出\\n\\n正文之后以 ```insight-result 块收尾，字段与示例见 `references/result-contract.md`（与基础事实技能同一契约；块内是严格 JSON，字符串里不要用英文双引号）。诊断结论写进卡片的 `diagnosis` 段，`basis` 如实填写；`comparison` 段写清比较对象、差异值与方向，`benchmark_fact_ids` 引用 `benchmark.*` 事实、`difference_fact_ids` 引用 `diff.*` 事实；没有基准时才写「本轮未接入基准数据，无法对比」。行动建议只写\\"值得考虑的检验方向\\"，不要产出行动对象（那是 action-decision 的职责）。\\n\\n输出前逐段自查：`text` 里出现的每一个 `{fact:id}` 都必须同时出现在该段的 `fact_ids` 数组里（`comparison` 段的引用也计入 `fact_ids`）；`{fact:}` 只能引用本块 `facts` 中 `status` 为 `AVAILABLE` 的事实。漏登记或引用了不可用事实，该卡片会被服务端整卡丢弃。\\n\\n配图：差异对比适合 `compare_categories` 柱状图（客群与对照两组系列）、结构占比适合 `stacked_bar`、下钻矩阵适合 `heatmap`；调用 chart-intent 判定，不要直接画。没有可展示数值时 `charts` 为 `[]`。\\n"}', '{"name": "diagnostic-analysis", "display_name": "客群诊断分析", "description": "回答“哪里值得关注、为什么值得关注”：在事实基础上寻找对比对象、量化差异、下钻定位集中方向，并严格区分规则、统计与假设三种依据。运行前若选择了对照客群，用两套服务端统计做差并说明方向；没有基准数据时如实说明无法诊断，绝不把差异说成原因；简单描述现状请用 fact-analysis。", "instructions": "# 诊断分析\\n\\n你要回答：「哪里值得关注」「为什么值得关注」。诊断的前提是**有可比较的对象**——基准、规则或统计检验；没有对比就没有诊断。\\n\\n## 前置事实\\n\\n先检查当前上下文里是否已经有本轮事实（同一次会话中先跑过 fact-analysis 时，提示词里会带有其输出）。没有就先调用 **fact-analysis** 技能补齐事实链，再做诊断——诊断必须建立在同一份事实表上，不能另起一套口径。\\n\\n## 诊断循环\\n\\n1. **读事实**：列出 AS-IS 事实（客群实际值，优先使用 `tag_stats` 里服务端注入的统计）与已声明的缺口。\\n2. **找可比对象**：上下文里有 `baseline`（对照客群）时，它就是本轮基准——对照客群由服务端重新编译并统计，与客群使用同一批标签列，可直接做差；在报告里写清对照客群的名称与人数。没有 `baseline` 时，按 `references/benchmark-selection.md` 逐项检查同类客群、全量客群、同机构、标准化基准，都不具备就明确记录「无基准」，进入第 5 步。`tag_stats`/`baseline.tag_stats` 只覆盖各自客群自身，不能跨客群拼接成本轮之外的基准。\\n3. **量化差异**：差异 = 客群值 − 对照值，登记为 `diff.*` 派生事实（比率类差值单位 `pp`），注明方向（高于/低于）。差异只在两侧口径一致时才成立（同期、同口径、同分母、同单位）；只有一侧可用时不得做差。被条件截断的列（`plan_tag`）要在结论里声明截断影响。\\n4. **下钻定位**（见 `references/drilldown-strategy.md`）：差异集中在哪些子群？按资产层、风险层、机构、产品线逐层看；下钻每一层都需要对应维度数据，数据没有就停下并声明。本轮可选标签有限，无法下钻时如实记录，不得用明细臆测子群差异。\\n5. **形成诊断**（见 `references/diagnosis-boundaries.md`）：每条结论标明依据类型——`RULE`（明确业务规则推导）、`STAT`（统计检验，需附检验方法与区间）、`HYPOTHESIS`（未验证的假设）。**差异 ≠ 原因**：可以说\\"权益类占比均值低于对照客群 X pp\\"，不能说\\"因为客户不喜欢理财\\"。对照客群的位置只是可比对象，不是目标值。\\n\\n## 阈值与显著性\\n\\n- 规则型判断（如\\"低于同类客群 X pp 以上算缺口\\"）要把规则原文写进 `boundary.metric_definitions`。\\n- 统计型判断必须给检验方法与双侧区间（如 Wilson + 多重比较校正），样本不足时降级为 HYPOTHESIS 或不下结论。没有做检验时，只能把差异陈述为观察（事实/派生事实），诊断句用 `HYPOTHESIS` 或规则口径，不得声称\\"显著\\"。\\n- 没有依据时宁可输出「未形成诊断」，也不要输出一个看起来像结论的猜测。\\n\\n## 输出\\n\\n正文之后以 ```insight-result 块收尾，字段与示例见 `references/result-contract.md`（与基础事实技能同一契约；块内是严格 JSON，字符串里不要用英文双引号）。诊断结论写进卡片的 `diagnosis` 段，`basis` 如实填写；`comparison` 段写清比较对象、差异值与方向，`benchmark_fact_ids` 引用 `benchmark.*` 事实、`difference_fact_ids` 引用 `diff.*` 事实；没有基准时才写「本轮未接入基准数据，无法对比」。行动建议只写\\"值得考虑的检验方向\\"，不要产出行动对象（那是 action-decision 的职责）。\\n\\n输出前逐段自查：`text` 里出现的每一个 `{fact:id}` 都必须同时出现在该段的 `fact_ids` 数组里（`comparison` 段的引用也计入 `fact_ids`）；`{fact:}` 只能引用本块 `facts` 中 `status` 为 `AVAILABLE` 的事实。漏登记或引用了不可用事实，该卡片会被服务端整卡丢弃。\\n\\n配图：差异对比适合 `compare_categories` 柱状图（客群与对照两组系列）、结构占比适合 `stacked_bar`、下钻矩阵适合 `heatmap`；调用 chart-intent 判定，不要直接画。没有可展示数值时 `charts` 为 `[]`。", "argument_hint": "要诊断的方向（如：产品配置、资产结构）", "version": "1.2.0", "category": "diagnosis", "user_invocable": true, "disable_model_invocation": false, "allowed_tools": ["Read", "Skill"], "resources": [{"path": "references/benchmark-selection.md", "content": "# 基准选择\\n\\n## 基准来源\\n\\n| 来源 | 说明 | 适用 |\\n| --- | --- | --- |\\n| `baseline` 对照客群（已接入） | 用户在运行前选择的已保存客群，服务端按同一批标签列重新编译并统计；`benchmark.*` 是对照值，`diff.*` 是差值 | 默认来源；在报告里写清对照客群名称与人数 |\\n| `same_aum` | 同资产层级客群 | 防\\"资产规模差异\\"混淆产品行为差异 |\\n| `all_customers` | 全量客户 | 看客群相对全行的位置 |\\n| `same_org` | 同机构（分行/支行） | 排除地域经营差异 |\\n| `standardized` | 标准化基准 | 按 AUM × 风险等级交叉标准化后比较 |\\n\\n优先使用上下文里的 `baseline`——它是本轮唯一可复核的服务端基准。上下文没有 `baseline` 时，`same_aum` / `all_customers` / `same_org` / `standardized` 都是**尚未接入取数通道**的类型：在 `reasons` 中写「缺少基准数据，无法量化差异」，`comparison` 段如实写未接入，`benchmark_fact_ids` 与 `difference_fact_ids` 留空；诊断段只允许规则型结论（规则原文写进边界）。\\n\\n## 可比性检查清单\\n\\n比较前逐条确认，任何一条不满足就要么换基准、要么声明不可比：\\n\\n- **同期**：两侧数据日期一致（`data_as_of` 对齐）。\\n- **同口径**：指标定义一致（分子分母、时间窗口、是否含无资产客户）。\\n- **同分母**：比率类指标的分母口径一致。\\n- **样本充足**：两侧样本都超过抑制阈值（20），统计比较时按检验方法要求更高。\\n- **截断声明**：任一侧该列被自身圈选条件截断（`plan_tag`）时，差异结论必须声明截断影响。\\n\\n## 差异表达\\n\\n- 比率差用 **pp**（百分点）：`48.7% − 23.4% = 25.3pp`；相对差才用 %（`相对低 52%`），两者不能混用。\\n- 金额差注明单位与是否可比期间。\\n- 标注方向：缺口（低于基准）还是溢出（高于基准），并且**方向本身不做价值判断**——高与低都不等于好与坏。\\n- 与对照客群的差异是观察事实；把差异诊断为\\"问题\\"需要规则或检验支撑，`basis` 按依据如实填写。\\n"}, {"path": "references/diagnosis-boundaries.md", "content": "# 诊断边界\\n\\n## 差异 ≠ 原因\\n\\n观察到的差异只说明「不一样」，不说明「为什么不一样」。把差异叙述成因果是诊断环节最常见的越界：\\n\\n- ❌ 「因为客户风险偏好保守，所以理财持有率低」——把相关当因果，且\\"风险偏好保守\\"本身没有证据。\\n- ✅ 「理财持有率较同资产层级低 25.3pp，差异集中在 100~300 万资产段、中高风险承受能力客户」——陈述可复算的观察。\\n- ✅ 「一种可能解释是……，需要 X 数据/检验才能确认」——写成 HYPOTHESIS 并明确验证路径。\\n\\n## 依据类型（basis）\\n\\n| basis | 含义 | 必要条件 |\\n| --- | --- | --- |\\n| `RULE` | 明确业务规则推导 | 规则原文附在边界说明里；规则本身是组织已确认的口径 |\\n| `STAT` | 统计检验结论 | 附检验方法、区间与样本量；区间不重叠才可称\\"显著\\"；多重比较要校正 |\\n| `HYPOTHESIS` | 未验证假设 | 语言必须标明\\"假设/待验证\\"，不得使用断言句式 |\\n\\n评分、排序、预测类内容一律 `HYPOTHESIS`，除非有已发布的评分规则（此时是 `RULE`）。\\n\\n## 统计表达纪律\\n\\n- 区间不重叠 → \\"存在显著差异（方法：Wilson，95% 区间 [19.9%, 30.8%] vs [66.1%, 74.6%]）\\"。\\n- 区间重叠 → 只能说\\"观察到的差异未通过显著性检验\\"，不能暗示趋势。\\n- 样本低于阈值 → 不出结论；把该子群标记为样本不足。\\n- 不得把 RULE 型判断包装成\\"统计显著\\"；也不得把 HYPOTHESIS 写成确定性结论。\\n\\n## 什么时候输出「未形成诊断」\\n\\n以下情形，`status` 至少降为 `PARTIAL`，诊断段如实写未形成诊断与原因：\\n\\n- 没有任何基准或规则可比；\\n- 数据缺口使差异无法量化（如指标未接入）；\\n- 样本不足，差异不可检验。\\n\\n宁可输出\\"未形成诊断 + 检验计划\\"，也不要输出没有依据的结论——报告会被业务直接采信，未验证的猜测可能造成真实的营销与合规损失。\\n"}, {"path": "references/drilldown-strategy.md", "content": "# 下钻策略\\n\\n差异找到后，回答「集中在谁身上」。下钻是逐层的：每层只在数据允许时进行，每层下钻都要保持两侧可比。\\n\\n## 常用下钻维度（按优先级）\\n\\n1. **资产层级** `aum_tier`：差异是否集中在高/低资产段——最常见的混杂因素。\\n2. **风险等级** `risk_level`：产品持有差异常与风险承受能力共线。\\n3. **客户等级** `customer_tier`：存量经营分层。\\n4. **机构** `org_branch`：地域经营差异。\\n5. **时间**：差异是结构性的还是本期事件驱动的。\\n\\n## 方法\\n\\n- 逐层计算「客群值 vs 基准值」的差异，观察差异在哪个子群放大。\\n- 子群样本低于抑制阈值（20）时该格必须抑制（`SUPPRESSED` / 图上 `value: null`），不得展示。\\n- 下钻层数控制在 2~3 层：更深的层通常样本不足，结论会失去统计意义。\\n- 记录每次下钻的过滤条件，保证结论可复算。\\n\\n## 收敛判断\\n\\n- 差异在某个子群显著放大 → 「差异主要集中于……」，这是可下结论的形态。\\n- 差异在各子群均匀 → 说明差异与这些维度无关，换维度或接受\\"未定位到集中方向\\"。\\n- 数据不足以完成下钻 → 在 `reasons` 与 `boundary` 写明缺哪一层的什么数据。\\n\\n## 与事实层的关系\\n\\n下钻产生的新数字同样是事实：要么来自确定性数据系统，要么登记为 MISSING。下钻中临时口算的结果不得写进报告——比率、差值必须由服务端事实承载。\\n"}, {"path": "references/result-contract.md", "content": "# 结果契约（insight-result 块）\\n\\n正文之后必须追加一个 ```insight-result 围栏块，内含一个 JSON 对象。平台会在服务端校验并组装为洞察报告；块缺失或校验失败时只保留正文，图表与卡片不会展示。\\n\\n## JSON 纪律（先看这一节）\\n\\n块内必须是**严格 JSON**，平台直接解析，不接受任何近似写法：\\n\\n- 字符串内部不要出现英文双引号；需要引用词句时用中文引号 `「」` 或 `“”`。未转义的英文双引号是最常见的解析失败原因。\\n- 不要写注释、尾逗号、单引号；换行、反斜杠按 JSON 规则转义（正文段落已写在 JSON 外面，字符串内如需换行用 `\\\\n`）。\\n- 输出块之前自查一遍括号配对与逗号，宁可少写一段文字，也不要产出不合法 JSON。\\n- 块只写一次，放在正文最后；界面会把它从正文中移除，不要把同一份结果重复输出。\\n\\n## 顶层字段\\n\\n| 字段 | 类型 | 说明 |\\n| --- | --- | --- |\\n| `status` | `COMPLETE` / `PARTIAL` / `BLOCKED` | 本轮分析完成度。只有人数可用、其余指标缺失时为 `PARTIAL`；连人数都没有或无法归纳任何事实时为 `BLOCKED` |\\n| `reasons` | string[]（≤6） | 为什么是这个状态：一句话一条，写清缺失了什么 |\\n| `facts` | Fact[]（≤300） | 事实表，见下 |\\n| `cards` | InsightCard[]（1~30） | 五段式洞察卡，见下 |\\n| `charts` | ChartSpec[]（0~30） | 由 chart-intent / chart-atomic 产出的图表 spec；没有可用数据时为 `[]` |\\n| `followups` | string[]（≤10） | 建议的下一步（可运行的技能、可补充的条件、值得关注的方向） |\\n\\n## Fact（事实）\\n\\n| 字段 | 规则 |\\n| --- | --- |\\n| `id` | `f-` 开头小写标识（`f-count`、`f-aum-missing`），全表唯一 |\\n| `metric` | 指标 id（见 metric-catalog），如 `customer_count`、`aum` |\\n| `label` | 中文短标签，如「客群规模」「总资产」 |\\n| `value` | 数值；MISSING/SUPPRESSED 时必须为 `null` |\\n| `unit` | 只能是 `人` `元` `%` `pp` `分` |\\n| `sample_size` | 计算该事实的样本量（整数）。客群人数事实填人数本身；MISSING 填 `null` |\\n| `status` | `AVAILABLE`（有数）/ `SUPPRESSED`（样本太小被抑制）/ `MISSING`（数据未接入） |\\n| `query_id` | 证据来源标记：`cohort.count`（服务端人数）、`catalog.<metric>`（目录中未接入的指标）等 |\\n| `evidence` | 1~10 条来源说明（中文），写清\\"来自服务端核验的什么\\" |\\n| `role` | `OBSERVED`（直接观测）/ `BENCHMARK` / `POST_EXCLUSION` / `DERIVED` |\\n| `denominator_id` | 百分比的分子分母引用；非百分比填 `null` |\\n| `derived_from` | 派生来源事实 id 数组；直接观测填 `[]` |\\n| `exclusions_applied` | 已应用的排除项；未排除填 `[]` |\\n\\n允许登记为 AVAILABLE 的数值只有三类：\\n\\n1. **服务端核验的人数**（`count.value`，`query_id` 用 `cohort.count`）。\\n2. **条件原文中的阈值**（如「转入金额 ≥ 500000 元」中的 500000）。条件阈值事实用最接近的目录指标 id 作 `metric`、条件原文单位作 `unit`，并在 `evidence` 注明「来自服务端核验的圈选条件」——这样正文才能用 `{fact:id}` 安全引用这些数字。\\n3. **`tag_stats` 与 `baseline.tag_stats` 中服务端注入的标签统计**（本节下一小节）。服务端会逐条复核：`query_id` 命中 `tagstat.*`、`benchmark.*`、`diff.*` 的事实，取值必须与注入的统计量一致，否则整条被丢弃；数值统计的 `unit` 必须与注入值相同，未登记单位的标签统计不得登记为 AVAILABLE。\\n\\n除此之外的一切数值都必须来自确定性数据系统，没有就登记 `MISSING`。\\n\\n## 标签统计（tag_stats）与脱敏明细（sample_rows）\\n\\n当用户在左侧标签栏选择了标签并运行技能时，`cohort_context` 会多出两个字段：\\n\\n- `tag_stats`：每个所选标签一条，字段为 `tag_id` / `label` / `tag_type` / `unit` / `unit_source` / `plan_tag` / `status` / `reason` / `sample_size`，以及二选一的 `numeric` 或 `categories`。\\n  - `status` 为 `AVAILABLE` 时才可作为事实来源；`SUPPRESSED`（存在小于 20 人的分类，整组已抑制）、`MISSING`（取数失败或人数漂移）、`UNSUPPORTED`（该标签类型不支持统计）一律登记为 `MISSING` 事实并复述 `reason`。\\n  - `numeric`：`{n, missing, min, max, sum, avg, median}`，`query_id` 用 `tagstat.<tag_id>.<统计名>`（如 `tagstat.812.avg`）。数值已按标签登记的量纲折算到 `unit` 上（比率类已转成百分数，万元量纲已折算成元），**不要**再自行换算。\\n  - `categories`：`[{code, label, count, share}]`，计数用 `tagstat.<tag_id>.cat.<code>`（单位「人」），占比用 `tagstat.<tag_id>.share.<code>`（单位「%」）；占比事实必须带 `denominator_id`（指向人数事实）。分布的单位是固有的，不受该标签是否登记量纲影响。\\n  - `unit` 为 `null` 表示该标签的数值统计没有登记量纲：它的 `numeric` 数字只能用于定性描述与边界说明，**不得**登记为 AVAILABLE 事实；`categories` 的计数与占比不受此限制。\\n  - `plan_tag` 为 `true` 表示该列已被圈选条件截断（例如条件是「AUM ≥ 50 万」，那么 AUM 的均值有偏），结论里必须声明这一点。\\n- `sample_rows`：`{columns, rows, limit, masked, note}`，是所选标签列在客群内的脱敏明细（客户号已打码，最多 100 行）。它只用于观察分布形态与异常值，**不得**据以产出任何个体级结论或精确统计；正式数值一律引用 `tag_stats` 或人数。\\n\\n`stats_note` 非空时说明本轮取数已降级，要在 `boundary` 里如实转述。\\n\\n## 对照客群基准（baseline）\\n\\n当用户在运行技能前选择了「对照客群」时，`cohort_context` 会多出 `baseline`：`{group_id, name, count, tag_stats, stats_note}`。`tag_stats` 的结构与当前客群完全一致，字段含义相同；`plan_tag` 表示该列被对照客群自身的条件截断，做差与结论时要一并声明。`baseline` 是服务端核验的已保存客群，同一批标签列的两套统计可以直接比较。\\n\\n- 对照统计登记为事实时，`query_id` 用 `benchmark.<tag_id>.<统计名>` / `benchmark.<tag_id>.cat.<code>` / `benchmark.<tag_id>.share.<code>`，`role` 填 `BENCHMARK`；取值必须与注入值一致，服务端同样逐条复核。\\n- 客群与对照的差值登记为派生事实：`query_id` 用 `diff.<tag_id>.<统计名>`（数值差，单位与量纲同该统计）、`diff.<tag_id>.cat.<code>`（人数差，单位「人」）、`diff.<tag_id>.share.<code>`（占比差，单位 `pp`）；`role` 填 `DERIVED`，`derived_from` 填两侧事实 id。差值只在两侧同口径（均 AVAILABLE 且单位相同）时成立；只有一侧可用时不得登记差值。\\n- 差异 = 客群值 − 对照值；方向说明（高于/低于）本身不做价值判断，高与低都不等于好与坏。\\n- `baseline.stats_note` 非空时说明对照取数已降级，`comparison` 段与 `boundary` 要如实转述。\\n- 没选对照客群时以上都不适用，`comparison` 段按无基准处理。\\n\\n## Statement（陈述段）\\n\\n`{ text, fact_ids }`：`text` 是中文陈述，事实数值写成 `{fact:id}` 占位符，`fact_ids` 列出本段引用的全部 id。`{fact:}` 只允许引用 AVAILABLE 事实；缺失数据改用自然语言说明。日期、版本号、阈值这类非事实数字可以直接写。\\n\\n## InsightCard（五段式卡片）\\n\\n| 段 | 要求 |\\n| --- | --- |\\n| `facts` | 事实陈述 + 条件复述；引用规模事实 |\\n| `comparison` | `{text, fact_ids, benchmark_fact_ids, difference_fact_ids}`。有对照客群时写清比较对象（名称与人数）与差异事实；没有基准数据时如实写「本轮未接入基准数据，无法对比」并把两个数组填空数组 |\\n| `diagnosis` | `{text, fact_ids, basis}`，`basis ∈ RULE / STAT / HYPOTHESIS`。事实技能只做方法性说明（如「缺少基准，未形成诊断」），basis 用 `RULE`；`statistical_evidence` 填 `null` |\\n| `action` | `{text, fact_ids, population_fact_id, priority}`。不产出行动对象时 `population_fact_id: null`、`priority: \\"NONE\\"` |\\n| `boundary` | `{text, data_as_of, skill_version, sample_fact_id, metric_definitions}`。`text` 写适用边界与缺失影响；`data_as_of` 与 `skill_version` 先写空串（服务端回填）；`sample_fact_id` 填规模事实 id，无人数时写 `\\"\\"`；`metric_definitions` 是本次使用/欠缺的指标口径说明（每条一句话） |\\n\\n## 完整示例\\n\\n```insight-result\\n{\\n  \\"status\\": \\"PARTIAL\\",\\n  \\"reasons\\": [\\n    \\"仅接入服务端核验的客群条件与有效人数，资产、产品与行为指标未接入\\",\\n    \\"缺少基准数据，不产出对比与诊断结论\\"\\n  ],\\n  \\"facts\\": [\\n    {\\n      \\"id\\": \\"f-count\\",\\n      \\"metric\\": \\"customer_count\\",\\n      \\"label\\": \\"客群规模\\",\\n      \\"value\\": 1268,\\n      \\"unit\\": \\"人\\",\\n      \\"sample_size\\": 1268,\\n      \\"status\\": \\"AVAILABLE\\",\\n      \\"query_id\\": \\"cohort.count\\",\\n      \\"evidence\\": [\\"服务端按当前已核验方案统计的人数\\"],\\n      \\"role\\": \\"OBSERVED\\",\\n      \\"denominator_id\\": null,\\n      \\"derived_from\\": [],\\n      \\"exclusions_applied\\": []\\n    },\\n    {\\n      \\"id\\": \\"f-aum-missing\\",\\n      \\"metric\\": \\"aum\\",\\n      \\"label\\": \\"总资产\\",\\n      \\"value\\": null,\\n      \\"unit\\": \\"元\\",\\n      \\"sample_size\\": null,\\n      \\"status\\": \\"MISSING\\",\\n      \\"query_id\\": \\"catalog.aum\\",\\n      \\"evidence\\": [\\"本轮未接入指标取数通道，无法计算总资产\\"],\\n      \\"role\\": \\"OBSERVED\\",\\n      \\"denominator_id\\": null,\\n      \\"derived_from\\": [],\\n      \\"exclusions_applied\\": []\\n    },\\n    {\\n      \\"id\\": \\"f-holding-missing\\",\\n      \\"metric\\": \\"product_holding_rate\\",\\n      \\"label\\": \\"产品持有率\\",\\n      \\"value\\": null,\\n      \\"unit\\": \\"%\\",\\n      \\"sample_size\\": null,\\n      \\"status\\": \\"MISSING\\",\\n      \\"query_id\\": \\"catalog.product_holding_rate\\",\\n      \\"evidence\\": [\\"本轮未接入指标取数通道，无法计算产品持有结构\\"],\\n      \\"role\\": \\"OBSERVED\\",\\n      \\"denominator_id\\": null,\\n      \\"derived_from\\": [],\\n      \\"exclusions_applied\\": []\\n    }\\n  ],\\n  \\"cards\\": [\\n    {\\n      \\"id\\": \\"card-overview\\",\\n      \\"title\\": \\"客群概况\\",\\n      \\"facts\\": {\\n        \\"text\\": \\"本客群由「近30天转入金额至少500000元」且「未持有理财产品」两个条件圈定，共 {fact:f-count}。\\",\\n        \\"fact_ids\\": [\\"f-count\\"]\\n      },\\n      \\"comparison\\": {\\n        \\"text\\": \\"本轮未接入基准数据，无法回答「和同类客户比怎么样」。\\",\\n        \\"fact_ids\\": [],\\n        \\"benchmark_fact_ids\\": [],\\n        \\"difference_fact_ids\\": []\\n      },\\n      \\"diagnosis\\": {\\n        \\"text\\": \\"缺少对比对象与指标数据，本轮未形成诊断；条件的业务含义不等于客户的经营结论。\\",\\n        \\"fact_ids\\": [],\\n        \\"basis\\": \\"RULE\\",\\n        \\"statistical_evidence\\": null\\n      },\\n      \\"action\\": {\\n        \\"text\\": \\"本轮不产出行动对象：既没有客户级产品数据，也没有营销与适当性规则。\\",\\n        \\"fact_ids\\": [],\\n        \\"population_fact_id\\": null,\\n        \\"priority\\": \\"NONE\\"\\n      },\\n      \\"boundary\\": {\\n        \\"text\\": \\"结论仅覆盖客群条件与规模；资产、产品、人口与行为表现均未接入，不能据此推断客户特征或配置缺口。\\",\\n        \\"data_as_of\\": \\"\\",\\n        \\"skill_version\\": \\"\\",\\n        \\"sample_fact_id\\": \\"f-count\\",\\n        \\"metric_definitions\\": [\\n          \\"customer_count：按当前已核验方案服务端统计的客户数\\",\\n          \\"aum：客户名下资产总额，本轮未接入\\",\\n          \\"product_holding_rate：持有指定产品的客户占比，本轮未接入\\"\\n        ]\\n      }\\n    }\\n  ],\\n  \\"charts\\": [\\n    {\\n      \\"schema_version\\": 1,\\n      \\"id\\": \\"chart-scale\\",\\n      \\"title\\": \\"客群规模\\",\\n      \\"kind\\": \\"kpi\\",\\n      \\"intent\\": \\"single_value\\",\\n      \\"unit\\": \\"人\\",\\n      \\"metric_label\\": \\"客户数\\",\\n      \\"series\\": [\\n        {\\n          \\"name\\": \\"客群规模\\",\\n          \\"fact_ids\\": [\\"f-count\\"],\\n          \\"points\\": [{ \\"category\\": \\"客户数\\", \\"column\\": null, \\"fact_id\\": \\"f-count\\", \\"value\\": 1268 }]\\n        }\\n      ],\\n      \\"annotations\\": [],\\n      \\"reconcile\\": [],\\n      \\"zero_baseline\\": true,\\n      \\"orientation\\": \\"vertical\\"\\n    }\\n  ],\\n  \\"followups\\": [\\n    \\"运行 diagnostic-analysis：在接入基准数据后对比同类客群的资产与产品结构\\",\\n    \\"补充产品持有相关条件后再圈选，可缩小到更聚焦的客群\\"\\n  ]\\n}\\n```\\n\\n## 常见错误\\n\\n- 写了「约 1200 人」「近七成」这类未绑定事实的数字——必须用 `{fact:f-count}`。\\n- 把估算或经验值写成事实——宁可 `MISSING`，不可编造。\\n- 用 `{fact:}` 引用 MISSING 事实——面板会拒绝渲染；缺失只做文字说明。\\n- 段内 `text` 引用了 `{fact:id}` 却没写进该段的 `fact_ids`——服务端会按引用自动补齐；引用了不存在或不可用事实的，整卡丢弃。\\n- 图表 spec 引用了 `facts` 中不存在、或数值与事实不一致的 `fact_id`——spec 里的 `value` 必须与事实值完全相等。\\n- 忘了 `insight-result` 块或 JSON 不合法——结果是降级为纯文本，卡片和图表全部丢失。\\n- 给标签统计事实写了 `tagstat.*` 的 `query_id` 却改了数值，或引用了未选择标签、已抑制、未登记单位的统计量——服务端会整条丢弃。\\n- 给对照统计写了 `benchmark.*` / `diff.*` 却自行改数，或对只有一侧可用的统计量造差值——同样整条丢弃。\\n- 把 `sample_rows` 里的明细当成统计口径，或据它写出个体级结论。\\n"}], "skill_md": "---\\nname: \\"diagnostic-analysis\\"\\ndescription: \\"回答“哪里值得关注、为什么值得关注”：在事实基础上寻找对比对象、量化差异、下钻定位集中方向，并严格区分规则、统计与假设三种依据。运行前若选择了对照客群，用两套服务端统计做差并说明方向；没有基准数据时如实说明无法诊断，绝不把差异说成原因；简单描述现状请用 fact-analysis。\\"\\nargument-hint: \\"要诊断的方向（如：产品配置、资产结构）\\"\\nuser-invocable: true\\ndisable-model-invocation: false\\nallowed-tools: [\\"Read\\", \\"Skill\\"]\\n---\\n\\n# 诊断分析\\n\\n你要回答：「哪里值得关注」「为什么值得关注」。诊断的前提是**有可比较的对象**——基准、规则或统计检验；没有对比就没有诊断。\\n\\n## 前置事实\\n\\n先检查当前上下文里是否已经有本轮事实（同一次会话中先跑过 fact-analysis 时，提示词里会带有其输出）。没有就先调用 **fact-analysis** 技能补齐事实链，再做诊断——诊断必须建立在同一份事实表上，不能另起一套口径。\\n\\n## 诊断循环\\n\\n1. **读事实**：列出 AS-IS 事实（客群实际值，优先使用 `tag_stats` 里服务端注入的统计）与已声明的缺口。\\n2. **找可比对象**：上下文里有 `baseline`（对照客群）时，它就是本轮基准——对照客群由服务端重新编译并统计，与客群使用同一批标签列，可直接做差；在报告里写清对照客群的名称与人数。没有 `baseline` 时，按 `references/benchmark-selection.md` 逐项检查同类客群、全量客群、同机构、标准化基准，都不具备就明确记录「无基准」，进入第 5 步。`tag_stats`/`baseline.tag_stats` 只覆盖各自客群自身，不能跨客群拼接成本轮之外的基准。\\n3. **量化差异**：差异 = 客群值 − 对照值，登记为 `diff.*` 派生事实（比率类差值单位 `pp`），注明方向（高于/低于）。差异只在两侧口径一致时才成立（同期、同口径、同分母、同单位）；只有一侧可用时不得做差。被条件截断的列（`plan_tag`）要在结论里声明截断影响。\\n4. **下钻定位**（见 `references/drilldown-strategy.md`）：差异集中在哪些子群？按资产层、风险层、机构、产品线逐层看；下钻每一层都需要对应维度数据，数据没有就停下并声明。本轮可选标签有限，无法下钻时如实记录，不得用明细臆测子群差异。\\n5. **形成诊断**（见 `references/diagnosis-boundaries.md`）：每条结论标明依据类型——`RULE`（明确业务规则推导）、`STAT`（统计检验，需附检验方法与区间）、`HYPOTHESIS`（未验证的假设）。**差异 ≠ 原因**：可以说\\"权益类占比均值低于对照客群 X pp\\"，不能说\\"因为客户不喜欢理财\\"。对照客群的位置只是可比对象，不是目标值。\\n\\n## 阈值与显著性\\n\\n- 规则型判断（如\\"低于同类客群 X pp 以上算缺口\\"）要把规则原文写进 `boundary.metric_definitions`。\\n- 统计型判断必须给检验方法与双侧区间（如 Wilson + 多重比较校正），样本不足时降级为 HYPOTHESIS 或不下结论。没有做检验时，只能把差异陈述为观察（事实/派生事实），诊断句用 `HYPOTHESIS` 或规则口径，不得声称\\"显著\\"。\\n- 没有依据时宁可输出「未形成诊断」，也不要输出一个看起来像结论的猜测。\\n\\n## 输出\\n\\n正文之后以 ```insight-result 块收尾，字段与示例见 `references/result-contract.md`（与基础事实技能同一契约；块内是严格 JSON，字符串里不要用英文双引号）。诊断结论写进卡片的 `diagnosis` 段，`basis` 如实填写；`comparison` 段写清比较对象、差异值与方向，`benchmark_fact_ids` 引用 `benchmark.*` 事实、`difference_fact_ids` 引用 `diff.*` 事实；没有基准时才写「本轮未接入基准数据，无法对比」。行动建议只写\\"值得考虑的检验方向\\"，不要产出行动对象（那是 action-decision 的职责）。\\n\\n输出前逐段自查：`text` 里出现的每一个 `{fact:id}` 都必须同时出现在该段的 `fact_ids` 数组里（`comparison` 段的引用也计入 `fact_ids`）；`{fact:}` 只能引用本块 `facts` 中 `status` 为 `AVAILABLE` 的事实。漏登记或引用了不可用事实，该卡片会被服务端整卡丢弃。\\n\\n配图：差异对比适合 `compare_categories` 柱状图（客群与对照两组系列）、结构占比适合 `stacked_bar`、下钻矩阵适合 `heatmap`；调用 chart-intent 判定，不要直接画。没有可展示数值时 `charts` 为 `[]`。\\n"}', 1, 'seed', 'seed', NOW(), NOW(), NOW())
ON DUPLICATE KEY UPDATE draft_json=VALUES(draft_json), published_json=VALUES(published_json),
  row_version=row_version+1, update_by='seed', update_time=NOW(), publish_time=NOW();

INSERT INTO ts_agent_skill (name, draft_json, published_json, row_version, create_by, update_by, create_time, update_time, publish_time)
VALUES ('fact-analysis', '{"name": "fact-analysis", "display_name": "客群基础事实分析", "description": "面向任意已核验客群回答“这批客户是什么样”：把服务端核验的客群条件与有效人数整理成事实卡与图表，指标数据未接入时显性声明缺口。用户要客群概况、特征描述、规模与条件复述，或诊断/行动技能需要先补齐事实时使用；不要用它产出对比结论、因果判断或行动建议。", "instructions": "# 基础事实分析\\n\\n你要回答的是「这批客户是什么样」——描述现状，不下结论。\\n\\n## 证据来源\\n\\n本轮唯一的确定性证据在提示词末尾的「服务端客群上下文」（cohort_context）里，逐项理解：\\n\\n- `name` / `revision` / `plan_hash`：客群名称与方案版本，写进卡片边界。\\n- `plan.tree`：已核验的圈选条件。叶子节点形如\\n  `{kind:\\"TAG_PREDICATE\\", name:\\"近30天转入金额\\", operator:\\">=\\", values:[\\"500000\\"], code_options:[{code,label}], time_constraint:\\"近30天\\"}`；\\n  `Group{logic:\\"AND\\"|\\"OR\\", children}` 表达组合；`SCOPE_ALL` 表示全量客户；`DERIVED_PREDICATE` 用 `expression` 表达计算条件。\\n  `intent_plan.requirements[].business_meaning` 与 `plan.summary` 是需求层的业务含义，可直接引用。\\n- `count.value`：服务端核验过的人数（只在 `status=\\"COUNTED\\"` 时存在）。这是最基础的事实，任何情况下都可使用。\\n- `count` 为 null 表示方案尚未统计人数，不能推断，也不能拿条件估算。\\n- `tag_stats`：用户在左侧标签栏选择的标签，由服务端从当前客群里取出的聚合统计（数值型给人数/缺失/最小/最大/合计/均值/中位数，分类型给取值分布与占比）。`status=\\"AVAILABLE\\"` 时分布计数与占比即可用；数值统计还要求 `unit` 非 null（未登记量纲的标签只能描述形态，不能出数字）。`query_id` 原样抄 `tagstat.*`，数值已由服务端按登记量纲折算（比率转百分数、万元折元），不要再换算。`plan_tag=true` 的列已被条件截断，结论里要声明。\\n- `sample_rows`：所选标签列的脱敏明细（最多 100 行）。只用来观察分布形态，不能据此产出精确统计或个体结论。\\n\\n除此之外的指标（资产、产品、人口属性、行为、渠道……）如果不在 `tag_stats` 里，就仍然没有取数通道——用户没有选择对应标签，或者该标签未登记单位。**未经服务端核验的数字不得出现在输出中**，包括示例、估算和\\"行业经验值\\"。报告会被当作经营事实使用，编造数字是这个平台最严重的错误。\\n\\n## 工作步骤\\n\\n1. 读 `references/metric-catalog.md`，按目录规划「理论上应该看什么」（规模 / 客户结构 / 资产 / 产品 / 行为五组）。\\n2. 对照目录盘点证据：先看 `tag_stats` 里哪些条目可用，再检查用户是否漏选了值得分析的标签（在 `followups` 里建议补充选择）。把最相关的 3~6 个缺口登记为 MISSING 事实。\\n3. 复述条件用业务语言：优先 `code_options` 的 label 而不是码值，保留时间约束与单位；不要自行做单位换算。\\n4. 判断是否配图：有满足样本规则的数值事实时，调用 **chart-intent** 技能选图（它会再调用 chart-atomic 产出 spec）。没有可用数值就不配图，宁缺毋滥。\\n5. 按 `references/result-contract.md` 组装 `insight-result` 块收尾。\\n\\n## 判断规则\\n\\n- **事实 ≠ 诊断**：可以写「理财持有率 23.4%」，不能写「理财配置不足」。后者需要基准与规则，属于 diagnostic-analysis 的职责。越界会让报告失去可信度。\\n- **数值绑定事实**：正文与卡片里的事实数值一律写成 `{fact:f-xxx}` 引用，并在该段的 `fact_ids` 中登记。这样渲染、复制与复核都能追溯到同一份事实表。`{fact:}` 只能引用 AVAILABLE 的事实。\\n- **缺失显性化**：缺什么就写「本轮未接入 XX」并说明影响，而不是悄悄省略；沉默会让读者把缺失当成\\"没问题\\"。\\n- **样本抑制**：人数小于 20（平台抑制阈值）时不出图、不强调具体人数，改为说明样本量不足以展示。这是隐私要求。\\n\\n## 输出\\n\\n先写正文（中文、分段、不复述 JSON），再以 ```insight-result 围栏块输出结构化结果；块内字段与示例见 `references/result-contract.md`，块内必须是严格 JSON（字符串里不要用英文双引号）。图表 spec 由 chart-intent / chart-atomic 产出，不要自己发明字段。\\n\\n完成后不改动客群条件、人数、方案版本，也不创建实体客群。", "argument_hint": "分析目标或关注点（可留空）", "version": "1.1.2", "category": "fact", "user_invocable": true, "disable_model_invocation": false, "allowed_tools": ["Read", "Skill"], "resources": [{"path": "references/analysis-principles.md", "content": "# 分析原则\\n\\n## 事实与推断的分层\\n\\n平台把客群分析分为三层能力，每层可独立运行、逐层叠加：\\n\\n- **基础事实**（本技能）：只回答「是什么」。人数、条件、分布、占比——全部来自确定性数据系统。\\n- **诊断分析**：回答「哪里值得关注、为什么」。必须有对比对象（基准、规则或统计检验），并严格区分结论的依据类型（RULE / STAT / HYPOTHESIS）。\\n- **行动决策**：回答「接下来做什么」。行动对象必须来自规则服务过滤，不能由语言模型直接指定客户。\\n\\n越层表达会污染整条链路：事实层写下的「理财配置不足」，到了业务侧会被当成诊断结论使用，而它没有任何基准或规则支撑。宁可少说，不可越层。\\n\\n## 证据纪律\\n\\n- 数值计算与事实认定交给确定性系统（服务端核验的人数、指标绑定与聚合查询）；语言模型的职责是**理解、选择与解释**。\\n- 每条事实都要能回答「这个数从哪来」：`query_id` 与 `evidence` 就是这条追溯链。写不出证据的数值，就不该出现在报告里。\\n- 派生事实（`derived_from`）必须给出完整来源；链路断裂时降级为 `MISSING`。\\n\\n## 条件复述的口径\\n\\n圈选条件本身也是事实，复述时保持原口径：\\n\\n- 用 `code_options` 的 label（如「风险等级：稳健型」），不要暴露内部码值。\\n- 保留 `time_constraint`（如「近30天」），它决定条件的时间语义。\\n- `Group.logic` 决定条件之间的关系（AND/OR），复述时用「且 / 任一」明确表达。\\n- 企业客户、机构归属等上下文字段可能出现在 `intent_plan.requirements`，以业务含义为准引用。\\n\\n## 缺口声明\\n\\n报告里的缺失不是免责声明，而是分析结论的一部分：\\n\\n- 写清「缺什么 + 影响什么判断」。例：「本轮未接入产品持有数据，无法判断产品配置结构」。\\n- 把缺失登记为 MISSING 事实，让后续接入数据时可以定向补齐。\\n- 不要用「建议进一步分析」这类空话代替具体缺口。\\n"}, {"path": "references/fact-patterns.md", "content": "# 事实叙述模式\\n\\n## 正文结构\\n\\n一段合格的事实分析正文通常三段：\\n\\n1. **这段客群是谁**：用业务语言复述圈选条件，点出条件的业务意图（需求台账里的 business_meaning 可参考）。\\n2. **当前掌握的事实**：规模（以及任何已接入的数值事实），每条附一句口径。\\n3. **缺口与影响**：哪些指标没有接入、因此哪些问题现在答不了；给出 followups。\\n\\n正文不重复 JSON 块里的逐字段内容；数字用自然语言承载时也要写成 `{fact:id}` 占位（服务端渲染时替换）。\\n\\n## 卡片模式\\n\\n- 一个客群默认产出一张「客群概况」卡；当用户点名多组关注点（如\\"看看规模和产品\\"），可以拆成 2~3 张卡，每张聚焦一组事实。\\n- 卡的标题用业务语（「规模与条件」「产品持有概况」），不要用「分析1」「概况A」。\\n- `boundary.metric_definitions` 里逐条列出本卡涉及指标的口径一句话，包含未接入的。\\n\\n## 已接入事实的典型写法\\n\\n```\\n本条件已由服务端核验，满足条件的客户共 {fact:f-count}。\\n```\\n\\n```\\n条件共 2 条（近30天转入金额至少50万元 且 未持有理财产品），人数以服务端统计为准，如 {fact:f-count}。\\n```\\n\\n（单位与数值由服务端渲染；不要在文本里重复写人数。）\\n\\n## 缺口声明的典型写法\\n\\n```\\n本轮未接入总资产与产品持有数据，因此无法给出资产结构与产品覆盖情况；这两项需要指标取数能力接入后重跑。\\n```\\n\\n```\\n仍缺少：资产分层（aum_tier）、活期占比（liquid_share）。它们会影响对资金形态的判断，当前不能替代。\\n```\\n\\n## 不要写\\n\\n- 「资产管理规模中等偏低」——这是带判断的描述，需要基准，属诊断层。\\n- 「说明客户对理财兴趣不高」——因果推断，严禁。\\n- 「约有八成客户……」——未绑定事实的近似数字，严禁。\\n- 「建议加强营销」——行动层职责。\\n"}, {"path": "references/metric-catalog.md", "content": "# 指标目录（Metric Catalog）\\n\\n事实分析按下面五组规划「理论上应该看什么」。目录中标注「已接入」的才是可用事实；其余在输出中登记为 `MISSING` 事实与边界说明。\\n\\n标注「选标签可取」的指标：只要用户在左侧标签栏选择了对应标签，服务端就会把它作为 `tag_stats` 注入，可以直接写成事实——数值列给人数/缺失/最小/最大/合计/均值/中位数，分类列给取值分布与占比。同一标签没有选择时，仍然登记为 MISSING，并在 `followups` 里建议补充选择；不要因为\\"应该能取到\\"就写出数字。\\n\\n## 规模\\n\\n| 指标 id | 名称 | 单位 | 取数 |\\n| --- | --- | --- | --- |\\n| `customer_count` | 客群规模 | 人 | 已接入（服务端核验人数） |\\n\\n## 客户结构\\n\\n| 指标 id | 名称 | 单位 | 取数 |\\n| --- | --- | --- | --- |\\n| `age_band` | 年龄段分布 | 人 | 选标签可取（年龄字段；分层边界由标签口径决定，不要自造档位） |\\n| `gender` | 性别分布 | 人 | 选标签可取 |\\n| `customer_tier` | 客户等级分布 | 人 | 选标签可取 |\\n| `risk_level` | 风险等级分布 | 人 | 选标签可取 |\\n| `org_branch` | 归属机构分布 | 人 | 选标签可取 |\\n\\n## 资产\\n\\n| 指标 id | 名称 | 单位 | 取数 |\\n| --- | --- | --- | --- |\\n| `aum` | 总资产（AUM） | 元 | 选标签可取（合计） |\\n| `aum_avg` | 人均资产 | 元 | 选标签可取（均值） |\\n| `aum_median` | 资产中位数 | 元 | 选标签可取（中位数；服务端未产出时登记 MISSING） |\\n| `aum_tier` | 资产分层（如 30 万 / 100 万档） | 人 | 选标签可取（仅当该标签本身是分层字段；不要用金额列自行分档） |\\n| `liquid_aum` | 活期资产 | 元 | 选标签可取 |\\n| `fixed_aum` | 定期资产 | 元 | 选标签可取 |\\n| `investment_aum` | 投资类资产 | 元 | 选标签可取 |\\n| `liquid_share` | 活期占比 | % | 未接入（需要两个金额列同时选择并做比值，本轮不产出派生占比） |\\n\\n## 产品\\n\\n| 指标 id | 名称 | 单位 | 取数 |\\n| --- | --- | --- | --- |\\n| `product_holding_rate` | 产品持有率（按品类） | % | 选标签可取（持有标志列的分布；`%` 事实必须带分母） |\\n| `product_count_per_customer` | 人均产品覆盖数 | 分 | 未接入（需要按客户计数，本轮只有列级聚合） |\\n| `product_gap` | 产品配置缺口（相对基准） | pp | 未接入（需基准，属诊断） |\\n\\n## 行为\\n\\n| 指标 id | 名称 | 单位 | 取数 |\\n| --- | --- | --- | --- |\\n| `active_rate` | 活跃客户占比 | % | 选标签可取（活跃标志列的分布；`%` 事实必须带分母） |\\n| `channel_reach` | 渠道触达分布 | 人 | 选标签可取（渠道列的分布） |\\n| `fund_flow` | 资金流入流出 | 元 | 选标签可取（金额列的合计/均值） |\\n\\n## 口径说明\\n\\n- 金额单位默认「元」，不要把万元/亿元等复合单位写进 `unit`。`tag_stats` 里的数值已由服务端按标签语义层登记的量纲折算好（万元量纲折成元、比率折成百分数），直接引用即可，不要再做换算。\\n- 占比类指标（`%`）在平台契约里必须带分母（`denominator_id`），没有分母不得生成占比事实。分布条目已带 `share`，直接引用即可。\\n- 分布类指标在图上最多展示 12 个类别；超过时选择业务关键类别并说明截断范围，不允许编造「其他」桶。\\n- `tag_stats` 里 `plan_tag=true` 的列已经被圈选条件截断（例如条件是「AUM ≥ 50 万」，AUM 的均值就只覆盖 50 万以上客户），必须在卡片边界里说明这一点。\\n- `unit` 为 `null` 的标签没有登记单位，它的数字不能写成事实；只能定性描述并登记 MISSING 说明单位缺口。\\n- 标注「未接入」的指标，本轮统一登记 `MISSING` 事实（挑与本问题最相关的 3~6 个），并在边界中说明缺失对结论的影响。\\n"}, {"path": "references/result-contract.md", "content": "# 结果契约（insight-result 块）\\n\\n正文之后必须追加一个 ```insight-result 围栏块，内含一个 JSON 对象。平台会在服务端校验并组装为洞察报告；块缺失或校验失败时只保留正文，图表与卡片不会展示。\\n\\n## JSON 纪律（先看这一节）\\n\\n块内必须是**严格 JSON**，平台直接解析，不接受任何近似写法：\\n\\n- 字符串内部不要出现英文双引号；需要引用词句时用中文引号 `「」` 或 `“”`。未转义的英文双引号是最常见的解析失败原因。\\n- 不要写注释、尾逗号、单引号；换行、反斜杠按 JSON 规则转义（正文段落已写在 JSON 外面，字符串内如需换行用 `\\\\n`）。\\n- 输出块之前自查一遍括号配对与逗号，宁可少写一段文字，也不要产出不合法 JSON。\\n- 块只写一次，放在正文最后；界面会把它从正文中移除，不要把同一份结果重复输出。\\n\\n## 顶层字段\\n\\n| 字段 | 类型 | 说明 |\\n| --- | --- | --- |\\n| `status` | `COMPLETE` / `PARTIAL` / `BLOCKED` | 本轮分析完成度。只有人数可用、其余指标缺失时为 `PARTIAL`；连人数都没有或无法归纳任何事实时为 `BLOCKED` |\\n| `reasons` | string[]（≤6） | 为什么是这个状态：一句话一条，写清缺失了什么 |\\n| `facts` | Fact[]（≤300） | 事实表，见下 |\\n| `cards` | InsightCard[]（1~30） | 五段式洞察卡，见下 |\\n| `charts` | ChartSpec[]（0~30） | 由 chart-intent / chart-atomic 产出的图表 spec；没有可用数据时为 `[]` |\\n| `followups` | string[]（≤10） | 建议的下一步（可运行的技能、可补充的条件、值得关注的方向） |\\n\\n## Fact（事实）\\n\\n| 字段 | 规则 |\\n| --- | --- |\\n| `id` | `f-` 开头小写标识（`f-count`、`f-aum-missing`），全表唯一 |\\n| `metric` | 指标 id（见 metric-catalog），如 `customer_count`、`aum` |\\n| `label` | 中文短标签，如「客群规模」「总资产」 |\\n| `value` | 数值；MISSING/SUPPRESSED 时必须为 `null` |\\n| `unit` | 只能是 `人` `元` `%` `pp` `分` |\\n| `sample_size` | 计算该事实的样本量（整数）。客群人数事实填人数本身；MISSING 填 `null` |\\n| `status` | `AVAILABLE`（有数）/ `SUPPRESSED`（样本太小被抑制）/ `MISSING`（数据未接入） |\\n| `query_id` | 证据来源标记：`cohort.count`（服务端人数）、`catalog.<metric>`（目录中未接入的指标）等 |\\n| `evidence` | 1~10 条来源说明（中文），写清\\"来自服务端核验的什么\\" |\\n| `role` | `OBSERVED`（直接观测）/ `BENCHMARK` / `POST_EXCLUSION` / `DERIVED` |\\n| `denominator_id` | 百分比的分子分母引用；非百分比填 `null` |\\n| `derived_from` | 派生来源事实 id 数组；直接观测填 `[]` |\\n| `exclusions_applied` | 已应用的排除项；未排除填 `[]` |\\n\\n允许登记为 AVAILABLE 的数值只有三类：\\n\\n1. **服务端核验的人数**（`count.value`，`query_id` 用 `cohort.count`）。\\n2. **条件原文中的阈值**（如「转入金额 ≥ 500000 元」中的 500000）。条件阈值事实用最接近的目录指标 id 作 `metric`、条件原文单位作 `unit`，并在 `evidence` 注明「来自服务端核验的圈选条件」——这样正文才能用 `{fact:id}` 安全引用这些数字。\\n3. **`tag_stats` 与 `baseline.tag_stats` 中服务端注入的标签统计**（本节下一小节）。服务端会逐条复核：`query_id` 命中 `tagstat.*`、`benchmark.*`、`diff.*` 的事实，取值必须与注入的统计量一致，否则整条被丢弃；数值统计的 `unit` 必须与注入值相同，未登记单位的标签统计不得登记为 AVAILABLE。\\n\\n除此之外的一切数值都必须来自确定性数据系统，没有就登记 `MISSING`。\\n\\n## 标签统计（tag_stats）与脱敏明细（sample_rows）\\n\\n当用户在左侧标签栏选择了标签并运行技能时，`cohort_context` 会多出两个字段：\\n\\n- `tag_stats`：每个所选标签一条，字段为 `tag_id` / `label` / `tag_type` / `unit` / `unit_source` / `plan_tag` / `status` / `reason` / `sample_size`，以及二选一的 `numeric` 或 `categories`。\\n  - `status` 为 `AVAILABLE` 时才可作为事实来源；`SUPPRESSED`（存在小于 20 人的分类，整组已抑制）、`MISSING`（取数失败或人数漂移）、`UNSUPPORTED`（该标签类型不支持统计）一律登记为 `MISSING` 事实并复述 `reason`。\\n  - `numeric`：`{n, missing, min, max, sum, avg, median}`，`query_id` 用 `tagstat.<tag_id>.<统计名>`（如 `tagstat.812.avg`）。数值已按标签登记的量纲折算到 `unit` 上（比率类已转成百分数，万元量纲已折算成元），**不要**再自行换算。\\n  - `categories`：`[{code, label, count, share}]`，计数用 `tagstat.<tag_id>.cat.<code>`（单位「人」），占比用 `tagstat.<tag_id>.share.<code>`（单位「%」）；占比事实必须带 `denominator_id`（指向人数事实）。分布的单位是固有的，不受该标签是否登记量纲影响。\\n  - `unit` 为 `null` 表示该标签的数值统计没有登记量纲：它的 `numeric` 数字只能用于定性描述与边界说明，**不得**登记为 AVAILABLE 事实；`categories` 的计数与占比不受此限制。\\n  - `plan_tag` 为 `true` 表示该列已被圈选条件截断（例如条件是「AUM ≥ 50 万」，那么 AUM 的均值有偏），结论里必须声明这一点。\\n- `sample_rows`：`{columns, rows, limit, masked, note}`，是所选标签列在客群内的脱敏明细（客户号已打码，最多 100 行）。它只用于观察分布形态与异常值，**不得**据以产出任何个体级结论或精确统计；正式数值一律引用 `tag_stats` 或人数。\\n\\n`stats_note` 非空时说明本轮取数已降级，要在 `boundary` 里如实转述。\\n\\n## 对照客群基准（baseline）\\n\\n当用户在运行技能前选择了「对照客群」时，`cohort_context` 会多出 `baseline`：`{group_id, name, count, tag_stats, stats_note}`。`tag_stats` 的结构与当前客群完全一致，字段含义相同；`plan_tag` 表示该列被对照客群自身的条件截断，做差与结论时要一并声明。`baseline` 是服务端核验的已保存客群，同一批标签列的两套统计可以直接比较。\\n\\n- 对照统计登记为事实时，`query_id` 用 `benchmark.<tag_id>.<统计名>` / `benchmark.<tag_id>.cat.<code>` / `benchmark.<tag_id>.share.<code>`，`role` 填 `BENCHMARK`；取值必须与注入值一致，服务端同样逐条复核。\\n- 客群与对照的差值登记为派生事实：`query_id` 用 `diff.<tag_id>.<统计名>`（数值差，单位与量纲同该统计）、`diff.<tag_id>.cat.<code>`（人数差，单位「人」）、`diff.<tag_id>.share.<code>`（占比差，单位 `pp`）；`role` 填 `DERIVED`，`derived_from` 填两侧事实 id。差值只在两侧同口径（均 AVAILABLE 且单位相同）时成立；只有一侧可用时不得登记差值。\\n- 差异 = 客群值 − 对照值；方向说明（高于/低于）本身不做价值判断，高与低都不等于好与坏。\\n- `baseline.stats_note` 非空时说明对照取数已降级，`comparison` 段与 `boundary` 要如实转述。\\n- 没选对照客群时以上都不适用，`comparison` 段按无基准处理。\\n\\n## Statement（陈述段）\\n\\n`{ text, fact_ids }`：`text` 是中文陈述，事实数值写成 `{fact:id}` 占位符，`fact_ids` 列出本段引用的全部 id。`{fact:}` 只允许引用 AVAILABLE 事实；缺失数据改用自然语言说明。日期、版本号、阈值这类非事实数字可以直接写。\\n\\n## InsightCard（五段式卡片）\\n\\n| 段 | 要求 |\\n| --- | --- |\\n| `facts` | 事实陈述 + 条件复述；引用规模事实 |\\n| `comparison` | `{text, fact_ids, benchmark_fact_ids, difference_fact_ids}`。有对照客群时写清比较对象（名称与人数）与差异事实；没有基准数据时如实写「本轮未接入基准数据，无法对比」并把两个数组填空数组 |\\n| `diagnosis` | `{text, fact_ids, basis}`，`basis ∈ RULE / STAT / HYPOTHESIS`。事实技能只做方法性说明（如「缺少基准，未形成诊断」），basis 用 `RULE`；`statistical_evidence` 填 `null` |\\n| `action` | `{text, fact_ids, population_fact_id, priority}`。不产出行动对象时 `population_fact_id: null`、`priority: \\"NONE\\"` |\\n| `boundary` | `{text, data_as_of, skill_version, sample_fact_id, metric_definitions}`。`text` 写适用边界与缺失影响；`data_as_of` 与 `skill_version` 先写空串（服务端回填）；`sample_fact_id` 填规模事实 id，无人数时写 `\\"\\"`；`metric_definitions` 是本次使用/欠缺的指标口径说明（每条一句话） |\\n\\n## 完整示例\\n\\n```insight-result\\n{\\n  \\"status\\": \\"PARTIAL\\",\\n  \\"reasons\\": [\\n    \\"仅接入服务端核验的客群条件与有效人数，资产、产品与行为指标未接入\\",\\n    \\"缺少基准数据，不产出对比与诊断结论\\"\\n  ],\\n  \\"facts\\": [\\n    {\\n      \\"id\\": \\"f-count\\",\\n      \\"metric\\": \\"customer_count\\",\\n      \\"label\\": \\"客群规模\\",\\n      \\"value\\": 1268,\\n      \\"unit\\": \\"人\\",\\n      \\"sample_size\\": 1268,\\n      \\"status\\": \\"AVAILABLE\\",\\n      \\"query_id\\": \\"cohort.count\\",\\n      \\"evidence\\": [\\"服务端按当前已核验方案统计的人数\\"],\\n      \\"role\\": \\"OBSERVED\\",\\n      \\"denominator_id\\": null,\\n      \\"derived_from\\": [],\\n      \\"exclusions_applied\\": []\\n    },\\n    {\\n      \\"id\\": \\"f-aum-missing\\",\\n      \\"metric\\": \\"aum\\",\\n      \\"label\\": \\"总资产\\",\\n      \\"value\\": null,\\n      \\"unit\\": \\"元\\",\\n      \\"sample_size\\": null,\\n      \\"status\\": \\"MISSING\\",\\n      \\"query_id\\": \\"catalog.aum\\",\\n      \\"evidence\\": [\\"本轮未接入指标取数通道，无法计算总资产\\"],\\n      \\"role\\": \\"OBSERVED\\",\\n      \\"denominator_id\\": null,\\n      \\"derived_from\\": [],\\n      \\"exclusions_applied\\": []\\n    },\\n    {\\n      \\"id\\": \\"f-holding-missing\\",\\n      \\"metric\\": \\"product_holding_rate\\",\\n      \\"label\\": \\"产品持有率\\",\\n      \\"value\\": null,\\n      \\"unit\\": \\"%\\",\\n      \\"sample_size\\": null,\\n      \\"status\\": \\"MISSING\\",\\n      \\"query_id\\": \\"catalog.product_holding_rate\\",\\n      \\"evidence\\": [\\"本轮未接入指标取数通道，无法计算产品持有结构\\"],\\n      \\"role\\": \\"OBSERVED\\",\\n      \\"denominator_id\\": null,\\n      \\"derived_from\\": [],\\n      \\"exclusions_applied\\": []\\n    }\\n  ],\\n  \\"cards\\": [\\n    {\\n      \\"id\\": \\"card-overview\\",\\n      \\"title\\": \\"客群概况\\",\\n      \\"facts\\": {\\n        \\"text\\": \\"本客群由「近30天转入金额至少500000元」且「未持有理财产品」两个条件圈定，共 {fact:f-count}。\\",\\n        \\"fact_ids\\": [\\"f-count\\"]\\n      },\\n      \\"comparison\\": {\\n        \\"text\\": \\"本轮未接入基准数据，无法回答「和同类客户比怎么样」。\\",\\n        \\"fact_ids\\": [],\\n        \\"benchmark_fact_ids\\": [],\\n        \\"difference_fact_ids\\": []\\n      },\\n      \\"diagnosis\\": {\\n        \\"text\\": \\"缺少对比对象与指标数据，本轮未形成诊断；条件的业务含义不等于客户的经营结论。\\",\\n        \\"fact_ids\\": [],\\n        \\"basis\\": \\"RULE\\",\\n        \\"statistical_evidence\\": null\\n      },\\n      \\"action\\": {\\n        \\"text\\": \\"本轮不产出行动对象：既没有客户级产品数据，也没有营销与适当性规则。\\",\\n        \\"fact_ids\\": [],\\n        \\"population_fact_id\\": null,\\n        \\"priority\\": \\"NONE\\"\\n      },\\n      \\"boundary\\": {\\n        \\"text\\": \\"结论仅覆盖客群条件与规模；资产、产品、人口与行为表现均未接入，不能据此推断客户特征或配置缺口。\\",\\n        \\"data_as_of\\": \\"\\",\\n        \\"skill_version\\": \\"\\",\\n        \\"sample_fact_id\\": \\"f-count\\",\\n        \\"metric_definitions\\": [\\n          \\"customer_count：按当前已核验方案服务端统计的客户数\\",\\n          \\"aum：客户名下资产总额，本轮未接入\\",\\n          \\"product_holding_rate：持有指定产品的客户占比，本轮未接入\\"\\n        ]\\n      }\\n    }\\n  ],\\n  \\"charts\\": [\\n    {\\n      \\"schema_version\\": 1,\\n      \\"id\\": \\"chart-scale\\",\\n      \\"title\\": \\"客群规模\\",\\n      \\"kind\\": \\"kpi\\",\\n      \\"intent\\": \\"single_value\\",\\n      \\"unit\\": \\"人\\",\\n      \\"metric_label\\": \\"客户数\\",\\n      \\"series\\": [\\n        {\\n          \\"name\\": \\"客群规模\\",\\n          \\"fact_ids\\": [\\"f-count\\"],\\n          \\"points\\": [{ \\"category\\": \\"客户数\\", \\"column\\": null, \\"fact_id\\": \\"f-count\\", \\"value\\": 1268 }]\\n        }\\n      ],\\n      \\"annotations\\": [],\\n      \\"reconcile\\": [],\\n      \\"zero_baseline\\": true,\\n      \\"orientation\\": \\"vertical\\"\\n    }\\n  ],\\n  \\"followups\\": [\\n    \\"运行 diagnostic-analysis：在接入基准数据后对比同类客群的资产与产品结构\\",\\n    \\"补充产品持有相关条件后再圈选，可缩小到更聚焦的客群\\"\\n  ]\\n}\\n```\\n\\n## 常见错误\\n\\n- 写了「约 1200 人」「近七成」这类未绑定事实的数字——必须用 `{fact:f-count}`。\\n- 把估算或经验值写成事实——宁可 `MISSING`，不可编造。\\n- 用 `{fact:}` 引用 MISSING 事实——面板会拒绝渲染；缺失只做文字说明。\\n- 段内 `text` 引用了 `{fact:id}` 却没写进该段的 `fact_ids`——服务端会按引用自动补齐；引用了不存在或不可用事实的，整卡丢弃。\\n- 图表 spec 引用了 `facts` 中不存在、或数值与事实不一致的 `fact_id`——spec 里的 `value` 必须与事实值完全相等。\\n- 忘了 `insight-result` 块或 JSON 不合法——结果是降级为纯文本，卡片和图表全部丢失。\\n- 给标签统计事实写了 `tagstat.*` 的 `query_id` 却改了数值，或引用了未选择标签、已抑制、未登记单位的统计量——服务端会整条丢弃。\\n- 给对照统计写了 `benchmark.*` / `diff.*` 却自行改数，或对只有一侧可用的统计量造差值——同样整条丢弃。\\n- 把 `sample_rows` 里的明细当成统计口径，或据它写出个体级结论。\\n"}], "skill_md": "---\\nname: \\"fact-analysis\\"\\ndescription: \\"面向任意已核验客群回答“这批客户是什么样”：把服务端核验的客群条件与有效人数整理成事实卡与图表，指标数据未接入时显性声明缺口。用户要客群概况、特征描述、规模与条件复述，或诊断/行动技能需要先补齐事实时使用；不要用它产出对比结论、因果判断或行动建议。\\"\\nargument-hint: \\"分析目标或关注点（可留空）\\"\\nuser-invocable: true\\ndisable-model-invocation: false\\nallowed-tools: [\\"Read\\", \\"Skill\\"]\\n---\\n\\n# 基础事实分析\\n\\n你要回答的是「这批客户是什么样」——描述现状，不下结论。\\n\\n## 证据来源\\n\\n本轮唯一的确定性证据在提示词末尾的「服务端客群上下文」（cohort_context）里，逐项理解：\\n\\n- `name` / `revision` / `plan_hash`：客群名称与方案版本，写进卡片边界。\\n- `plan.tree`：已核验的圈选条件。叶子节点形如\\n  `{kind:\\"TAG_PREDICATE\\", name:\\"近30天转入金额\\", operator:\\">=\\", values:[\\"500000\\"], code_options:[{code,label}], time_constraint:\\"近30天\\"}`；\\n  `Group{logic:\\"AND\\"|\\"OR\\", children}` 表达组合；`SCOPE_ALL` 表示全量客户；`DERIVED_PREDICATE` 用 `expression` 表达计算条件。\\n  `intent_plan.requirements[].business_meaning` 与 `plan.summary` 是需求层的业务含义，可直接引用。\\n- `count.value`：服务端核验过的人数（只在 `status=\\"COUNTED\\"` 时存在）。这是最基础的事实，任何情况下都可使用。\\n- `count` 为 null 表示方案尚未统计人数，不能推断，也不能拿条件估算。\\n- `tag_stats`：用户在左侧标签栏选择的标签，由服务端从当前客群里取出的聚合统计（数值型给人数/缺失/最小/最大/合计/均值/中位数，分类型给取值分布与占比）。`status=\\"AVAILABLE\\"` 时分布计数与占比即可用；数值统计还要求 `unit` 非 null（未登记量纲的标签只能描述形态，不能出数字）。`query_id` 原样抄 `tagstat.*`，数值已由服务端按登记量纲折算（比率转百分数、万元折元），不要再换算。`plan_tag=true` 的列已被条件截断，结论里要声明。\\n- `sample_rows`：所选标签列的脱敏明细（最多 100 行）。只用来观察分布形态，不能据此产出精确统计或个体结论。\\n\\n除此之外的指标（资产、产品、人口属性、行为、渠道……）如果不在 `tag_stats` 里，就仍然没有取数通道——用户没有选择对应标签，或者该标签未登记单位。**未经服务端核验的数字不得出现在输出中**，包括示例、估算和\\"行业经验值\\"。报告会被当作经营事实使用，编造数字是这个平台最严重的错误。\\n\\n## 工作步骤\\n\\n1. 读 `references/metric-catalog.md`，按目录规划「理论上应该看什么」（规模 / 客户结构 / 资产 / 产品 / 行为五组）。\\n2. 对照目录盘点证据：先看 `tag_stats` 里哪些条目可用，再检查用户是否漏选了值得分析的标签（在 `followups` 里建议补充选择）。把最相关的 3~6 个缺口登记为 MISSING 事实。\\n3. 复述条件用业务语言：优先 `code_options` 的 label 而不是码值，保留时间约束与单位；不要自行做单位换算。\\n4. 判断是否配图：有满足样本规则的数值事实时，调用 **chart-intent** 技能选图（它会再调用 chart-atomic 产出 spec）。没有可用数值就不配图，宁缺毋滥。\\n5. 按 `references/result-contract.md` 组装 `insight-result` 块收尾。\\n\\n## 判断规则\\n\\n- **事实 ≠ 诊断**：可以写「理财持有率 23.4%」，不能写「理财配置不足」。后者需要基准与规则，属于 diagnostic-analysis 的职责。越界会让报告失去可信度。\\n- **数值绑定事实**：正文与卡片里的事实数值一律写成 `{fact:f-xxx}` 引用，并在该段的 `fact_ids` 中登记。这样渲染、复制与复核都能追溯到同一份事实表。`{fact:}` 只能引用 AVAILABLE 的事实。\\n- **缺失显性化**：缺什么就写「本轮未接入 XX」并说明影响，而不是悄悄省略；沉默会让读者把缺失当成\\"没问题\\"。\\n- **样本抑制**：人数小于 20（平台抑制阈值）时不出图、不强调具体人数，改为说明样本量不足以展示。这是隐私要求。\\n\\n## 输出\\n\\n先写正文（中文、分段、不复述 JSON），再以 ```insight-result 围栏块输出结构化结果；块内字段与示例见 `references/result-contract.md`，块内必须是严格 JSON（字符串里不要用英文双引号）。图表 spec 由 chart-intent / chart-atomic 产出，不要自己发明字段。\\n\\n完成后不改动客群条件、人数、方案版本，也不创建实体客群。\\n"}', '{"name": "fact-analysis", "display_name": "客群基础事实分析", "description": "面向任意已核验客群回答“这批客户是什么样”：把服务端核验的客群条件与有效人数整理成事实卡与图表，指标数据未接入时显性声明缺口。用户要客群概况、特征描述、规模与条件复述，或诊断/行动技能需要先补齐事实时使用；不要用它产出对比结论、因果判断或行动建议。", "instructions": "# 基础事实分析\\n\\n你要回答的是「这批客户是什么样」——描述现状，不下结论。\\n\\n## 证据来源\\n\\n本轮唯一的确定性证据在提示词末尾的「服务端客群上下文」（cohort_context）里，逐项理解：\\n\\n- `name` / `revision` / `plan_hash`：客群名称与方案版本，写进卡片边界。\\n- `plan.tree`：已核验的圈选条件。叶子节点形如\\n  `{kind:\\"TAG_PREDICATE\\", name:\\"近30天转入金额\\", operator:\\">=\\", values:[\\"500000\\"], code_options:[{code,label}], time_constraint:\\"近30天\\"}`；\\n  `Group{logic:\\"AND\\"|\\"OR\\", children}` 表达组合；`SCOPE_ALL` 表示全量客户；`DERIVED_PREDICATE` 用 `expression` 表达计算条件。\\n  `intent_plan.requirements[].business_meaning` 与 `plan.summary` 是需求层的业务含义，可直接引用。\\n- `count.value`：服务端核验过的人数（只在 `status=\\"COUNTED\\"` 时存在）。这是最基础的事实，任何情况下都可使用。\\n- `count` 为 null 表示方案尚未统计人数，不能推断，也不能拿条件估算。\\n- `tag_stats`：用户在左侧标签栏选择的标签，由服务端从当前客群里取出的聚合统计（数值型给人数/缺失/最小/最大/合计/均值/中位数，分类型给取值分布与占比）。`status=\\"AVAILABLE\\"` 时分布计数与占比即可用；数值统计还要求 `unit` 非 null（未登记量纲的标签只能描述形态，不能出数字）。`query_id` 原样抄 `tagstat.*`，数值已由服务端按登记量纲折算（比率转百分数、万元折元），不要再换算。`plan_tag=true` 的列已被条件截断，结论里要声明。\\n- `sample_rows`：所选标签列的脱敏明细（最多 100 行）。只用来观察分布形态，不能据此产出精确统计或个体结论。\\n\\n除此之外的指标（资产、产品、人口属性、行为、渠道……）如果不在 `tag_stats` 里，就仍然没有取数通道——用户没有选择对应标签，或者该标签未登记单位。**未经服务端核验的数字不得出现在输出中**，包括示例、估算和\\"行业经验值\\"。报告会被当作经营事实使用，编造数字是这个平台最严重的错误。\\n\\n## 工作步骤\\n\\n1. 读 `references/metric-catalog.md`，按目录规划「理论上应该看什么」（规模 / 客户结构 / 资产 / 产品 / 行为五组）。\\n2. 对照目录盘点证据：先看 `tag_stats` 里哪些条目可用，再检查用户是否漏选了值得分析的标签（在 `followups` 里建议补充选择）。把最相关的 3~6 个缺口登记为 MISSING 事实。\\n3. 复述条件用业务语言：优先 `code_options` 的 label 而不是码值，保留时间约束与单位；不要自行做单位换算。\\n4. 判断是否配图：有满足样本规则的数值事实时，调用 **chart-intent** 技能选图（它会再调用 chart-atomic 产出 spec）。没有可用数值就不配图，宁缺毋滥。\\n5. 按 `references/result-contract.md` 组装 `insight-result` 块收尾。\\n\\n## 判断规则\\n\\n- **事实 ≠ 诊断**：可以写「理财持有率 23.4%」，不能写「理财配置不足」。后者需要基准与规则，属于 diagnostic-analysis 的职责。越界会让报告失去可信度。\\n- **数值绑定事实**：正文与卡片里的事实数值一律写成 `{fact:f-xxx}` 引用，并在该段的 `fact_ids` 中登记。这样渲染、复制与复核都能追溯到同一份事实表。`{fact:}` 只能引用 AVAILABLE 的事实。\\n- **缺失显性化**：缺什么就写「本轮未接入 XX」并说明影响，而不是悄悄省略；沉默会让读者把缺失当成\\"没问题\\"。\\n- **样本抑制**：人数小于 20（平台抑制阈值）时不出图、不强调具体人数，改为说明样本量不足以展示。这是隐私要求。\\n\\n## 输出\\n\\n先写正文（中文、分段、不复述 JSON），再以 ```insight-result 围栏块输出结构化结果；块内字段与示例见 `references/result-contract.md`，块内必须是严格 JSON（字符串里不要用英文双引号）。图表 spec 由 chart-intent / chart-atomic 产出，不要自己发明字段。\\n\\n完成后不改动客群条件、人数、方案版本，也不创建实体客群。", "argument_hint": "分析目标或关注点（可留空）", "version": "1.1.2", "category": "fact", "user_invocable": true, "disable_model_invocation": false, "allowed_tools": ["Read", "Skill"], "resources": [{"path": "references/analysis-principles.md", "content": "# 分析原则\\n\\n## 事实与推断的分层\\n\\n平台把客群分析分为三层能力，每层可独立运行、逐层叠加：\\n\\n- **基础事实**（本技能）：只回答「是什么」。人数、条件、分布、占比——全部来自确定性数据系统。\\n- **诊断分析**：回答「哪里值得关注、为什么」。必须有对比对象（基准、规则或统计检验），并严格区分结论的依据类型（RULE / STAT / HYPOTHESIS）。\\n- **行动决策**：回答「接下来做什么」。行动对象必须来自规则服务过滤，不能由语言模型直接指定客户。\\n\\n越层表达会污染整条链路：事实层写下的「理财配置不足」，到了业务侧会被当成诊断结论使用，而它没有任何基准或规则支撑。宁可少说，不可越层。\\n\\n## 证据纪律\\n\\n- 数值计算与事实认定交给确定性系统（服务端核验的人数、指标绑定与聚合查询）；语言模型的职责是**理解、选择与解释**。\\n- 每条事实都要能回答「这个数从哪来」：`query_id` 与 `evidence` 就是这条追溯链。写不出证据的数值，就不该出现在报告里。\\n- 派生事实（`derived_from`）必须给出完整来源；链路断裂时降级为 `MISSING`。\\n\\n## 条件复述的口径\\n\\n圈选条件本身也是事实，复述时保持原口径：\\n\\n- 用 `code_options` 的 label（如「风险等级：稳健型」），不要暴露内部码值。\\n- 保留 `time_constraint`（如「近30天」），它决定条件的时间语义。\\n- `Group.logic` 决定条件之间的关系（AND/OR），复述时用「且 / 任一」明确表达。\\n- 企业客户、机构归属等上下文字段可能出现在 `intent_plan.requirements`，以业务含义为准引用。\\n\\n## 缺口声明\\n\\n报告里的缺失不是免责声明，而是分析结论的一部分：\\n\\n- 写清「缺什么 + 影响什么判断」。例：「本轮未接入产品持有数据，无法判断产品配置结构」。\\n- 把缺失登记为 MISSING 事实，让后续接入数据时可以定向补齐。\\n- 不要用「建议进一步分析」这类空话代替具体缺口。\\n"}, {"path": "references/fact-patterns.md", "content": "# 事实叙述模式\\n\\n## 正文结构\\n\\n一段合格的事实分析正文通常三段：\\n\\n1. **这段客群是谁**：用业务语言复述圈选条件，点出条件的业务意图（需求台账里的 business_meaning 可参考）。\\n2. **当前掌握的事实**：规模（以及任何已接入的数值事实），每条附一句口径。\\n3. **缺口与影响**：哪些指标没有接入、因此哪些问题现在答不了；给出 followups。\\n\\n正文不重复 JSON 块里的逐字段内容；数字用自然语言承载时也要写成 `{fact:id}` 占位（服务端渲染时替换）。\\n\\n## 卡片模式\\n\\n- 一个客群默认产出一张「客群概况」卡；当用户点名多组关注点（如\\"看看规模和产品\\"），可以拆成 2~3 张卡，每张聚焦一组事实。\\n- 卡的标题用业务语（「规模与条件」「产品持有概况」），不要用「分析1」「概况A」。\\n- `boundary.metric_definitions` 里逐条列出本卡涉及指标的口径一句话，包含未接入的。\\n\\n## 已接入事实的典型写法\\n\\n```\\n本条件已由服务端核验，满足条件的客户共 {fact:f-count}。\\n```\\n\\n```\\n条件共 2 条（近30天转入金额至少50万元 且 未持有理财产品），人数以服务端统计为准，如 {fact:f-count}。\\n```\\n\\n（单位与数值由服务端渲染；不要在文本里重复写人数。）\\n\\n## 缺口声明的典型写法\\n\\n```\\n本轮未接入总资产与产品持有数据，因此无法给出资产结构与产品覆盖情况；这两项需要指标取数能力接入后重跑。\\n```\\n\\n```\\n仍缺少：资产分层（aum_tier）、活期占比（liquid_share）。它们会影响对资金形态的判断，当前不能替代。\\n```\\n\\n## 不要写\\n\\n- 「资产管理规模中等偏低」——这是带判断的描述，需要基准，属诊断层。\\n- 「说明客户对理财兴趣不高」——因果推断，严禁。\\n- 「约有八成客户……」——未绑定事实的近似数字，严禁。\\n- 「建议加强营销」——行动层职责。\\n"}, {"path": "references/metric-catalog.md", "content": "# 指标目录（Metric Catalog）\\n\\n事实分析按下面五组规划「理论上应该看什么」。目录中标注「已接入」的才是可用事实；其余在输出中登记为 `MISSING` 事实与边界说明。\\n\\n标注「选标签可取」的指标：只要用户在左侧标签栏选择了对应标签，服务端就会把它作为 `tag_stats` 注入，可以直接写成事实——数值列给人数/缺失/最小/最大/合计/均值/中位数，分类列给取值分布与占比。同一标签没有选择时，仍然登记为 MISSING，并在 `followups` 里建议补充选择；不要因为\\"应该能取到\\"就写出数字。\\n\\n## 规模\\n\\n| 指标 id | 名称 | 单位 | 取数 |\\n| --- | --- | --- | --- |\\n| `customer_count` | 客群规模 | 人 | 已接入（服务端核验人数） |\\n\\n## 客户结构\\n\\n| 指标 id | 名称 | 单位 | 取数 |\\n| --- | --- | --- | --- |\\n| `age_band` | 年龄段分布 | 人 | 选标签可取（年龄字段；分层边界由标签口径决定，不要自造档位） |\\n| `gender` | 性别分布 | 人 | 选标签可取 |\\n| `customer_tier` | 客户等级分布 | 人 | 选标签可取 |\\n| `risk_level` | 风险等级分布 | 人 | 选标签可取 |\\n| `org_branch` | 归属机构分布 | 人 | 选标签可取 |\\n\\n## 资产\\n\\n| 指标 id | 名称 | 单位 | 取数 |\\n| --- | --- | --- | --- |\\n| `aum` | 总资产（AUM） | 元 | 选标签可取（合计） |\\n| `aum_avg` | 人均资产 | 元 | 选标签可取（均值） |\\n| `aum_median` | 资产中位数 | 元 | 选标签可取（中位数；服务端未产出时登记 MISSING） |\\n| `aum_tier` | 资产分层（如 30 万 / 100 万档） | 人 | 选标签可取（仅当该标签本身是分层字段；不要用金额列自行分档） |\\n| `liquid_aum` | 活期资产 | 元 | 选标签可取 |\\n| `fixed_aum` | 定期资产 | 元 | 选标签可取 |\\n| `investment_aum` | 投资类资产 | 元 | 选标签可取 |\\n| `liquid_share` | 活期占比 | % | 未接入（需要两个金额列同时选择并做比值，本轮不产出派生占比） |\\n\\n## 产品\\n\\n| 指标 id | 名称 | 单位 | 取数 |\\n| --- | --- | --- | --- |\\n| `product_holding_rate` | 产品持有率（按品类） | % | 选标签可取（持有标志列的分布；`%` 事实必须带分母） |\\n| `product_count_per_customer` | 人均产品覆盖数 | 分 | 未接入（需要按客户计数，本轮只有列级聚合） |\\n| `product_gap` | 产品配置缺口（相对基准） | pp | 未接入（需基准，属诊断） |\\n\\n## 行为\\n\\n| 指标 id | 名称 | 单位 | 取数 |\\n| --- | --- | --- | --- |\\n| `active_rate` | 活跃客户占比 | % | 选标签可取（活跃标志列的分布；`%` 事实必须带分母） |\\n| `channel_reach` | 渠道触达分布 | 人 | 选标签可取（渠道列的分布） |\\n| `fund_flow` | 资金流入流出 | 元 | 选标签可取（金额列的合计/均值） |\\n\\n## 口径说明\\n\\n- 金额单位默认「元」，不要把万元/亿元等复合单位写进 `unit`。`tag_stats` 里的数值已由服务端按标签语义层登记的量纲折算好（万元量纲折成元、比率折成百分数），直接引用即可，不要再做换算。\\n- 占比类指标（`%`）在平台契约里必须带分母（`denominator_id`），没有分母不得生成占比事实。分布条目已带 `share`，直接引用即可。\\n- 分布类指标在图上最多展示 12 个类别；超过时选择业务关键类别并说明截断范围，不允许编造「其他」桶。\\n- `tag_stats` 里 `plan_tag=true` 的列已经被圈选条件截断（例如条件是「AUM ≥ 50 万」，AUM 的均值就只覆盖 50 万以上客户），必须在卡片边界里说明这一点。\\n- `unit` 为 `null` 的标签没有登记单位，它的数字不能写成事实；只能定性描述并登记 MISSING 说明单位缺口。\\n- 标注「未接入」的指标，本轮统一登记 `MISSING` 事实（挑与本问题最相关的 3~6 个），并在边界中说明缺失对结论的影响。\\n"}, {"path": "references/result-contract.md", "content": "# 结果契约（insight-result 块）\\n\\n正文之后必须追加一个 ```insight-result 围栏块，内含一个 JSON 对象。平台会在服务端校验并组装为洞察报告；块缺失或校验失败时只保留正文，图表与卡片不会展示。\\n\\n## JSON 纪律（先看这一节）\\n\\n块内必须是**严格 JSON**，平台直接解析，不接受任何近似写法：\\n\\n- 字符串内部不要出现英文双引号；需要引用词句时用中文引号 `「」` 或 `“”`。未转义的英文双引号是最常见的解析失败原因。\\n- 不要写注释、尾逗号、单引号；换行、反斜杠按 JSON 规则转义（正文段落已写在 JSON 外面，字符串内如需换行用 `\\\\n`）。\\n- 输出块之前自查一遍括号配对与逗号，宁可少写一段文字，也不要产出不合法 JSON。\\n- 块只写一次，放在正文最后；界面会把它从正文中移除，不要把同一份结果重复输出。\\n\\n## 顶层字段\\n\\n| 字段 | 类型 | 说明 |\\n| --- | --- | --- |\\n| `status` | `COMPLETE` / `PARTIAL` / `BLOCKED` | 本轮分析完成度。只有人数可用、其余指标缺失时为 `PARTIAL`；连人数都没有或无法归纳任何事实时为 `BLOCKED` |\\n| `reasons` | string[]（≤6） | 为什么是这个状态：一句话一条，写清缺失了什么 |\\n| `facts` | Fact[]（≤300） | 事实表，见下 |\\n| `cards` | InsightCard[]（1~30） | 五段式洞察卡，见下 |\\n| `charts` | ChartSpec[]（0~30） | 由 chart-intent / chart-atomic 产出的图表 spec；没有可用数据时为 `[]` |\\n| `followups` | string[]（≤10） | 建议的下一步（可运行的技能、可补充的条件、值得关注的方向） |\\n\\n## Fact（事实）\\n\\n| 字段 | 规则 |\\n| --- | --- |\\n| `id` | `f-` 开头小写标识（`f-count`、`f-aum-missing`），全表唯一 |\\n| `metric` | 指标 id（见 metric-catalog），如 `customer_count`、`aum` |\\n| `label` | 中文短标签，如「客群规模」「总资产」 |\\n| `value` | 数值；MISSING/SUPPRESSED 时必须为 `null` |\\n| `unit` | 只能是 `人` `元` `%` `pp` `分` |\\n| `sample_size` | 计算该事实的样本量（整数）。客群人数事实填人数本身；MISSING 填 `null` |\\n| `status` | `AVAILABLE`（有数）/ `SUPPRESSED`（样本太小被抑制）/ `MISSING`（数据未接入） |\\n| `query_id` | 证据来源标记：`cohort.count`（服务端人数）、`catalog.<metric>`（目录中未接入的指标）等 |\\n| `evidence` | 1~10 条来源说明（中文），写清\\"来自服务端核验的什么\\" |\\n| `role` | `OBSERVED`（直接观测）/ `BENCHMARK` / `POST_EXCLUSION` / `DERIVED` |\\n| `denominator_id` | 百分比的分子分母引用；非百分比填 `null` |\\n| `derived_from` | 派生来源事实 id 数组；直接观测填 `[]` |\\n| `exclusions_applied` | 已应用的排除项；未排除填 `[]` |\\n\\n允许登记为 AVAILABLE 的数值只有三类：\\n\\n1. **服务端核验的人数**（`count.value`，`query_id` 用 `cohort.count`）。\\n2. **条件原文中的阈值**（如「转入金额 ≥ 500000 元」中的 500000）。条件阈值事实用最接近的目录指标 id 作 `metric`、条件原文单位作 `unit`，并在 `evidence` 注明「来自服务端核验的圈选条件」——这样正文才能用 `{fact:id}` 安全引用这些数字。\\n3. **`tag_stats` 与 `baseline.tag_stats` 中服务端注入的标签统计**（本节下一小节）。服务端会逐条复核：`query_id` 命中 `tagstat.*`、`benchmark.*`、`diff.*` 的事实，取值必须与注入的统计量一致，否则整条被丢弃；数值统计的 `unit` 必须与注入值相同，未登记单位的标签统计不得登记为 AVAILABLE。\\n\\n除此之外的一切数值都必须来自确定性数据系统，没有就登记 `MISSING`。\\n\\n## 标签统计（tag_stats）与脱敏明细（sample_rows）\\n\\n当用户在左侧标签栏选择了标签并运行技能时，`cohort_context` 会多出两个字段：\\n\\n- `tag_stats`：每个所选标签一条，字段为 `tag_id` / `label` / `tag_type` / `unit` / `unit_source` / `plan_tag` / `status` / `reason` / `sample_size`，以及二选一的 `numeric` 或 `categories`。\\n  - `status` 为 `AVAILABLE` 时才可作为事实来源；`SUPPRESSED`（存在小于 20 人的分类，整组已抑制）、`MISSING`（取数失败或人数漂移）、`UNSUPPORTED`（该标签类型不支持统计）一律登记为 `MISSING` 事实并复述 `reason`。\\n  - `numeric`：`{n, missing, min, max, sum, avg, median}`，`query_id` 用 `tagstat.<tag_id>.<统计名>`（如 `tagstat.812.avg`）。数值已按标签登记的量纲折算到 `unit` 上（比率类已转成百分数，万元量纲已折算成元），**不要**再自行换算。\\n  - `categories`：`[{code, label, count, share}]`，计数用 `tagstat.<tag_id>.cat.<code>`（单位「人」），占比用 `tagstat.<tag_id>.share.<code>`（单位「%」）；占比事实必须带 `denominator_id`（指向人数事实）。分布的单位是固有的，不受该标签是否登记量纲影响。\\n  - `unit` 为 `null` 表示该标签的数值统计没有登记量纲：它的 `numeric` 数字只能用于定性描述与边界说明，**不得**登记为 AVAILABLE 事实；`categories` 的计数与占比不受此限制。\\n  - `plan_tag` 为 `true` 表示该列已被圈选条件截断（例如条件是「AUM ≥ 50 万」，那么 AUM 的均值有偏），结论里必须声明这一点。\\n- `sample_rows`：`{columns, rows, limit, masked, note}`，是所选标签列在客群内的脱敏明细（客户号已打码，最多 100 行）。它只用于观察分布形态与异常值，**不得**据以产出任何个体级结论或精确统计；正式数值一律引用 `tag_stats` 或人数。\\n\\n`stats_note` 非空时说明本轮取数已降级，要在 `boundary` 里如实转述。\\n\\n## 对照客群基准（baseline）\\n\\n当用户在运行技能前选择了「对照客群」时，`cohort_context` 会多出 `baseline`：`{group_id, name, count, tag_stats, stats_note}`。`tag_stats` 的结构与当前客群完全一致，字段含义相同；`plan_tag` 表示该列被对照客群自身的条件截断，做差与结论时要一并声明。`baseline` 是服务端核验的已保存客群，同一批标签列的两套统计可以直接比较。\\n\\n- 对照统计登记为事实时，`query_id` 用 `benchmark.<tag_id>.<统计名>` / `benchmark.<tag_id>.cat.<code>` / `benchmark.<tag_id>.share.<code>`，`role` 填 `BENCHMARK`；取值必须与注入值一致，服务端同样逐条复核。\\n- 客群与对照的差值登记为派生事实：`query_id` 用 `diff.<tag_id>.<统计名>`（数值差，单位与量纲同该统计）、`diff.<tag_id>.cat.<code>`（人数差，单位「人」）、`diff.<tag_id>.share.<code>`（占比差，单位 `pp`）；`role` 填 `DERIVED`，`derived_from` 填两侧事实 id。差值只在两侧同口径（均 AVAILABLE 且单位相同）时成立；只有一侧可用时不得登记差值。\\n- 差异 = 客群值 − 对照值；方向说明（高于/低于）本身不做价值判断，高与低都不等于好与坏。\\n- `baseline.stats_note` 非空时说明对照取数已降级，`comparison` 段与 `boundary` 要如实转述。\\n- 没选对照客群时以上都不适用，`comparison` 段按无基准处理。\\n\\n## Statement（陈述段）\\n\\n`{ text, fact_ids }`：`text` 是中文陈述，事实数值写成 `{fact:id}` 占位符，`fact_ids` 列出本段引用的全部 id。`{fact:}` 只允许引用 AVAILABLE 事实；缺失数据改用自然语言说明。日期、版本号、阈值这类非事实数字可以直接写。\\n\\n## InsightCard（五段式卡片）\\n\\n| 段 | 要求 |\\n| --- | --- |\\n| `facts` | 事实陈述 + 条件复述；引用规模事实 |\\n| `comparison` | `{text, fact_ids, benchmark_fact_ids, difference_fact_ids}`。有对照客群时写清比较对象（名称与人数）与差异事实；没有基准数据时如实写「本轮未接入基准数据，无法对比」并把两个数组填空数组 |\\n| `diagnosis` | `{text, fact_ids, basis}`，`basis ∈ RULE / STAT / HYPOTHESIS`。事实技能只做方法性说明（如「缺少基准，未形成诊断」），basis 用 `RULE`；`statistical_evidence` 填 `null` |\\n| `action` | `{text, fact_ids, population_fact_id, priority}`。不产出行动对象时 `population_fact_id: null`、`priority: \\"NONE\\"` |\\n| `boundary` | `{text, data_as_of, skill_version, sample_fact_id, metric_definitions}`。`text` 写适用边界与缺失影响；`data_as_of` 与 `skill_version` 先写空串（服务端回填）；`sample_fact_id` 填规模事实 id，无人数时写 `\\"\\"`；`metric_definitions` 是本次使用/欠缺的指标口径说明（每条一句话） |\\n\\n## 完整示例\\n\\n```insight-result\\n{\\n  \\"status\\": \\"PARTIAL\\",\\n  \\"reasons\\": [\\n    \\"仅接入服务端核验的客群条件与有效人数，资产、产品与行为指标未接入\\",\\n    \\"缺少基准数据，不产出对比与诊断结论\\"\\n  ],\\n  \\"facts\\": [\\n    {\\n      \\"id\\": \\"f-count\\",\\n      \\"metric\\": \\"customer_count\\",\\n      \\"label\\": \\"客群规模\\",\\n      \\"value\\": 1268,\\n      \\"unit\\": \\"人\\",\\n      \\"sample_size\\": 1268,\\n      \\"status\\": \\"AVAILABLE\\",\\n      \\"query_id\\": \\"cohort.count\\",\\n      \\"evidence\\": [\\"服务端按当前已核验方案统计的人数\\"],\\n      \\"role\\": \\"OBSERVED\\",\\n      \\"denominator_id\\": null,\\n      \\"derived_from\\": [],\\n      \\"exclusions_applied\\": []\\n    },\\n    {\\n      \\"id\\": \\"f-aum-missing\\",\\n      \\"metric\\": \\"aum\\",\\n      \\"label\\": \\"总资产\\",\\n      \\"value\\": null,\\n      \\"unit\\": \\"元\\",\\n      \\"sample_size\\": null,\\n      \\"status\\": \\"MISSING\\",\\n      \\"query_id\\": \\"catalog.aum\\",\\n      \\"evidence\\": [\\"本轮未接入指标取数通道，无法计算总资产\\"],\\n      \\"role\\": \\"OBSERVED\\",\\n      \\"denominator_id\\": null,\\n      \\"derived_from\\": [],\\n      \\"exclusions_applied\\": []\\n    },\\n    {\\n      \\"id\\": \\"f-holding-missing\\",\\n      \\"metric\\": \\"product_holding_rate\\",\\n      \\"label\\": \\"产品持有率\\",\\n      \\"value\\": null,\\n      \\"unit\\": \\"%\\",\\n      \\"sample_size\\": null,\\n      \\"status\\": \\"MISSING\\",\\n      \\"query_id\\": \\"catalog.product_holding_rate\\",\\n      \\"evidence\\": [\\"本轮未接入指标取数通道，无法计算产品持有结构\\"],\\n      \\"role\\": \\"OBSERVED\\",\\n      \\"denominator_id\\": null,\\n      \\"derived_from\\": [],\\n      \\"exclusions_applied\\": []\\n    }\\n  ],\\n  \\"cards\\": [\\n    {\\n      \\"id\\": \\"card-overview\\",\\n      \\"title\\": \\"客群概况\\",\\n      \\"facts\\": {\\n        \\"text\\": \\"本客群由「近30天转入金额至少500000元」且「未持有理财产品」两个条件圈定，共 {fact:f-count}。\\",\\n        \\"fact_ids\\": [\\"f-count\\"]\\n      },\\n      \\"comparison\\": {\\n        \\"text\\": \\"本轮未接入基准数据，无法回答「和同类客户比怎么样」。\\",\\n        \\"fact_ids\\": [],\\n        \\"benchmark_fact_ids\\": [],\\n        \\"difference_fact_ids\\": []\\n      },\\n      \\"diagnosis\\": {\\n        \\"text\\": \\"缺少对比对象与指标数据，本轮未形成诊断；条件的业务含义不等于客户的经营结论。\\",\\n        \\"fact_ids\\": [],\\n        \\"basis\\": \\"RULE\\",\\n        \\"statistical_evidence\\": null\\n      },\\n      \\"action\\": {\\n        \\"text\\": \\"本轮不产出行动对象：既没有客户级产品数据，也没有营销与适当性规则。\\",\\n        \\"fact_ids\\": [],\\n        \\"population_fact_id\\": null,\\n        \\"priority\\": \\"NONE\\"\\n      },\\n      \\"boundary\\": {\\n        \\"text\\": \\"结论仅覆盖客群条件与规模；资产、产品、人口与行为表现均未接入，不能据此推断客户特征或配置缺口。\\",\\n        \\"data_as_of\\": \\"\\",\\n        \\"skill_version\\": \\"\\",\\n        \\"sample_fact_id\\": \\"f-count\\",\\n        \\"metric_definitions\\": [\\n          \\"customer_count：按当前已核验方案服务端统计的客户数\\",\\n          \\"aum：客户名下资产总额，本轮未接入\\",\\n          \\"product_holding_rate：持有指定产品的客户占比，本轮未接入\\"\\n        ]\\n      }\\n    }\\n  ],\\n  \\"charts\\": [\\n    {\\n      \\"schema_version\\": 1,\\n      \\"id\\": \\"chart-scale\\",\\n      \\"title\\": \\"客群规模\\",\\n      \\"kind\\": \\"kpi\\",\\n      \\"intent\\": \\"single_value\\",\\n      \\"unit\\": \\"人\\",\\n      \\"metric_label\\": \\"客户数\\",\\n      \\"series\\": [\\n        {\\n          \\"name\\": \\"客群规模\\",\\n          \\"fact_ids\\": [\\"f-count\\"],\\n          \\"points\\": [{ \\"category\\": \\"客户数\\", \\"column\\": null, \\"fact_id\\": \\"f-count\\", \\"value\\": 1268 }]\\n        }\\n      ],\\n      \\"annotations\\": [],\\n      \\"reconcile\\": [],\\n      \\"zero_baseline\\": true,\\n      \\"orientation\\": \\"vertical\\"\\n    }\\n  ],\\n  \\"followups\\": [\\n    \\"运行 diagnostic-analysis：在接入基准数据后对比同类客群的资产与产品结构\\",\\n    \\"补充产品持有相关条件后再圈选，可缩小到更聚焦的客群\\"\\n  ]\\n}\\n```\\n\\n## 常见错误\\n\\n- 写了「约 1200 人」「近七成」这类未绑定事实的数字——必须用 `{fact:f-count}`。\\n- 把估算或经验值写成事实——宁可 `MISSING`，不可编造。\\n- 用 `{fact:}` 引用 MISSING 事实——面板会拒绝渲染；缺失只做文字说明。\\n- 段内 `text` 引用了 `{fact:id}` 却没写进该段的 `fact_ids`——服务端会按引用自动补齐；引用了不存在或不可用事实的，整卡丢弃。\\n- 图表 spec 引用了 `facts` 中不存在、或数值与事实不一致的 `fact_id`——spec 里的 `value` 必须与事实值完全相等。\\n- 忘了 `insight-result` 块或 JSON 不合法——结果是降级为纯文本，卡片和图表全部丢失。\\n- 给标签统计事实写了 `tagstat.*` 的 `query_id` 却改了数值，或引用了未选择标签、已抑制、未登记单位的统计量——服务端会整条丢弃。\\n- 给对照统计写了 `benchmark.*` / `diff.*` 却自行改数，或对只有一侧可用的统计量造差值——同样整条丢弃。\\n- 把 `sample_rows` 里的明细当成统计口径，或据它写出个体级结论。\\n"}], "skill_md": "---\\nname: \\"fact-analysis\\"\\ndescription: \\"面向任意已核验客群回答“这批客户是什么样”：把服务端核验的客群条件与有效人数整理成事实卡与图表，指标数据未接入时显性声明缺口。用户要客群概况、特征描述、规模与条件复述，或诊断/行动技能需要先补齐事实时使用；不要用它产出对比结论、因果判断或行动建议。\\"\\nargument-hint: \\"分析目标或关注点（可留空）\\"\\nuser-invocable: true\\ndisable-model-invocation: false\\nallowed-tools: [\\"Read\\", \\"Skill\\"]\\n---\\n\\n# 基础事实分析\\n\\n你要回答的是「这批客户是什么样」——描述现状，不下结论。\\n\\n## 证据来源\\n\\n本轮唯一的确定性证据在提示词末尾的「服务端客群上下文」（cohort_context）里，逐项理解：\\n\\n- `name` / `revision` / `plan_hash`：客群名称与方案版本，写进卡片边界。\\n- `plan.tree`：已核验的圈选条件。叶子节点形如\\n  `{kind:\\"TAG_PREDICATE\\", name:\\"近30天转入金额\\", operator:\\">=\\", values:[\\"500000\\"], code_options:[{code,label}], time_constraint:\\"近30天\\"}`；\\n  `Group{logic:\\"AND\\"|\\"OR\\", children}` 表达组合；`SCOPE_ALL` 表示全量客户；`DERIVED_PREDICATE` 用 `expression` 表达计算条件。\\n  `intent_plan.requirements[].business_meaning` 与 `plan.summary` 是需求层的业务含义，可直接引用。\\n- `count.value`：服务端核验过的人数（只在 `status=\\"COUNTED\\"` 时存在）。这是最基础的事实，任何情况下都可使用。\\n- `count` 为 null 表示方案尚未统计人数，不能推断，也不能拿条件估算。\\n- `tag_stats`：用户在左侧标签栏选择的标签，由服务端从当前客群里取出的聚合统计（数值型给人数/缺失/最小/最大/合计/均值/中位数，分类型给取值分布与占比）。`status=\\"AVAILABLE\\"` 时分布计数与占比即可用；数值统计还要求 `unit` 非 null（未登记量纲的标签只能描述形态，不能出数字）。`query_id` 原样抄 `tagstat.*`，数值已由服务端按登记量纲折算（比率转百分数、万元折元），不要再换算。`plan_tag=true` 的列已被条件截断，结论里要声明。\\n- `sample_rows`：所选标签列的脱敏明细（最多 100 行）。只用来观察分布形态，不能据此产出精确统计或个体结论。\\n\\n除此之外的指标（资产、产品、人口属性、行为、渠道……）如果不在 `tag_stats` 里，就仍然没有取数通道——用户没有选择对应标签，或者该标签未登记单位。**未经服务端核验的数字不得出现在输出中**，包括示例、估算和\\"行业经验值\\"。报告会被当作经营事实使用，编造数字是这个平台最严重的错误。\\n\\n## 工作步骤\\n\\n1. 读 `references/metric-catalog.md`，按目录规划「理论上应该看什么」（规模 / 客户结构 / 资产 / 产品 / 行为五组）。\\n2. 对照目录盘点证据：先看 `tag_stats` 里哪些条目可用，再检查用户是否漏选了值得分析的标签（在 `followups` 里建议补充选择）。把最相关的 3~6 个缺口登记为 MISSING 事实。\\n3. 复述条件用业务语言：优先 `code_options` 的 label 而不是码值，保留时间约束与单位；不要自行做单位换算。\\n4. 判断是否配图：有满足样本规则的数值事实时，调用 **chart-intent** 技能选图（它会再调用 chart-atomic 产出 spec）。没有可用数值就不配图，宁缺毋滥。\\n5. 按 `references/result-contract.md` 组装 `insight-result` 块收尾。\\n\\n## 判断规则\\n\\n- **事实 ≠ 诊断**：可以写「理财持有率 23.4%」，不能写「理财配置不足」。后者需要基准与规则，属于 diagnostic-analysis 的职责。越界会让报告失去可信度。\\n- **数值绑定事实**：正文与卡片里的事实数值一律写成 `{fact:f-xxx}` 引用，并在该段的 `fact_ids` 中登记。这样渲染、复制与复核都能追溯到同一份事实表。`{fact:}` 只能引用 AVAILABLE 的事实。\\n- **缺失显性化**：缺什么就写「本轮未接入 XX」并说明影响，而不是悄悄省略；沉默会让读者把缺失当成\\"没问题\\"。\\n- **样本抑制**：人数小于 20（平台抑制阈值）时不出图、不强调具体人数，改为说明样本量不足以展示。这是隐私要求。\\n\\n## 输出\\n\\n先写正文（中文、分段、不复述 JSON），再以 ```insight-result 围栏块输出结构化结果；块内字段与示例见 `references/result-contract.md`，块内必须是严格 JSON（字符串里不要用英文双引号）。图表 spec 由 chart-intent / chart-atomic 产出，不要自己发明字段。\\n\\n完成后不改动客群条件、人数、方案版本，也不创建实体客群。\\n"}', 1, 'seed', 'seed', NOW(), NOW(), NOW())
ON DUPLICATE KEY UPDATE draft_json=VALUES(draft_json), published_json=VALUES(published_json),
  row_version=row_version+1, update_by='seed', update_time=NOW(), publish_time=NOW();

INSERT INTO ts_agent_skill (name, draft_json, published_json, row_version, create_by, update_by, create_time, update_time, publish_time)
VALUES ('chart-atomic', '{"name": "chart-atomic", "display_name": "图表原子层", "description": "把一组已核验事实编译为一张符合平台图表协议的 InsightChartSpec（kpi/table/bar/stacked_bar/heatmap/funnel）。当图表意图已明确、需要产出或修订具体图表 spec 时使用；字段规则与对账要求见技能内参考资料，任何字段都不能自行发明。用户不应直接调用本技能。", "instructions": "# 图表原子层\\n\\n输入：一组已核验事实、一个图表意图（`intent`）、以及要表达的取数结构；输出：**一张** `InsightChartSpec`。spec 是声明式协议（不是 ECharts option），由平台前端渲染、校验并导出。\\n\\n## 产出步骤\\n\\n1. 读 `references/marks.md`：确认所选图形（kind）的表达语义与数据形态匹配。\\n2. 读 `references/encoding-rules.md`：按单位、方向、系列与格子的规则组装 `series` / `points`。\\n3. 读 `references/spec-guard.md`：这是平台的渲染守卫（chartGuard），**逐条自查**——不满足的 spec 会被前端拒绝渲染，显示为错误。\\n4. 输出：一张图一个 ```json 围栏块，块内只有 spec 对象；随后用一句话说明该图表达什么、以及任何未展示的类别。\\n\\n## 硬性判断\\n\\n- **数值只来自事实**：`points[].value` 必须与事实表里对应 `fact_id` 的 `value` 完全相等；不一致的图会被守卫拒绝。没有事实就没有图。\\n- **缺失即抑制**：MISSING/SUPPRESSED 事实对应的格子 `value` 写 `null`（`sample_size` 也是 null）——渲染为\\"已抑制\\"占位，不得补零或省略该格子。\\n- **不发明字段**：spec 顶层、series、point、annotation、reconcile 都只允许协议列出的字段；多余字段同样会被拒绝。\\n- **一张图一个意图**：多意图拆成多张图，交给 chart-compose 组合；不要在一张图里塞多种表达。\\n\\n## 与其他技能的关系\\n\\n- 图表 **选择**（画什么、要不要画）属于 chart-intent；本技能只负责\\"怎么把已定意图画成合法 spec\\"。\\n- 多图组合（顺序、仪表板）属于 chart-compose。\\n- 修订 spec（用户改图需求）同样走本技能：改字段后重新自查。\\n\\n## 常见失败与修正\\n\\n| 失败 | 修正 |\\n| --- | --- |\\n| 类别超过 12 | 选择业务关键 ≤12 个类别并说明截断；不能造\\"其他\\"桶 |\\n| 百分比堆叠没有分组对账 | 每个类别补一条 `percentage` 对账（引用该类别全部格子） |\\n| KPI 放多个事实 | KPI 只允许一格；多指标拆多张 KPI 或用 table |\\n| 漏斗未单调 | 检查逐层人数是否单调不增；数据不满足就不要画漏斗 |\\n| 注解里有阿拉伯数字 | 数字改成 `{fact:id}` 占位；注解只允许占位形式的数字 |", "argument_hint": "数据画像、图表意图与事实 id 列表", "version": "1.0.0", "category": "chart", "user_invocable": false, "disable_model_invocation": false, "allowed_tools": ["Read", "Skill"], "resources": [{"path": "references/encoding-rules.md", "content": "# 编码规则\\n\\n## 单位（unit）\\n\\n| unit | 用途 | 注意 |\\n| --- | --- | --- |\\n| `人` | 客户数、触达数 | 整数；0 或 ≥20（抑制阈值）才允许展示 |\\n| `元` | 金额 | 保持原始数值，不换算单位（不写\\"万元\\"） |\\n| `%` | 占比 | 必须有分母事实（`denominator_id`）；值域 0~100 |\\n| `pp` | 百分点差 | 差异类指标（客群值 − 基准值） |\\n| `分` | 评分、点数 | 评分类事实 |\\n\\n一张图的 `unit` 是单一的；混合单位的表达拆图。\\n\\n## 方向（orientation）\\n\\n- `horizontal`：类别名较长（中文机构名、产品名）或多于 6 个类别时的默认选择——横向条更好读。\\n- `vertical`：类别少且名称短，或强调序列（如时间）时使用。\\n- 该字段对所有 kind 都必须填写（`kpi`/`table` 也填 `vertical`）。\\n\\n## 系列（series）与格子（points）\\n\\n- 每个系列：`{ name(≤24字), fact_ids[], points[] }`；`fact_ids` 必须与格子里的 `fact_id` 一一对应（集合相等）。\\n- 每个格子：`{ category(≤24), column, fact_id, value }`。\\n  - 非矩阵图（非 heatmap）`column` 必须为 `null`。\\n  - heatmap 的 `column` 是第二维（≤24 字）。\\n- 同一系列内 `(category, column)` 不能重复。\\n- 类别去重后总数 ≤12；列去重后 ≤12。超过时截断——选择业务最关键的类别，并在说明里写明还有多少类别未展示。\\n- 事实值缺失（MISSING/SUPPRESSED）的格子：`value: null`，事实侧 `sample_size: null`。\\n\\n## 标题与标识\\n\\n- `id`：`^[a-z][a-z0-9_.-]{0,79}$`（如 `chart-holding-rate`），用于引用与导出文件名。\\n- `title` ≤80 字；`metric_label` ≤40 字；用业务语言（「产品持有率」而不是「rate_1」）。\\n\\n## 对账（reconcile）\\n\\n对账是图表可信度的锚：读者能验证\\"这部分加起来等于整体\\"。\\n\\n| kind | 何时必须 | 规则 |\\n| --- | --- | --- |\\n| `sum` | 展示组成且各格可加 | `fact_ids` 之和 === `total_fact_id` 事实值（tolerance ≤0.05） |\\n| `percentage` | 占比堆叠（unit=%） | 每类别一条，`fact_ids` 为该类别全部格子，合计 100±tolerance |\\n| `funnel` | 漏斗图 | `fact_ids` **与展示顺序完全一致**，且逐格单调不增 |\\n\\n不满足对账时优先修正数据选择（舍弃不可加的格子），而不是硬凑。\\n\\n## 标注（annotations）\\n\\n- 最多 8 条；`text` ≤500 字，其中**任何阿拉伯/全角数字都必须写成 `{fact:id}` 占位**（守卫会检查占位之外没有数字），`fact_ids` 声明本标注引用的全部事实。\\n- 标注用于指出拐点、阈值线或口径提示（如「口径：近30天」——注意\\"30\\"是数字，需改写为「口径：近一月」或改用事实占位）。\\n\\n## 零基线\\n\\n`zero_baseline` 恒为 `true`：柱状与漏斗从 0 起，避免视觉夸大；这是平台统一的诚实性要求。\\n"}, {"path": "references/marks.md", "content": "# 图形（Marks）\\n\\n平台支持六种图形，各自对应确定的表达语义。图形与意图（intent）必须匹配，否则渲染守卫会拒绝。\\n\\n| kind | 表达 | 数据形态 | 配套 intent |\\n| --- | --- | --- | --- |\\n| `kpi` | 单个关键数值 | 恰好 1 个格子、1 个系列 | `single_value` |\\n| `table` | 精确读数（守卫通过后以可访问表格渲染） | 类别 × 系列 | 任意 intent |\\n| `bar` | 类别间比较、分布 | 1~8 个系列，类别 ≤12 | `compare_categories` / `show_distribution` |\\n| `stacked_bar` | 构成（占比或绝对量堆叠） | 1~8 个系列 | `show_composition` |\\n| `heatmap` | 二维矩阵（类别 × 列） | 恰好 1 个系列，格子带 `column` | `show_matrix` |\\n| `funnel` | 逐级收窄的转化 | 恰好 1 个系列、单调递减 | `show_conversion` |\\n\\n## 选择提示\\n\\n- 一个数说清的事，用 `kpi`；精确对读，用 `table`。\\n- 比较/分布：类别少且量纲一致用 `bar`；类别多但需要精确值，`table` 比堆叠条更诚实。\\n- 构成：占总量且各组可加时用 `stacked_bar`；占比堆叠必须带分组对账。\\n- 矩阵：两个维度（如 AUM 段 × 风险等级）呈现密度/差异时用 `heatmap`；格子缺失用抑制占位。\\n- 漏斗：只有在各层人数来自同一口径、且单调递减时才画；任何一层是估算都不画。\\n\\n## 平台既有词表\\n\\n守卫中的 `intent → kind` 固定映射（不可更改）：\\n\\n```\\nsingle_value      → kpi\\ncompare_categories→ bar\\nshow_composition  → stacked_bar\\nshow_distribution → bar\\nshow_matrix       → heatmap\\nshow_conversion   → funnel\\ntable             → 任意 intent\\n```\\n\\n## 与旧平台词表的对应\\n\\n内容体系中的「六图表原子」（KPI、表格、柱状、堆叠、热力、漏斗）就是以上六种；不再引入桑基、地图、树图等新 kind——渲染与守卫没有对应的支持，产出即失败。\\n"}, {"path": "references/spec-guard.md", "content": "# 渲染守卫清单（spec-guard）\\n\\n平台前端在渲染与导出前会执行完整的 spec 校验（chartGuard）。**任何一条不满足，该图整体不渲染**。产出 spec 后逐条自查。\\n\\n## 1. 字段与形状\\n\\n- [ ] spec 顶层只允许这些键：`schema_version, id, title, kind, intent, unit, metric_label, series, annotations, reconcile, zero_baseline, orientation`。\\n- [ ] `series[]` 只允许：`name, fact_ids, points`；`points[]` 只允许：`category, column, fact_id, value`。\\n- [ ] `reconcile[]` 只允许：`kind, fact_ids, total_fact_id, tolerance`；`annotations[]` 只允许：`text, fact_ids`。\\n- [ ] `schema_version` = `1`；`zero_baseline` = `true`（布尔）。\\n\\n## 2. 类型与意图\\n\\n- [ ] `kind ∈ {kpi, table, bar, stacked_bar, heatmap, funnel}`。\\n- [ ] `intent` 与 `kind` 匹配：`single_value→kpi`、`compare_categories→bar`、`show_composition→stacked_bar`、`show_distribution→bar`、`show_matrix→heatmap`、`show_conversion→funnel`；`table` 允许任意 intent。\\n- [ ] `orientation ∈ {horizontal, vertical}`；`unit ∈ {人, 元, %, pp, 分}`。\\n- [ ] 文字长度：`id`≤80、`title`≤80、`metric_label`≤40、系列名≤24、`category`≤24、`column`≤24。\\n- [ ] 所有文字不含 `<`（防注入）。\\n\\n## 3. 事实绑定\\n\\n- [ ] 每个 `point.fact_id` 都能在事实表中找到；`fact.unit === spec.unit`；**`fact.value === point.value`（严格相等）**。\\n- [ ] AVAILABLE 事实才可出现在图里：`sample_size` 为整数且 ≥20（平台抑制阈值）。\\n- [ ] `unit=\\"人\\"` 的事实值：整数，且为 0 或 ≥20。\\n- [ ] `unit=\\"%\\"` 的事实：`denominator_id` 必须指向可用的分母事实（值>0），值域 0~100；若 `calculation=\\"WEIGHTED\\"`，`weights` 的键必须与 `derived_from` 完全一致、非负且合计为 1，加权结果与事实值一致（±0.01）；若 `derived_from` 非空，`sum(derived_from 事实值) / denominator × 100` 与事实值一致（±0.01）。\\n- [ ] MISSING / SUPPRESSED 事实的格子：`point.value` 必须为 `null` 且事实 `sample_size` 为 `null`——这是\\"已抑制\\"的合法形态，渲染为占位而非数值。\\n\\n## 4. 系列与格子\\n\\n- [ ] `series` 数量 1~8；`kpi` / `heatmap` / `funnel` 恰好 1 个系列。\\n- [ ] 每个系列 `points` 数量 1~100；`fact_ids` 集合与格子引用集合**完全相等**。\\n- [ ] 同一系列内 `(category, column)` 组合不重复。\\n- [ ] 全部类别去重 ≤12；全部列去重 ≤12。\\n- [ ] `heatmap` 的格子必须带 `column`；**其他所有 kind 的 `column` 必须为 `null`**（包括 table）。\\n- [ ] `kpi` 的全部格子数必须为 1。\\n\\n## 5. 对账\\n\\n- [ ] `reconcile` ≤12 条；每条 `fact_ids` 非空、不重复、且都是图上已展示的格子。\\n- [ ] `tolerance ∈ [0, 0.05]`。\\n- [ ] `kind=\\"sum\\"`：必须给 `total_fact_id`（可用事实、单位与图一致），且格子之和 = 总值（±tolerance）。\\n- [ ] `kind=\\"percentage\\"`：`unit` 必须为 `%`，格子之和 = 100（±tolerance）。\\n- [ ] `kind=\\"funnel\\"`：各格值单调不增（`v[i] ≤ v[i-1]`）。\\n- [ ] `kind=\\"funnel\\"` 的图：`unit=\\"人\\"`，且必须有一条 `funnel` 对账，其 `fact_ids` 与展示顺序（逐个格子）**完全一致**。\\n- [ ] `unit=\\"%\\"` 的 `stacked_bar`：每个类别都要有一条 `percentage` 对账，覆盖该类别全部格子。\\n\\n## 6. 标注\\n\\n- [ ] ≤8 条；`text` ≤500 字；`fact_ids` 1~10 个且都是 AVAILABLE 事实。\\n- [ ] `text` 中出现的每个 `{fact:id}` 都必须在该条 `fact_ids` 中。\\n- [ ] `text` 去掉 `{fact:...}` 占位后**不得含任何数字字符**（含全角０-９）——\\"近30天\\"要改写为\\"近一月\\"，或把数字做成事实占位。\\n\\n## 自查方法\\n\\n产出后给自己过一遍这张清单，特别是：字段拼写、`column` 空值规则、`value` 与事实严格相等、对账完整性、标注数字。任何一条拿不准，就换成更保守的 kind（table）或删除该图。\\n"}], "skill_md": "---\\nname: \\"chart-atomic\\"\\ndescription: \\"把一组已核验事实编译为一张符合平台图表协议的 InsightChartSpec（kpi/table/bar/stacked_bar/heatmap/funnel）。当图表意图已明确、需要产出或修订具体图表 spec 时使用；字段规则与对账要求见技能内参考资料，任何字段都不能自行发明。用户不应直接调用本技能。\\"\\nargument-hint: \\"数据画像、图表意图与事实 id 列表\\"\\nuser-invocable: false\\ndisable-model-invocation: false\\nallowed-tools: [\\"Read\\", \\"Skill\\"]\\n---\\n\\n# 图表原子层\\n\\n输入：一组已核验事实、一个图表意图（`intent`）、以及要表达的取数结构；输出：**一张** `InsightChartSpec`。spec 是声明式协议（不是 ECharts option），由平台前端渲染、校验并导出。\\n\\n## 产出步骤\\n\\n1. 读 `references/marks.md`：确认所选图形（kind）的表达语义与数据形态匹配。\\n2. 读 `references/encoding-rules.md`：按单位、方向、系列与格子的规则组装 `series` / `points`。\\n3. 读 `references/spec-guard.md`：这是平台的渲染守卫（chartGuard），**逐条自查**——不满足的 spec 会被前端拒绝渲染，显示为错误。\\n4. 输出：一张图一个 ```json 围栏块，块内只有 spec 对象；随后用一句话说明该图表达什么、以及任何未展示的类别。\\n\\n## 硬性判断\\n\\n- **数值只来自事实**：`points[].value` 必须与事实表里对应 `fact_id` 的 `value` 完全相等；不一致的图会被守卫拒绝。没有事实就没有图。\\n- **缺失即抑制**：MISSING/SUPPRESSED 事实对应的格子 `value` 写 `null`（`sample_size` 也是 null）——渲染为\\"已抑制\\"占位，不得补零或省略该格子。\\n- **不发明字段**：spec 顶层、series、point、annotation、reconcile 都只允许协议列出的字段；多余字段同样会被拒绝。\\n- **一张图一个意图**：多意图拆成多张图，交给 chart-compose 组合；不要在一张图里塞多种表达。\\n\\n## 与其他技能的关系\\n\\n- 图表 **选择**（画什么、要不要画）属于 chart-intent；本技能只负责\\"怎么把已定意图画成合法 spec\\"。\\n- 多图组合（顺序、仪表板）属于 chart-compose。\\n- 修订 spec（用户改图需求）同样走本技能：改字段后重新自查。\\n\\n## 常见失败与修正\\n\\n| 失败 | 修正 |\\n| --- | --- |\\n| 类别超过 12 | 选择业务关键 ≤12 个类别并说明截断；不能造\\"其他\\"桶 |\\n| 百分比堆叠没有分组对账 | 每个类别补一条 `percentage` 对账（引用该类别全部格子） |\\n| KPI 放多个事实 | KPI 只允许一格；多指标拆多张 KPI 或用 table |\\n| 漏斗未单调 | 检查逐层人数是否单调不增；数据不满足就不要画漏斗 |\\n| 注解里有阿拉伯数字 | 数字改成 `{fact:id}` 占位；注解只允许占位形式的数字 |\\n"}', '{"name": "chart-atomic", "display_name": "图表原子层", "description": "把一组已核验事实编译为一张符合平台图表协议的 InsightChartSpec（kpi/table/bar/stacked_bar/heatmap/funnel）。当图表意图已明确、需要产出或修订具体图表 spec 时使用；字段规则与对账要求见技能内参考资料，任何字段都不能自行发明。用户不应直接调用本技能。", "instructions": "# 图表原子层\\n\\n输入：一组已核验事实、一个图表意图（`intent`）、以及要表达的取数结构；输出：**一张** `InsightChartSpec`。spec 是声明式协议（不是 ECharts option），由平台前端渲染、校验并导出。\\n\\n## 产出步骤\\n\\n1. 读 `references/marks.md`：确认所选图形（kind）的表达语义与数据形态匹配。\\n2. 读 `references/encoding-rules.md`：按单位、方向、系列与格子的规则组装 `series` / `points`。\\n3. 读 `references/spec-guard.md`：这是平台的渲染守卫（chartGuard），**逐条自查**——不满足的 spec 会被前端拒绝渲染，显示为错误。\\n4. 输出：一张图一个 ```json 围栏块，块内只有 spec 对象；随后用一句话说明该图表达什么、以及任何未展示的类别。\\n\\n## 硬性判断\\n\\n- **数值只来自事实**：`points[].value` 必须与事实表里对应 `fact_id` 的 `value` 完全相等；不一致的图会被守卫拒绝。没有事实就没有图。\\n- **缺失即抑制**：MISSING/SUPPRESSED 事实对应的格子 `value` 写 `null`（`sample_size` 也是 null）——渲染为\\"已抑制\\"占位，不得补零或省略该格子。\\n- **不发明字段**：spec 顶层、series、point、annotation、reconcile 都只允许协议列出的字段；多余字段同样会被拒绝。\\n- **一张图一个意图**：多意图拆成多张图，交给 chart-compose 组合；不要在一张图里塞多种表达。\\n\\n## 与其他技能的关系\\n\\n- 图表 **选择**（画什么、要不要画）属于 chart-intent；本技能只负责\\"怎么把已定意图画成合法 spec\\"。\\n- 多图组合（顺序、仪表板）属于 chart-compose。\\n- 修订 spec（用户改图需求）同样走本技能：改字段后重新自查。\\n\\n## 常见失败与修正\\n\\n| 失败 | 修正 |\\n| --- | --- |\\n| 类别超过 12 | 选择业务关键 ≤12 个类别并说明截断；不能造\\"其他\\"桶 |\\n| 百分比堆叠没有分组对账 | 每个类别补一条 `percentage` 对账（引用该类别全部格子） |\\n| KPI 放多个事实 | KPI 只允许一格；多指标拆多张 KPI 或用 table |\\n| 漏斗未单调 | 检查逐层人数是否单调不增；数据不满足就不要画漏斗 |\\n| 注解里有阿拉伯数字 | 数字改成 `{fact:id}` 占位；注解只允许占位形式的数字 |", "argument_hint": "数据画像、图表意图与事实 id 列表", "version": "1.0.0", "category": "chart", "user_invocable": false, "disable_model_invocation": false, "allowed_tools": ["Read", "Skill"], "resources": [{"path": "references/encoding-rules.md", "content": "# 编码规则\\n\\n## 单位（unit）\\n\\n| unit | 用途 | 注意 |\\n| --- | --- | --- |\\n| `人` | 客户数、触达数 | 整数；0 或 ≥20（抑制阈值）才允许展示 |\\n| `元` | 金额 | 保持原始数值，不换算单位（不写\\"万元\\"） |\\n| `%` | 占比 | 必须有分母事实（`denominator_id`）；值域 0~100 |\\n| `pp` | 百分点差 | 差异类指标（客群值 − 基准值） |\\n| `分` | 评分、点数 | 评分类事实 |\\n\\n一张图的 `unit` 是单一的；混合单位的表达拆图。\\n\\n## 方向（orientation）\\n\\n- `horizontal`：类别名较长（中文机构名、产品名）或多于 6 个类别时的默认选择——横向条更好读。\\n- `vertical`：类别少且名称短，或强调序列（如时间）时使用。\\n- 该字段对所有 kind 都必须填写（`kpi`/`table` 也填 `vertical`）。\\n\\n## 系列（series）与格子（points）\\n\\n- 每个系列：`{ name(≤24字), fact_ids[], points[] }`；`fact_ids` 必须与格子里的 `fact_id` 一一对应（集合相等）。\\n- 每个格子：`{ category(≤24), column, fact_id, value }`。\\n  - 非矩阵图（非 heatmap）`column` 必须为 `null`。\\n  - heatmap 的 `column` 是第二维（≤24 字）。\\n- 同一系列内 `(category, column)` 不能重复。\\n- 类别去重后总数 ≤12；列去重后 ≤12。超过时截断——选择业务最关键的类别，并在说明里写明还有多少类别未展示。\\n- 事实值缺失（MISSING/SUPPRESSED）的格子：`value: null`，事实侧 `sample_size: null`。\\n\\n## 标题与标识\\n\\n- `id`：`^[a-z][a-z0-9_.-]{0,79}$`（如 `chart-holding-rate`），用于引用与导出文件名。\\n- `title` ≤80 字；`metric_label` ≤40 字；用业务语言（「产品持有率」而不是「rate_1」）。\\n\\n## 对账（reconcile）\\n\\n对账是图表可信度的锚：读者能验证\\"这部分加起来等于整体\\"。\\n\\n| kind | 何时必须 | 规则 |\\n| --- | --- | --- |\\n| `sum` | 展示组成且各格可加 | `fact_ids` 之和 === `total_fact_id` 事实值（tolerance ≤0.05） |\\n| `percentage` | 占比堆叠（unit=%） | 每类别一条，`fact_ids` 为该类别全部格子，合计 100±tolerance |\\n| `funnel` | 漏斗图 | `fact_ids` **与展示顺序完全一致**，且逐格单调不增 |\\n\\n不满足对账时优先修正数据选择（舍弃不可加的格子），而不是硬凑。\\n\\n## 标注（annotations）\\n\\n- 最多 8 条；`text` ≤500 字，其中**任何阿拉伯/全角数字都必须写成 `{fact:id}` 占位**（守卫会检查占位之外没有数字），`fact_ids` 声明本标注引用的全部事实。\\n- 标注用于指出拐点、阈值线或口径提示（如「口径：近30天」——注意\\"30\\"是数字，需改写为「口径：近一月」或改用事实占位）。\\n\\n## 零基线\\n\\n`zero_baseline` 恒为 `true`：柱状与漏斗从 0 起，避免视觉夸大；这是平台统一的诚实性要求。\\n"}, {"path": "references/marks.md", "content": "# 图形（Marks）\\n\\n平台支持六种图形，各自对应确定的表达语义。图形与意图（intent）必须匹配，否则渲染守卫会拒绝。\\n\\n| kind | 表达 | 数据形态 | 配套 intent |\\n| --- | --- | --- | --- |\\n| `kpi` | 单个关键数值 | 恰好 1 个格子、1 个系列 | `single_value` |\\n| `table` | 精确读数（守卫通过后以可访问表格渲染） | 类别 × 系列 | 任意 intent |\\n| `bar` | 类别间比较、分布 | 1~8 个系列，类别 ≤12 | `compare_categories` / `show_distribution` |\\n| `stacked_bar` | 构成（占比或绝对量堆叠） | 1~8 个系列 | `show_composition` |\\n| `heatmap` | 二维矩阵（类别 × 列） | 恰好 1 个系列，格子带 `column` | `show_matrix` |\\n| `funnel` | 逐级收窄的转化 | 恰好 1 个系列、单调递减 | `show_conversion` |\\n\\n## 选择提示\\n\\n- 一个数说清的事，用 `kpi`；精确对读，用 `table`。\\n- 比较/分布：类别少且量纲一致用 `bar`；类别多但需要精确值，`table` 比堆叠条更诚实。\\n- 构成：占总量且各组可加时用 `stacked_bar`；占比堆叠必须带分组对账。\\n- 矩阵：两个维度（如 AUM 段 × 风险等级）呈现密度/差异时用 `heatmap`；格子缺失用抑制占位。\\n- 漏斗：只有在各层人数来自同一口径、且单调递减时才画；任何一层是估算都不画。\\n\\n## 平台既有词表\\n\\n守卫中的 `intent → kind` 固定映射（不可更改）：\\n\\n```\\nsingle_value      → kpi\\ncompare_categories→ bar\\nshow_composition  → stacked_bar\\nshow_distribution → bar\\nshow_matrix       → heatmap\\nshow_conversion   → funnel\\ntable             → 任意 intent\\n```\\n\\n## 与旧平台词表的对应\\n\\n内容体系中的「六图表原子」（KPI、表格、柱状、堆叠、热力、漏斗）就是以上六种；不再引入桑基、地图、树图等新 kind——渲染与守卫没有对应的支持，产出即失败。\\n"}, {"path": "references/spec-guard.md", "content": "# 渲染守卫清单（spec-guard）\\n\\n平台前端在渲染与导出前会执行完整的 spec 校验（chartGuard）。**任何一条不满足，该图整体不渲染**。产出 spec 后逐条自查。\\n\\n## 1. 字段与形状\\n\\n- [ ] spec 顶层只允许这些键：`schema_version, id, title, kind, intent, unit, metric_label, series, annotations, reconcile, zero_baseline, orientation`。\\n- [ ] `series[]` 只允许：`name, fact_ids, points`；`points[]` 只允许：`category, column, fact_id, value`。\\n- [ ] `reconcile[]` 只允许：`kind, fact_ids, total_fact_id, tolerance`；`annotations[]` 只允许：`text, fact_ids`。\\n- [ ] `schema_version` = `1`；`zero_baseline` = `true`（布尔）。\\n\\n## 2. 类型与意图\\n\\n- [ ] `kind ∈ {kpi, table, bar, stacked_bar, heatmap, funnel}`。\\n- [ ] `intent` 与 `kind` 匹配：`single_value→kpi`、`compare_categories→bar`、`show_composition→stacked_bar`、`show_distribution→bar`、`show_matrix→heatmap`、`show_conversion→funnel`；`table` 允许任意 intent。\\n- [ ] `orientation ∈ {horizontal, vertical}`；`unit ∈ {人, 元, %, pp, 分}`。\\n- [ ] 文字长度：`id`≤80、`title`≤80、`metric_label`≤40、系列名≤24、`category`≤24、`column`≤24。\\n- [ ] 所有文字不含 `<`（防注入）。\\n\\n## 3. 事实绑定\\n\\n- [ ] 每个 `point.fact_id` 都能在事实表中找到；`fact.unit === spec.unit`；**`fact.value === point.value`（严格相等）**。\\n- [ ] AVAILABLE 事实才可出现在图里：`sample_size` 为整数且 ≥20（平台抑制阈值）。\\n- [ ] `unit=\\"人\\"` 的事实值：整数，且为 0 或 ≥20。\\n- [ ] `unit=\\"%\\"` 的事实：`denominator_id` 必须指向可用的分母事实（值>0），值域 0~100；若 `calculation=\\"WEIGHTED\\"`，`weights` 的键必须与 `derived_from` 完全一致、非负且合计为 1，加权结果与事实值一致（±0.01）；若 `derived_from` 非空，`sum(derived_from 事实值) / denominator × 100` 与事实值一致（±0.01）。\\n- [ ] MISSING / SUPPRESSED 事实的格子：`point.value` 必须为 `null` 且事实 `sample_size` 为 `null`——这是\\"已抑制\\"的合法形态，渲染为占位而非数值。\\n\\n## 4. 系列与格子\\n\\n- [ ] `series` 数量 1~8；`kpi` / `heatmap` / `funnel` 恰好 1 个系列。\\n- [ ] 每个系列 `points` 数量 1~100；`fact_ids` 集合与格子引用集合**完全相等**。\\n- [ ] 同一系列内 `(category, column)` 组合不重复。\\n- [ ] 全部类别去重 ≤12；全部列去重 ≤12。\\n- [ ] `heatmap` 的格子必须带 `column`；**其他所有 kind 的 `column` 必须为 `null`**（包括 table）。\\n- [ ] `kpi` 的全部格子数必须为 1。\\n\\n## 5. 对账\\n\\n- [ ] `reconcile` ≤12 条；每条 `fact_ids` 非空、不重复、且都是图上已展示的格子。\\n- [ ] `tolerance ∈ [0, 0.05]`。\\n- [ ] `kind=\\"sum\\"`：必须给 `total_fact_id`（可用事实、单位与图一致），且格子之和 = 总值（±tolerance）。\\n- [ ] `kind=\\"percentage\\"`：`unit` 必须为 `%`，格子之和 = 100（±tolerance）。\\n- [ ] `kind=\\"funnel\\"`：各格值单调不增（`v[i] ≤ v[i-1]`）。\\n- [ ] `kind=\\"funnel\\"` 的图：`unit=\\"人\\"`，且必须有一条 `funnel` 对账，其 `fact_ids` 与展示顺序（逐个格子）**完全一致**。\\n- [ ] `unit=\\"%\\"` 的 `stacked_bar`：每个类别都要有一条 `percentage` 对账，覆盖该类别全部格子。\\n\\n## 6. 标注\\n\\n- [ ] ≤8 条；`text` ≤500 字；`fact_ids` 1~10 个且都是 AVAILABLE 事实。\\n- [ ] `text` 中出现的每个 `{fact:id}` 都必须在该条 `fact_ids` 中。\\n- [ ] `text` 去掉 `{fact:...}` 占位后**不得含任何数字字符**（含全角０-９）——\\"近30天\\"要改写为\\"近一月\\"，或把数字做成事实占位。\\n\\n## 自查方法\\n\\n产出后给自己过一遍这张清单，特别是：字段拼写、`column` 空值规则、`value` 与事实严格相等、对账完整性、标注数字。任何一条拿不准，就换成更保守的 kind（table）或删除该图。\\n"}], "skill_md": "---\\nname: \\"chart-atomic\\"\\ndescription: \\"把一组已核验事实编译为一张符合平台图表协议的 InsightChartSpec（kpi/table/bar/stacked_bar/heatmap/funnel）。当图表意图已明确、需要产出或修订具体图表 spec 时使用；字段规则与对账要求见技能内参考资料，任何字段都不能自行发明。用户不应直接调用本技能。\\"\\nargument-hint: \\"数据画像、图表意图与事实 id 列表\\"\\nuser-invocable: false\\ndisable-model-invocation: false\\nallowed-tools: [\\"Read\\", \\"Skill\\"]\\n---\\n\\n# 图表原子层\\n\\n输入：一组已核验事实、一个图表意图（`intent`）、以及要表达的取数结构；输出：**一张** `InsightChartSpec`。spec 是声明式协议（不是 ECharts option），由平台前端渲染、校验并导出。\\n\\n## 产出步骤\\n\\n1. 读 `references/marks.md`：确认所选图形（kind）的表达语义与数据形态匹配。\\n2. 读 `references/encoding-rules.md`：按单位、方向、系列与格子的规则组装 `series` / `points`。\\n3. 读 `references/spec-guard.md`：这是平台的渲染守卫（chartGuard），**逐条自查**——不满足的 spec 会被前端拒绝渲染，显示为错误。\\n4. 输出：一张图一个 ```json 围栏块，块内只有 spec 对象；随后用一句话说明该图表达什么、以及任何未展示的类别。\\n\\n## 硬性判断\\n\\n- **数值只来自事实**：`points[].value` 必须与事实表里对应 `fact_id` 的 `value` 完全相等；不一致的图会被守卫拒绝。没有事实就没有图。\\n- **缺失即抑制**：MISSING/SUPPRESSED 事实对应的格子 `value` 写 `null`（`sample_size` 也是 null）——渲染为\\"已抑制\\"占位，不得补零或省略该格子。\\n- **不发明字段**：spec 顶层、series、point、annotation、reconcile 都只允许协议列出的字段；多余字段同样会被拒绝。\\n- **一张图一个意图**：多意图拆成多张图，交给 chart-compose 组合；不要在一张图里塞多种表达。\\n\\n## 与其他技能的关系\\n\\n- 图表 **选择**（画什么、要不要画）属于 chart-intent；本技能只负责\\"怎么把已定意图画成合法 spec\\"。\\n- 多图组合（顺序、仪表板）属于 chart-compose。\\n- 修订 spec（用户改图需求）同样走本技能：改字段后重新自查。\\n\\n## 常见失败与修正\\n\\n| 失败 | 修正 |\\n| --- | --- |\\n| 类别超过 12 | 选择业务关键 ≤12 个类别并说明截断；不能造\\"其他\\"桶 |\\n| 百分比堆叠没有分组对账 | 每个类别补一条 `percentage` 对账（引用该类别全部格子） |\\n| KPI 放多个事实 | KPI 只允许一格；多指标拆多张 KPI 或用 table |\\n| 漏斗未单调 | 检查逐层人数是否单调不增；数据不满足就不要画漏斗 |\\n| 注解里有阿拉伯数字 | 数字改成 `{fact:id}` 占位；注解只允许占位形式的数字 |\\n"}', 1, 'seed', 'seed', NOW(), NOW(), NOW())
ON DUPLICATE KEY UPDATE draft_json=VALUES(draft_json), published_json=VALUES(published_json),
  row_version=row_version+1, update_by='seed', update_time=NOW(), publish_time=NOW();

INSERT INTO ts_agent_skill (name, draft_json, published_json, row_version, create_by, update_by, create_time, update_time, publish_time)
VALUES ('chart-compose', '{"name": "chart-compose", "display_name": "图表组合层", "description": "把多张图表组织成一次分析的配图方案：按“KPI → 差异/趋势 → 结构/原因 → 明细/行动”的信息顺序排序，套用概览/诊断/行动三类版式，控制总图数与去重。分析结果产生两张以上图表、或需要成体系的仪表板时使用；单张图不需要本技能。用户不应直接调用本技能。", "instructions": "# 图表组合层\\n\\n一次分析的多张图不是并列的，而是一条**阅读主线**。组合层决定：出几张、什么顺序、谁是主图。\\n\\n## 工作步骤\\n\\n1. 收集本轮已有的图表 spec（来自 chart-intent / chart-atomic）与它们的意图。\\n2. 按 `references/dashboard-layout.md` 选版式（概览 / 诊断 / 行动），并按信息顺序排序。\\n3. 去重与裁剪：同一意图、同一数据的图只留一张；总图数按 `references/storytelling.md` 的规则控制。\\n4. 输出：**有序的图表清单**（按最终顺序列出各图 id + 一句话角色），供分析技能放进 `insight-result` 的 `charts` 数组。\\n\\n## 组合原则\\n\\n- **一篇一条主线**：先给结论性数字（KPI），再给支撑（对比/结构），最后给可行动对象（明细/漏斗）。读者从上往下读，逻辑不回头。\\n- **少而精**：每张图必须能回答\\"它在主线里承担什么\\";承担不了就删。\\n- **顺序即阅读顺序**：平台按 `charts` 数组顺序渲染（KPI 类单独置顶成行），不要依赖随机摆放。\\n\\n## 版式与图数的对应\\n\\n| 版式 | 适用 | 典型结构 | 图数 |\\n| --- | --- | --- | --- |\\n| 概览 | 客群是什么样 | KPI 规模 → 分布/构成 | 2~4 |\\n| 诊断 | 哪里异常、为什么 | KPI 差异 → 对比条形 → 下钻矩阵 | 2~5 |\\n| 行动 | 接下来做什么 | KPI 对象数 → 漏斗 → 明细 | 2~4 |\\n\\n单张图（含单 KPI）说明不需要组合层，直接输出即可。", "argument_hint": "图表清单与分析主线", "version": "1.0.0", "category": "chart", "user_invocable": false, "disable_model_invocation": false, "allowed_tools": ["Read", "Skill"], "resources": [{"path": "references/dashboard-layout.md", "content": "# 仪表板版式\\n\\n三类版式对应三步分析链路。版式不是\\"模板套壳\\"，而是把信息顺序固化成读者熟悉的节奏。\\n\\n## 概览版式（客户是什么样）\\n\\n```\\n[KPI 行]  客群规模等 1~3 个关键数\\n[结构/分布]  1~2 张（分布柱状 / 构成堆叠）\\n[明细]  可选 1 张 table\\n```\\n\\n适用：fact-analysis 的产出配图。\\n\\n## 诊断版式（哪里值得关注）\\n\\n```\\n[KPI 行]  核心差异值（pp / 元），没有基准时不放\\n[对比]  客群 vs 基准的条形图\\n[下钻]  差异集中方向的矩阵或分组条形\\n```\\n\\n适用：diagnostic-analysis。差异图放在对比图之后，形成\\"先看差异、再看它集中在哪\\"的阅读路径。\\n\\n## 行动版式（接下来做什么）\\n\\n```\\n[KPI 行]  可执行对象数（没有规则链时省略）\\n[漏斗]  候选 → 过滤 → 可执行的逐层收窄\\n[明细]  优先级分布 table\\n```\\n\\n适用：action-decision。\\n\\n## 信息顺序（总原则）\\n\\n```\\nKPI（结论性数字）\\n   ↓\\n差异 / 趋势（和谁比、变化方向）\\n   ↓\\n结构 / 原因（由什么构成、集中在哪里）\\n   ↓\\n明细 / 行动对象（要做什么、从谁开始）\\n```\\n\\n任何版式都遵守这个从上到下的抽象度递减。把明细放最上面会让读者先陷入细节。\\n\\n## 平台渲染约定\\n\\n- `kind=\\"kpi\\"` 的图由面板统一置顶成 KPI 行，其余按 `charts` 数组顺序排列——KPI 在数组里的位置不影响展示，但为可读性仍放最前。\\n- 每张图有独立的标题与导出按钮；标题应能脱离上下文单独看懂（\\"产品持有率对比\\"而不是\\"对比图\\"）。\\n"}, {"path": "references/storytelling.md", "content": "# 数据故事规则\\n\\n## 每张图的角色声明\\n\\n组合时给每张图写一句话角色（不进入 spec，进入分析正文的说明）：\\n\\n```\\nchart-scale：本客群的规模底数\\nchart-tier：规模按资产层的分布，回答\\"集中在哪一档\\"\\n```\\n\\n写不出角色的图，删。\\n\\n## 去重规则\\n\\n- 同一份数据、同一意图 → 只保留表达力强的一张（一般是有序列/可对读的那张）。\\n- `table` 与图形表达同一数据时，只在\\"需要精确读数\\"时保留 table。\\n- KPI 与同数据的条形图并存没有意义——KPI 用于一个数，条形用于多类比较。\\n\\n## 图数上限\\n\\n- 单个分析结果建议 ≤6 张图（不含 KPI 行）。更多说明主线不清，先回退去重再裁剪。\\n- 平台层面的硬上限是 30（契约限制），但那是防御性上限，不是目标。\\n\\n## 叙事与图的关系\\n\\n- 正文写\\"论点\\"，图给\\"证据\\"：正文提到差异时，差异图紧随其后。\\n- 图题用业务语，主图可以用问句（\\"产品覆盖集中在哪一档？\\"）——问句图题引导读者带着问题看图。\\n- 任何图都必须能被正文引用（正文里说明它在讲什么）；正文没提到的图，要么补正文引用，要么删图。\\n\\n## 边界\\n\\n组合层不新增数据、不改 spec 内容（那是 chart-atomic 的职责）、不改变事实表。发现某张图与主线无关时，删图而不是改数据。\\n"}], "skill_md": "---\\nname: \\"chart-compose\\"\\ndescription: \\"把多张图表组织成一次分析的配图方案：按“KPI → 差异/趋势 → 结构/原因 → 明细/行动”的信息顺序排序，套用概览/诊断/行动三类版式，控制总图数与去重。分析结果产生两张以上图表、或需要成体系的仪表板时使用；单张图不需要本技能。用户不应直接调用本技能。\\"\\nargument-hint: \\"图表清单与分析主线\\"\\nuser-invocable: false\\ndisable-model-invocation: false\\nallowed-tools: [\\"Read\\", \\"Skill\\"]\\n---\\n\\n# 图表组合层\\n\\n一次分析的多张图不是并列的，而是一条**阅读主线**。组合层决定：出几张、什么顺序、谁是主图。\\n\\n## 工作步骤\\n\\n1. 收集本轮已有的图表 spec（来自 chart-intent / chart-atomic）与它们的意图。\\n2. 按 `references/dashboard-layout.md` 选版式（概览 / 诊断 / 行动），并按信息顺序排序。\\n3. 去重与裁剪：同一意图、同一数据的图只留一张；总图数按 `references/storytelling.md` 的规则控制。\\n4. 输出：**有序的图表清单**（按最终顺序列出各图 id + 一句话角色），供分析技能放进 `insight-result` 的 `charts` 数组。\\n\\n## 组合原则\\n\\n- **一篇一条主线**：先给结论性数字（KPI），再给支撑（对比/结构），最后给可行动对象（明细/漏斗）。读者从上往下读，逻辑不回头。\\n- **少而精**：每张图必须能回答\\"它在主线里承担什么\\";承担不了就删。\\n- **顺序即阅读顺序**：平台按 `charts` 数组顺序渲染（KPI 类单独置顶成行），不要依赖随机摆放。\\n\\n## 版式与图数的对应\\n\\n| 版式 | 适用 | 典型结构 | 图数 |\\n| --- | --- | --- | --- |\\n| 概览 | 客群是什么样 | KPI 规模 → 分布/构成 | 2~4 |\\n| 诊断 | 哪里异常、为什么 | KPI 差异 → 对比条形 → 下钻矩阵 | 2~5 |\\n| 行动 | 接下来做什么 | KPI 对象数 → 漏斗 → 明细 | 2~4 |\\n\\n单张图（含单 KPI）说明不需要组合层，直接输出即可。\\n"}', '{"name": "chart-compose", "display_name": "图表组合层", "description": "把多张图表组织成一次分析的配图方案：按“KPI → 差异/趋势 → 结构/原因 → 明细/行动”的信息顺序排序，套用概览/诊断/行动三类版式，控制总图数与去重。分析结果产生两张以上图表、或需要成体系的仪表板时使用；单张图不需要本技能。用户不应直接调用本技能。", "instructions": "# 图表组合层\\n\\n一次分析的多张图不是并列的，而是一条**阅读主线**。组合层决定：出几张、什么顺序、谁是主图。\\n\\n## 工作步骤\\n\\n1. 收集本轮已有的图表 spec（来自 chart-intent / chart-atomic）与它们的意图。\\n2. 按 `references/dashboard-layout.md` 选版式（概览 / 诊断 / 行动），并按信息顺序排序。\\n3. 去重与裁剪：同一意图、同一数据的图只留一张；总图数按 `references/storytelling.md` 的规则控制。\\n4. 输出：**有序的图表清单**（按最终顺序列出各图 id + 一句话角色），供分析技能放进 `insight-result` 的 `charts` 数组。\\n\\n## 组合原则\\n\\n- **一篇一条主线**：先给结论性数字（KPI），再给支撑（对比/结构），最后给可行动对象（明细/漏斗）。读者从上往下读，逻辑不回头。\\n- **少而精**：每张图必须能回答\\"它在主线里承担什么\\";承担不了就删。\\n- **顺序即阅读顺序**：平台按 `charts` 数组顺序渲染（KPI 类单独置顶成行），不要依赖随机摆放。\\n\\n## 版式与图数的对应\\n\\n| 版式 | 适用 | 典型结构 | 图数 |\\n| --- | --- | --- | --- |\\n| 概览 | 客群是什么样 | KPI 规模 → 分布/构成 | 2~4 |\\n| 诊断 | 哪里异常、为什么 | KPI 差异 → 对比条形 → 下钻矩阵 | 2~5 |\\n| 行动 | 接下来做什么 | KPI 对象数 → 漏斗 → 明细 | 2~4 |\\n\\n单张图（含单 KPI）说明不需要组合层，直接输出即可。", "argument_hint": "图表清单与分析主线", "version": "1.0.0", "category": "chart", "user_invocable": false, "disable_model_invocation": false, "allowed_tools": ["Read", "Skill"], "resources": [{"path": "references/dashboard-layout.md", "content": "# 仪表板版式\\n\\n三类版式对应三步分析链路。版式不是\\"模板套壳\\"，而是把信息顺序固化成读者熟悉的节奏。\\n\\n## 概览版式（客户是什么样）\\n\\n```\\n[KPI 行]  客群规模等 1~3 个关键数\\n[结构/分布]  1~2 张（分布柱状 / 构成堆叠）\\n[明细]  可选 1 张 table\\n```\\n\\n适用：fact-analysis 的产出配图。\\n\\n## 诊断版式（哪里值得关注）\\n\\n```\\n[KPI 行]  核心差异值（pp / 元），没有基准时不放\\n[对比]  客群 vs 基准的条形图\\n[下钻]  差异集中方向的矩阵或分组条形\\n```\\n\\n适用：diagnostic-analysis。差异图放在对比图之后，形成\\"先看差异、再看它集中在哪\\"的阅读路径。\\n\\n## 行动版式（接下来做什么）\\n\\n```\\n[KPI 行]  可执行对象数（没有规则链时省略）\\n[漏斗]  候选 → 过滤 → 可执行的逐层收窄\\n[明细]  优先级分布 table\\n```\\n\\n适用：action-decision。\\n\\n## 信息顺序（总原则）\\n\\n```\\nKPI（结论性数字）\\n   ↓\\n差异 / 趋势（和谁比、变化方向）\\n   ↓\\n结构 / 原因（由什么构成、集中在哪里）\\n   ↓\\n明细 / 行动对象（要做什么、从谁开始）\\n```\\n\\n任何版式都遵守这个从上到下的抽象度递减。把明细放最上面会让读者先陷入细节。\\n\\n## 平台渲染约定\\n\\n- `kind=\\"kpi\\"` 的图由面板统一置顶成 KPI 行，其余按 `charts` 数组顺序排列——KPI 在数组里的位置不影响展示，但为可读性仍放最前。\\n- 每张图有独立的标题与导出按钮；标题应能脱离上下文单独看懂（\\"产品持有率对比\\"而不是\\"对比图\\"）。\\n"}, {"path": "references/storytelling.md", "content": "# 数据故事规则\\n\\n## 每张图的角色声明\\n\\n组合时给每张图写一句话角色（不进入 spec，进入分析正文的说明）：\\n\\n```\\nchart-scale：本客群的规模底数\\nchart-tier：规模按资产层的分布，回答\\"集中在哪一档\\"\\n```\\n\\n写不出角色的图，删。\\n\\n## 去重规则\\n\\n- 同一份数据、同一意图 → 只保留表达力强的一张（一般是有序列/可对读的那张）。\\n- `table` 与图形表达同一数据时，只在\\"需要精确读数\\"时保留 table。\\n- KPI 与同数据的条形图并存没有意义——KPI 用于一个数，条形用于多类比较。\\n\\n## 图数上限\\n\\n- 单个分析结果建议 ≤6 张图（不含 KPI 行）。更多说明主线不清，先回退去重再裁剪。\\n- 平台层面的硬上限是 30（契约限制），但那是防御性上限，不是目标。\\n\\n## 叙事与图的关系\\n\\n- 正文写\\"论点\\"，图给\\"证据\\"：正文提到差异时，差异图紧随其后。\\n- 图题用业务语，主图可以用问句（\\"产品覆盖集中在哪一档？\\"）——问句图题引导读者带着问题看图。\\n- 任何图都必须能被正文引用（正文里说明它在讲什么）；正文没提到的图，要么补正文引用，要么删图。\\n\\n## 边界\\n\\n组合层不新增数据、不改 spec 内容（那是 chart-atomic 的职责）、不改变事实表。发现某张图与主线无关时，删图而不是改数据。\\n"}], "skill_md": "---\\nname: \\"chart-compose\\"\\ndescription: \\"把多张图表组织成一次分析的配图方案：按“KPI → 差异/趋势 → 结构/原因 → 明细/行动”的信息顺序排序，套用概览/诊断/行动三类版式，控制总图数与去重。分析结果产生两张以上图表、或需要成体系的仪表板时使用；单张图不需要本技能。用户不应直接调用本技能。\\"\\nargument-hint: \\"图表清单与分析主线\\"\\nuser-invocable: false\\ndisable-model-invocation: false\\nallowed-tools: [\\"Read\\", \\"Skill\\"]\\n---\\n\\n# 图表组合层\\n\\n一次分析的多张图不是并列的，而是一条**阅读主线**。组合层决定：出几张、什么顺序、谁是主图。\\n\\n## 工作步骤\\n\\n1. 收集本轮已有的图表 spec（来自 chart-intent / chart-atomic）与它们的意图。\\n2. 按 `references/dashboard-layout.md` 选版式（概览 / 诊断 / 行动），并按信息顺序排序。\\n3. 去重与裁剪：同一意图、同一数据的图只留一张；总图数按 `references/storytelling.md` 的规则控制。\\n4. 输出：**有序的图表清单**（按最终顺序列出各图 id + 一句话角色），供分析技能放进 `insight-result` 的 `charts` 数组。\\n\\n## 组合原则\\n\\n- **一篇一条主线**：先给结论性数字（KPI），再给支撑（对比/结构），最后给可行动对象（明细/漏斗）。读者从上往下读，逻辑不回头。\\n- **少而精**：每张图必须能回答\\"它在主线里承担什么\\";承担不了就删。\\n- **顺序即阅读顺序**：平台按 `charts` 数组顺序渲染（KPI 类单独置顶成行），不要依赖随机摆放。\\n\\n## 版式与图数的对应\\n\\n| 版式 | 适用 | 典型结构 | 图数 |\\n| --- | --- | --- | --- |\\n| 概览 | 客群是什么样 | KPI 规模 → 分布/构成 | 2~4 |\\n| 诊断 | 哪里异常、为什么 | KPI 差异 → 对比条形 → 下钻矩阵 | 2~5 |\\n| 行动 | 接下来做什么 | KPI 对象数 → 漏斗 → 明细 | 2~4 |\\n\\n单张图（含单 KPI）说明不需要组合层，直接输出即可。\\n"}', 1, 'seed', 'seed', NOW(), NOW(), NOW())
ON DUPLICATE KEY UPDATE draft_json=VALUES(draft_json), published_json=VALUES(published_json),
  row_version=row_version+1, update_by='seed', update_time=NOW(), publish_time=NOW();

INSERT INTO ts_agent_skill (name, draft_json, published_json, row_version, create_by, update_by, create_time, update_time, publish_time)
VALUES ('chart-intent', '{"name": "chart-intent", "display_name": "图表意图层", "description": "为分析结果自动配图：读取数据画像，先判断“要表达什么”（意图），再决定画不画、画哪张，并调用 chart-atomic 产出合法图表 spec。分析技能产出事实卡后需要配图时使用；数据不足时应输出空图表列表并说明原因，不要为凑图而画。用户不应直接调用本技能。", "instructions": "# 图表意图层\\n\\n图表不是\\"美化\\"，是表达。\\"选图\\"的本质是先定**意图**（想说什么），再交给 chart-atomic 实现。\\n\\n## 工作步骤\\n\\n1. **数据画像**：列出可用事实（AVAILABLE，满足样本规则）与缺失事实；数一数类别数、系列数、是否有分母、是否能对账。\\n2. **定意图**：按 `references/intent-taxonomy.md` 从六种意图中选 1 种（多张图各自定意图）。\\n3. **可画性判定**：按 `references/fallback-rules.md` 检查——不满足就降级或放弃这张图。宁缺毋滥：**没有可信数据时的正确产出是 `charts: []`**，并在正文说明原因。\\n4. **产出 spec**：调用 **chart-atomic** 技能（Skill 工具），把数据画像、意图和事实 id 交给它，由它按协议编译 spec。\\n5. 回到分析技能：把 spec 数组放进最终 `insight-result` 块的 `charts` 字段。\\n\\n## 配图原则\\n\\n- 每张图只服务一个意图；同一份数据既有对比又想看结构，就画两张（交给 chart-compose 排序）。\\n- 图表必须能被事实复算：图上每个数字都能在 `facts` 表里找到同一数值。做不到就不画。\\n- 抑制与缺失是数据的一部分：样本不足的格子用\\"已抑制\\"呈现（`value: null`），不要用 0 或省略来掩盖。\\n- 是否配图服从表达需要：只有一个人数事实时，KPI 是合适的；把它画成柱状图反而喧宾夺主。\\n\\n## 与相邻技能的关系\\n\\n- 分析技能（fact/diagnostic/action）产生事实与叙述 → 本技能决定图表方案 → chart-atomic 编译 spec → chart-compose 组合成仪表板顺序。", "argument_hint": "事实列表与想表达的重点（可留空）", "version": "1.0.0", "category": "chart", "user_invocable": false, "disable_model_invocation": false, "allowed_tools": ["Read", "Skill"], "resources": [{"path": "references/chart-selection.md", "content": "# 选图规则\\n\\n意图确定后的具体选图与结构化规则。\\n\\n## 按意图选图\\n\\n| intent | 首选 | 备选 | 升级为备选的条件 |\\n| --- | --- | --- | --- |\\n| `single_value` | kpi | table | 需要同时看多个单值时，拆多张 KPI 或一张 table（table 非矩阵，`column` 必须为 null） |\\n| `compare_categories` | bar | table | 类别 >12 或需要精确读数时用 table/截断 |\\n| `show_composition` | stacked_bar | table | 各组不可加、或有抑制格子时降级 |\\n| `show_distribution` | bar | table | 分箱需要精确读值时用 table |\\n| `show_matrix` | heatmap | table | 只有一维数据时降级为 bar |\\n| `show_conversion` | funnel | table | 不单调或各层口径不一致时禁止漏斗，改文字说明 |\\n\\n## 方向与排序\\n\\n- 类别名多为中文长词（\\"个人养老金\\"、\\"结构性存款\\"）→ `horizontal`。\\n- 强调排名 → 按数值排序；强调固有顺序（时间、层级）→ 保持自然顺序。\\n- 排序变化要在说明里写明（\\"按降序排列\\"）。\\n\\n## 规模约束（与守卫一致）\\n\\n- 类别 ≤12、系列 ≤8、格子 ≤100/系列、标注 ≤8。\\n- 超限的处理顺序：① 截断到业务最关键的类别并说明；② 降级为 table；③ 不画。\\n\\n## 百分比结构\\n\\n占比堆叠要求：每个类别一条 `percentage` 对账（引用该类别全部格子，合计 100）。如果某项占比没有分母事实，就不要把它放进堆叠——换成绝对量（人）的堆叠或删除该项。\\n\\n## 漏斗\\n\\n只在以下全部成立时画：\\n\\n1. 每一层人数都是 AVAILABLE 事实（同一口径）；\\n2. 逐层单调不增；\\n3. 有一条 `funnel` 对账与展示顺序完全一致。\\n\\n任何一层靠推算（\\"约 xxx 人\\"）→ 不画漏斗。\\n"}, {"path": "references/fallback-rules.md", "content": "# 降级与不配图\\n\\n## 判定顺序\\n\\n对每张候选图按顺序检查，第一个不通过就执行对应降级：\\n\\n1. **有事实吗？** 相关指标全部 MISSING → 不画，正文说明缺口。\\n2. **事实可用吗？** 事实 AVAILABLE 但 `sample_size` <20（或人数 <20）→ 该格抑制；若整张图都抑制 → 不画。\\n3. **类别/系列超限吗？** >12 类别或 >8 系列 → 截断并说明，或改 table。\\n4. **能对账吗？** 构成/漏斗类对不上账 → 降级为 table 或删图。\\n5. **意图清楚吗？** 说不清\\"这张图想表达什么\\" → 不画。\\n\\n## 各意图的典型降级\\n\\n| 场景 | 处理 |\\n| --- | --- |\\n| 只有一个数据点 | kpi；若连 kpi 都不合适（如类别名不明确）→ 不画 |\\n| 有一个 AVAILABLE 人数 + 一堆 MISSING | 只画 KPI（人数），其余在正文声明缺失 |\\n| 分布数据有抑制格子 | 保留抑制占位（`value: null`），整图仍可画 |\\n| 全部的类别都被抑制（样本小） | 不画 |\\n| 比例缺分母 | 不画占比图；改绝对量或删 |\\n| 漏斗某层缺失 | 不画漏斗 |\\n\\n## 输出契约\\n\\n- 可画：产出 spec（经 chart-atomic），并说明每张图\\"表达什么 + 有什么未展示\\"。\\n- 不画：`charts` 为 `[]`，在 `reasons` 与正文里写明**为什么不出图**（数据缺失/样本不足/无法对账），并给出补齐路径（followups）。\\n\\n## 为什么宁缺毋滥\\n\\n图表比文字更容易被当成结论。一张建立在缺失数据上的图，会让读者忽略正文里的边界声明。平台上\\"本次不配图 + 说明原因\\"是合格产出，\\"勉强的图\\"是不合格产出。\\n"}, {"path": "references/intent-taxonomy.md", "content": "# 意图分类\\n\\n六种图表意图，与图形（kind）一一对应（table 例外，可承载任意意图）：\\n\\n| intent | 想表达 | kind | 典型数据 |\\n| --- | --- | --- | --- |\\n| `single_value` | 一个关键数字 | kpi | 客群规模、可执行对象数 |\\n| `compare_categories` | 类别之间的高低 | bar | 各产品持有率、各机构客户数 |\\n| `show_composition` | 整体由什么构成 | stacked_bar | 资产构成（活期/定期/投资） |\\n| `show_distribution` | 数值在区间上的分布 | bar | AUM 分层人数 |\\n| `show_matrix` | 两个维度的交叉格局 | heatmap | AUM 段 × 风险等级 |\\n| `show_conversion` | 逐层收窄的转化 | funnel | 行动漏斗（候选→适当性→排除→可执行） |\\n\\n## 意图判断问句\\n\\n按顺序自问，命中即停：\\n\\n1. 「我要强调的是一件事的**一个数**吗？」→ `single_value`\\n2. 「我在**比大小**吗？」（谁高谁低、排名）→ `compare_categories`\\n3. 「我在说**一部分占整体**吗？」（占比、构成）→ `show_composition`\\n4. 「我在看**分布形态**吗？」（集中在哪段、长尾）→ `show_distribution`\\n5. 「我要同时看**两个维度**吗？」（谁和谁交叉最突出）→ `show_matrix`\\n6. 「我在讲**一条链路**吗？」（每一层剩下多少人）→ `show_conversion`\\n\\n## 意图纪律\\n\\n- 意图是\\"表达什么\\"，不是\\"数据长什么样\\"：同一份分层数据，强调分布用 `show_distribution`，强调占比构成用 `show_composition`——先想清楚要传达的信息。\\n- 一张图只选一个意图；表达不清就不要配图。\\n- 分布 vs 构成的自查：各格相加等于整体 → 构成；各格是互斥分箱的绝对量 → 分布。\\n"}], "skill_md": "---\\nname: \\"chart-intent\\"\\ndescription: \\"为分析结果自动配图：读取数据画像，先判断“要表达什么”（意图），再决定画不画、画哪张，并调用 chart-atomic 产出合法图表 spec。分析技能产出事实卡后需要配图时使用；数据不足时应输出空图表列表并说明原因，不要为凑图而画。用户不应直接调用本技能。\\"\\nargument-hint: \\"事实列表与想表达的重点（可留空）\\"\\nuser-invocable: false\\ndisable-model-invocation: false\\nallowed-tools: [\\"Read\\", \\"Skill\\"]\\n---\\n\\n# 图表意图层\\n\\n图表不是\\"美化\\"，是表达。\\"选图\\"的本质是先定**意图**（想说什么），再交给 chart-atomic 实现。\\n\\n## 工作步骤\\n\\n1. **数据画像**：列出可用事实（AVAILABLE，满足样本规则）与缺失事实；数一数类别数、系列数、是否有分母、是否能对账。\\n2. **定意图**：按 `references/intent-taxonomy.md` 从六种意图中选 1 种（多张图各自定意图）。\\n3. **可画性判定**：按 `references/fallback-rules.md` 检查——不满足就降级或放弃这张图。宁缺毋滥：**没有可信数据时的正确产出是 `charts: []`**，并在正文说明原因。\\n4. **产出 spec**：调用 **chart-atomic** 技能（Skill 工具），把数据画像、意图和事实 id 交给它，由它按协议编译 spec。\\n5. 回到分析技能：把 spec 数组放进最终 `insight-result` 块的 `charts` 字段。\\n\\n## 配图原则\\n\\n- 每张图只服务一个意图；同一份数据既有对比又想看结构，就画两张（交给 chart-compose 排序）。\\n- 图表必须能被事实复算：图上每个数字都能在 `facts` 表里找到同一数值。做不到就不画。\\n- 抑制与缺失是数据的一部分：样本不足的格子用\\"已抑制\\"呈现（`value: null`），不要用 0 或省略来掩盖。\\n- 是否配图服从表达需要：只有一个人数事实时，KPI 是合适的；把它画成柱状图反而喧宾夺主。\\n\\n## 与相邻技能的关系\\n\\n- 分析技能（fact/diagnostic/action）产生事实与叙述 → 本技能决定图表方案 → chart-atomic 编译 spec → chart-compose 组合成仪表板顺序。\\n"}', '{"name": "chart-intent", "display_name": "图表意图层", "description": "为分析结果自动配图：读取数据画像，先判断“要表达什么”（意图），再决定画不画、画哪张，并调用 chart-atomic 产出合法图表 spec。分析技能产出事实卡后需要配图时使用；数据不足时应输出空图表列表并说明原因，不要为凑图而画。用户不应直接调用本技能。", "instructions": "# 图表意图层\\n\\n图表不是\\"美化\\"，是表达。\\"选图\\"的本质是先定**意图**（想说什么），再交给 chart-atomic 实现。\\n\\n## 工作步骤\\n\\n1. **数据画像**：列出可用事实（AVAILABLE，满足样本规则）与缺失事实；数一数类别数、系列数、是否有分母、是否能对账。\\n2. **定意图**：按 `references/intent-taxonomy.md` 从六种意图中选 1 种（多张图各自定意图）。\\n3. **可画性判定**：按 `references/fallback-rules.md` 检查——不满足就降级或放弃这张图。宁缺毋滥：**没有可信数据时的正确产出是 `charts: []`**，并在正文说明原因。\\n4. **产出 spec**：调用 **chart-atomic** 技能（Skill 工具），把数据画像、意图和事实 id 交给它，由它按协议编译 spec。\\n5. 回到分析技能：把 spec 数组放进最终 `insight-result` 块的 `charts` 字段。\\n\\n## 配图原则\\n\\n- 每张图只服务一个意图；同一份数据既有对比又想看结构，就画两张（交给 chart-compose 排序）。\\n- 图表必须能被事实复算：图上每个数字都能在 `facts` 表里找到同一数值。做不到就不画。\\n- 抑制与缺失是数据的一部分：样本不足的格子用\\"已抑制\\"呈现（`value: null`），不要用 0 或省略来掩盖。\\n- 是否配图服从表达需要：只有一个人数事实时，KPI 是合适的；把它画成柱状图反而喧宾夺主。\\n\\n## 与相邻技能的关系\\n\\n- 分析技能（fact/diagnostic/action）产生事实与叙述 → 本技能决定图表方案 → chart-atomic 编译 spec → chart-compose 组合成仪表板顺序。", "argument_hint": "事实列表与想表达的重点（可留空）", "version": "1.0.0", "category": "chart", "user_invocable": false, "disable_model_invocation": false, "allowed_tools": ["Read", "Skill"], "resources": [{"path": "references/chart-selection.md", "content": "# 选图规则\\n\\n意图确定后的具体选图与结构化规则。\\n\\n## 按意图选图\\n\\n| intent | 首选 | 备选 | 升级为备选的条件 |\\n| --- | --- | --- | --- |\\n| `single_value` | kpi | table | 需要同时看多个单值时，拆多张 KPI 或一张 table（table 非矩阵，`column` 必须为 null） |\\n| `compare_categories` | bar | table | 类别 >12 或需要精确读数时用 table/截断 |\\n| `show_composition` | stacked_bar | table | 各组不可加、或有抑制格子时降级 |\\n| `show_distribution` | bar | table | 分箱需要精确读值时用 table |\\n| `show_matrix` | heatmap | table | 只有一维数据时降级为 bar |\\n| `show_conversion` | funnel | table | 不单调或各层口径不一致时禁止漏斗，改文字说明 |\\n\\n## 方向与排序\\n\\n- 类别名多为中文长词（\\"个人养老金\\"、\\"结构性存款\\"）→ `horizontal`。\\n- 强调排名 → 按数值排序；强调固有顺序（时间、层级）→ 保持自然顺序。\\n- 排序变化要在说明里写明（\\"按降序排列\\"）。\\n\\n## 规模约束（与守卫一致）\\n\\n- 类别 ≤12、系列 ≤8、格子 ≤100/系列、标注 ≤8。\\n- 超限的处理顺序：① 截断到业务最关键的类别并说明；② 降级为 table；③ 不画。\\n\\n## 百分比结构\\n\\n占比堆叠要求：每个类别一条 `percentage` 对账（引用该类别全部格子，合计 100）。如果某项占比没有分母事实，就不要把它放进堆叠——换成绝对量（人）的堆叠或删除该项。\\n\\n## 漏斗\\n\\n只在以下全部成立时画：\\n\\n1. 每一层人数都是 AVAILABLE 事实（同一口径）；\\n2. 逐层单调不增；\\n3. 有一条 `funnel` 对账与展示顺序完全一致。\\n\\n任何一层靠推算（\\"约 xxx 人\\"）→ 不画漏斗。\\n"}, {"path": "references/fallback-rules.md", "content": "# 降级与不配图\\n\\n## 判定顺序\\n\\n对每张候选图按顺序检查，第一个不通过就执行对应降级：\\n\\n1. **有事实吗？** 相关指标全部 MISSING → 不画，正文说明缺口。\\n2. **事实可用吗？** 事实 AVAILABLE 但 `sample_size` <20（或人数 <20）→ 该格抑制；若整张图都抑制 → 不画。\\n3. **类别/系列超限吗？** >12 类别或 >8 系列 → 截断并说明，或改 table。\\n4. **能对账吗？** 构成/漏斗类对不上账 → 降级为 table 或删图。\\n5. **意图清楚吗？** 说不清\\"这张图想表达什么\\" → 不画。\\n\\n## 各意图的典型降级\\n\\n| 场景 | 处理 |\\n| --- | --- |\\n| 只有一个数据点 | kpi；若连 kpi 都不合适（如类别名不明确）→ 不画 |\\n| 有一个 AVAILABLE 人数 + 一堆 MISSING | 只画 KPI（人数），其余在正文声明缺失 |\\n| 分布数据有抑制格子 | 保留抑制占位（`value: null`），整图仍可画 |\\n| 全部的类别都被抑制（样本小） | 不画 |\\n| 比例缺分母 | 不画占比图；改绝对量或删 |\\n| 漏斗某层缺失 | 不画漏斗 |\\n\\n## 输出契约\\n\\n- 可画：产出 spec（经 chart-atomic），并说明每张图\\"表达什么 + 有什么未展示\\"。\\n- 不画：`charts` 为 `[]`，在 `reasons` 与正文里写明**为什么不出图**（数据缺失/样本不足/无法对账），并给出补齐路径（followups）。\\n\\n## 为什么宁缺毋滥\\n\\n图表比文字更容易被当成结论。一张建立在缺失数据上的图，会让读者忽略正文里的边界声明。平台上\\"本次不配图 + 说明原因\\"是合格产出，\\"勉强的图\\"是不合格产出。\\n"}, {"path": "references/intent-taxonomy.md", "content": "# 意图分类\\n\\n六种图表意图，与图形（kind）一一对应（table 例外，可承载任意意图）：\\n\\n| intent | 想表达 | kind | 典型数据 |\\n| --- | --- | --- | --- |\\n| `single_value` | 一个关键数字 | kpi | 客群规模、可执行对象数 |\\n| `compare_categories` | 类别之间的高低 | bar | 各产品持有率、各机构客户数 |\\n| `show_composition` | 整体由什么构成 | stacked_bar | 资产构成（活期/定期/投资） |\\n| `show_distribution` | 数值在区间上的分布 | bar | AUM 分层人数 |\\n| `show_matrix` | 两个维度的交叉格局 | heatmap | AUM 段 × 风险等级 |\\n| `show_conversion` | 逐层收窄的转化 | funnel | 行动漏斗（候选→适当性→排除→可执行） |\\n\\n## 意图判断问句\\n\\n按顺序自问，命中即停：\\n\\n1. 「我要强调的是一件事的**一个数**吗？」→ `single_value`\\n2. 「我在**比大小**吗？」（谁高谁低、排名）→ `compare_categories`\\n3. 「我在说**一部分占整体**吗？」（占比、构成）→ `show_composition`\\n4. 「我在看**分布形态**吗？」（集中在哪段、长尾）→ `show_distribution`\\n5. 「我要同时看**两个维度**吗？」（谁和谁交叉最突出）→ `show_matrix`\\n6. 「我在讲**一条链路**吗？」（每一层剩下多少人）→ `show_conversion`\\n\\n## 意图纪律\\n\\n- 意图是\\"表达什么\\"，不是\\"数据长什么样\\"：同一份分层数据，强调分布用 `show_distribution`，强调占比构成用 `show_composition`——先想清楚要传达的信息。\\n- 一张图只选一个意图；表达不清就不要配图。\\n- 分布 vs 构成的自查：各格相加等于整体 → 构成；各格是互斥分箱的绝对量 → 分布。\\n"}], "skill_md": "---\\nname: \\"chart-intent\\"\\ndescription: \\"为分析结果自动配图：读取数据画像，先判断“要表达什么”（意图），再决定画不画、画哪张，并调用 chart-atomic 产出合法图表 spec。分析技能产出事实卡后需要配图时使用；数据不足时应输出空图表列表并说明原因，不要为凑图而画。用户不应直接调用本技能。\\"\\nargument-hint: \\"事实列表与想表达的重点（可留空）\\"\\nuser-invocable: false\\ndisable-model-invocation: false\\nallowed-tools: [\\"Read\\", \\"Skill\\"]\\n---\\n\\n# 图表意图层\\n\\n图表不是\\"美化\\"，是表达。\\"选图\\"的本质是先定**意图**（想说什么），再交给 chart-atomic 实现。\\n\\n## 工作步骤\\n\\n1. **数据画像**：列出可用事实（AVAILABLE，满足样本规则）与缺失事实；数一数类别数、系列数、是否有分母、是否能对账。\\n2. **定意图**：按 `references/intent-taxonomy.md` 从六种意图中选 1 种（多张图各自定意图）。\\n3. **可画性判定**：按 `references/fallback-rules.md` 检查——不满足就降级或放弃这张图。宁缺毋滥：**没有可信数据时的正确产出是 `charts: []`**，并在正文说明原因。\\n4. **产出 spec**：调用 **chart-atomic** 技能（Skill 工具），把数据画像、意图和事实 id 交给它，由它按协议编译 spec。\\n5. 回到分析技能：把 spec 数组放进最终 `insight-result` 块的 `charts` 字段。\\n\\n## 配图原则\\n\\n- 每张图只服务一个意图；同一份数据既有对比又想看结构，就画两张（交给 chart-compose 排序）。\\n- 图表必须能被事实复算：图上每个数字都能在 `facts` 表里找到同一数值。做不到就不画。\\n- 抑制与缺失是数据的一部分：样本不足的格子用\\"已抑制\\"呈现（`value: null`），不要用 0 或省略来掩盖。\\n- 是否配图服从表达需要：只有一个人数事实时，KPI 是合适的；把它画成柱状图反而喧宾夺主。\\n\\n## 与相邻技能的关系\\n\\n- 分析技能（fact/diagnostic/action）产生事实与叙述 → 本技能决定图表方案 → chart-atomic 编译 spec → chart-compose 组合成仪表板顺序。\\n"}', 1, 'seed', 'seed', NOW(), NOW(), NOW())
ON DUPLICATE KEY UPDATE draft_json=VALUES(draft_json), published_json=VALUES(published_json),
  row_version=row_version+1, update_by='seed', update_time=NOW(), publish_time=NOW();
